dotnetSource "LawSpec.Runtime/Actors.fs" = "/// Actors and supervision trees on .NET. A handle names a stable mailbox, not\n/// a worker: a supervised restart replaces the worker and keeps the committed\n/// checkpoint and the messages waiting. Each actor handles one message at a\n/// time; a handler that returns commits its next state before the reply, and\n/// one that throws commits nothing. Supervisors restart their children by\n/// strategy (one for one, one for all, rest for one) and lifetime (permanent,\n/// transient, temporary) within a rolling restart budget, and escalate to\n/// their own supervisor when it is spent. ref:DEC-actors-otp-supervision\n/// ref:erlang-otp-supervisors ref:DEC-fsharp-runtime-from-scratch\nmodule LawSpec.Runtime.Actors\n\nopen System\nopen System.Diagnostics\nopen System.Threading\nopen System.Threading.Tasks\n\n/// When a supervisor restarts a child that stopped.\ntype Lifetime =\n    /// Always.\n    | Permanent\n    /// Only after a crash.\n    | Transient\n    /// Never.\n    | Temporary\n\n/// Which children a supervisor restarts when one fails.\ntype Strategy =\n    | OneForOne\n    | OneForAll\n    | RestForOne\n\n/// What a tree runs: an actor (its start and its restart from the last\n/// checkpoint) or a supervisor of named children.\n[<NoEquality; NoComparison>]\ntype Spec =\n    | ActorSpec of start: (unit -> obj) * restart: (obj -> obj) * metadata: obj\n    | SupervisorSpec of strategy: Strategy * restarts: int * periodMicros: int64 * children: (string * Lifetime * Spec) list * metadata: obj\n\n/// What an observer is told about a handle.\n[<NoEquality; NoComparison>]\ntype Event =\n    | Crashed of cause: exn\n    | Stopped\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\ntype internal Operation =\n    | Run of (obj -> obj * obj)\n    | Crash of cause: exn * origin: obj\n    | Restart\n    | Stop\n\n[<NoEquality; NoComparison>]\ntype internal Entry =\n    { Reply: TaskCompletionSource<obj> option\n      Operation: Operation\n      Context: ExecutionContext option }\n\n/// A mailbox of events from the handles it monitors, received selectively.\n[<Sealed; AllowNullLiteral>]\ntype Inbox() =\n    let events = ResizeArray<obj * Event>()\n    let gate = obj ()\n    member internal _.Post(handle: obj, event: Event) =\n        lock gate (fun () ->\n            events.Add((handle, event))\n            Monitor.PulseAll gate)\n    /// The next event of a handle, waiting at most a number of milliseconds.\n    member _.Receive(handle: obj, milliseconds: int) : Event option =\n        let deadline = Stopwatch.GetTimestamp() + int64 milliseconds * Stopwatch.Frequency / 1000L\n        lock gate (fun () ->\n            let rec loop () =\n                match events |> Seq.tryFindIndex (fun (h, _) -> h.Equals handle) with\n                | Some i ->\n                    let _, event = events.[i]\n                    events.RemoveAt i\n                    Some event\n                | None ->\n                    let left = deadline - Stopwatch.GetTimestamp()\n                    if left <= 0L then None\n                    else\n                        Monitor.Wait(gate, TimeSpan.FromTicks(max 1L (left * TimeSpan.TicksPerSecond / Stopwatch.Frequency))) |> ignore\n                        loop ()\n            loop ())\n\n[<AllowNullLiteral>]\ntype internal Node(path: string list, spec: Spec, parent: string list option, lifetime: Lifetime) =\n    member val Path = path\n    member val Spec = spec\n    member val Parent = parent\n    member val Lifetime = lifetime\n    member val Children: (string * string list) list = [] with get, set\n    member val State: obj = null with get, set\n    member val Checkpoint: obj option = None with get, set\n    /// Run start, or restart from the checkpoint, before the next message.\n    member val Init = false with get, set\n    member val Worker = 0 with get, set\n    /// Which incarnation of the worker runs: a restart makes a new one.\n    member val Incarnation = 0 with get, set\n    member val Waiting = System.Collections.Generic.Queue<Entry>() with get\n    member val Active: Entry option = None with get, set\n    member val Running = false with get, set\n    member val Accepting = true with get, set\n    member val Removed = false with get, set\n    member val Observers: Inbox list = [] with get, set\n    member val Links: Handle list = [] with get, set\n    member val Seen = System.Collections.Generic.HashSet<obj>(HashIdentity.Reference) with get\n    member val Restarts: int64 list = [] with get, set\n    member val StopNotified = false with get, set\n    member _.IsActor = match spec with ActorSpec _ -> true | _ -> false\n\n/// A stable handle on an actor or a supervisor of a tree.\nand [<CustomEquality; NoComparison>] Handle =\n    internal { Tree: Tree; Path: string list }\n    override this.Equals other =\n        match other with\n        | :? Handle as h -> obj.ReferenceEquals(this.Tree, h.Tree) && this.Path = h.Path\n        | _ -> false\n    override this.GetHashCode() = hash this.Path ^^^ Runtime.CompilerServices.RuntimeHelpers.GetHashCode this.Tree\n    override this.ToString() = \"actor \" + String.Join(\"/\", this.Path)\n\n/// The tree of one started spec: its nodes, under one lock. No application\n/// code runs under the lock.\nand [<Sealed; AllowNullLiteral>] Tree internal (context: ExecutionContext) =\n    let gate = obj ()\n    let nodes = System.Collections.Generic.Dictionary<string list, Node>(HashIdentity.Structural)\n    member internal _.Gate = gate\n    member internal _.Nodes = nodes\n    member internal _.Context = context\n\nlet private current = new ThreadLocal<Node>()\n\nlet private now () = Stopwatch.GetTimestamp() * 1_000_000L / Stopwatch.Frequency\n\nlet private stopped () : exn = LawSpecException(\"ActorStopped\", \"the actor has stopped\") :> exn\n\nlet private crashed (cause: exn) : exn = LawSpecException(\"ActorCrashed\", cause.Message, [], cause) :> exn\n\nlet private reply (entry: Entry) (result: Choice<obj, exn>) =\n    match entry.Reply with\n    | Some r ->\n        match result with\n        | Choice1Of2 v -> r.TrySetResult v |> ignore\n        | Choice2Of2 e -> r.TrySetException e |> ignore\n    | None -> ()\n\nlet private node (tree: Tree) path = tree.Nodes.[path]\n\nlet rec private descendants (tree: Tree) path : string list list =\n    path :: ((node tree path).Children |> List.collect (fun (_, child) -> descendants tree child))\n\nlet private notify (tree: Tree) (n: Node) (event: Event) =\n    for inbox in n.Observers do\n        inbox.Post(box { Tree = tree; Path = n.Path }, event)\n\nlet private eligible (n: Node) = not n.Removed\n\n/// Mark a subtree gone: every waiting caller is told the actor stopped.\nlet private halt (tree: Tree) path =\n    for p in List.rev (descendants tree path) do\n        let n = node tree p\n        if not n.Removed then\n            n.Active |> Option.iter (fun e -> reply e (Choice2Of2(stopped ())))\n            for e in n.Waiting do reply e (Choice2Of2(stopped ()))\n            n.Waiting.Clear()\n            if not n.StopNotified then notify tree n Stopped\n            n.Removed <- true\n            n.Accepting <- false\n            n.Active <- None\n            n.StopNotified <- true\n            n.Worker <- n.Worker + 1\n\nlet rec private schedule (tree: Tree) (n: Node) =\n    if not n.Running && not n.Removed && n.IsActor && (n.Init || n.Waiting.Count > 0) then\n        n.Running <- true\n        let generation = n.Worker\n        ThreadPool.QueueUserWorkItem(fun _ -> pump tree n generation) |> ignore\n\n/// A supervisor restarts a group of its children: the failed actor starts\n/// again from its checkpoint before its next message; every other actor\n/// restarts after the messages it had already accepted.\nand private restartGroup (tree: Tree) parent failed (origin: string list) =\n    let supervisor = node tree parent\n    let live = supervisor.Children |> List.map snd |> List.filter (fun c -> not (node tree c).Removed)\n    let group =\n        match supervisor.Spec with\n        | SupervisorSpec(OneForOne, _, _, _, _) -> [ failed ]\n        | SupervisorSpec(OneForAll, _, _, _, _) -> live\n        | SupervisorSpec(RestForOne, _, _, _, _) -> live |> List.skipWhile (fun c -> c <> failed)\n        | ActorSpec _ -> [ failed ]\n    for member' in group do\n        if (node tree member').Lifetime = Temporary then halt tree member'\n        else\n            for p in descendants tree member' do\n                let n = node tree p\n                if not n.Removed then\n                    n.Accepting <- true\n                    n.Incarnation <- n.Incarnation + 1\n                    if n.IsActor then\n                        if p = origin then n.Init <- true\n                        else n.Waiting.Enqueue { Reply = None; Operation = Restart; Context = None }\n                        schedule tree n\n                    else n.Restarts <- []\n\n/// Decide what a stop (normal) or crash (abnormal) means: a restart within the\n/// parent's budget, an escalation, or the end of the subtree.\nand private decide (tree: Tree) path (abnormal: bool) (origin: string list) =\n    let n = node tree path\n    let restart = eligible n && (n.Lifetime = Permanent || (n.Lifetime = Transient && abnormal))\n    match n.Parent with\n    | Some parent when restart ->\n        let supervisor = node tree parent\n        match supervisor.Spec with\n        | SupervisorSpec(_, limit, period, _, _) ->\n            let at = now ()\n            let recent = supervisor.Restarts |> List.filter (fun t -> at - t <= period)\n            if List.length recent < limit && eligible supervisor then\n                supervisor.Restarts <- recent @ [ at ]\n                restartGroup tree parent path origin\n            else decide tree parent true origin\n        | ActorSpec _ -> halt tree path\n    | _ ->\n        if not n.IsActor && abnormal then\n            notify tree n (Crashed(LawSpecException(\"RestartLimit\", String.Join(\"/\", path)) :> exn))\n            n.StopNotified <- true\n        halt tree path\n\n/// An actor failed: its caller learns why, its observers and linked actors\n/// are told, and its supervisor decides.\nand private failed (tree: Tree) (n: Node) (entry: Entry option) (cause: exn) (origin: obj) =\n    match entry with\n    | Some({ Operation = Crash _ } as e) -> reply e (Choice1Of2(box ()))\n    | Some e -> reply e (Choice2Of2(crashed cause))\n    | None -> ()\n    n.Active <- None\n    n.Seen.Add origin |> ignore\n    notify tree n (Crashed cause)\n    n.StopNotified <- true\n    let links = n.Links\n    decide tree n.Path true n.Path\n    if not n.Removed then n.StopNotified <- false\n    links\n\nand private propagate (links: Handle list) (cause: exn) (origin: obj) =\n    for other in links do\n        let t = other.Tree\n        lock t.Gate (fun () ->\n            match t.Nodes.TryGetValue other.Path with\n            | true, n when n.Accepting && not n.Removed && not (n.Seen.Contains origin) ->\n                n.Seen.Add origin |> ignore\n                n.Waiting.Enqueue { Reply = None; Operation = Crash(cause, origin); Context = None }\n                schedule t n\n            | _ -> ())\n\nand private pump (tree: Tree) (n: Node) (generation: int) =\n    let mutable go = true\n    while go do\n        let origin = obj ()\n        let step =\n            lock tree.Gate (fun () ->\n                if n.Worker <> generation || n.Removed then\n                    if n.Worker = generation then n.Running <- false\n                    None\n                elif n.Init then Some(Choice1Of2 n.Checkpoint)\n                elif n.Waiting.Count > 0 then\n                    let e = n.Waiting.Dequeue()\n                    n.Active <- Some e\n                    Some(Choice2Of2 e)\n                else\n                    n.Running <- false\n                    None)\n        match step with\n        | None -> go <- false\n        | Some(Choice1Of2 checkpoint) ->\n            let start, restart =\n                match n.Spec with\n                | ActorSpec(s, r, _) -> s, r\n                | SupervisorSpec _ -> failwith \"unreachable\"\n            let outcome =\n                try\n                    let mutable value = null\n                    ExecutionContext.Run(tree.Context.CreateCopy(), (fun _ ->\n                        value <- (match checkpoint with Some c -> restart c | None -> start ())), null)\n                    Choice1Of2 value\n                with e -> Choice2Of2 e\n            let links =\n                lock tree.Gate (fun () ->\n                    if n.Worker <> generation then []\n                    else\n                        match outcome with\n                        | Choice1Of2 v ->\n                            n.State <- v\n                            n.Checkpoint <- Some v\n                            n.Init <- false\n                            []\n                        | Choice2Of2 e -> failed tree n None e origin)\n            match outcome with\n            | Choice2Of2 e when not (List.isEmpty links) -> propagate links e origin\n            | _ -> ()\n        | Some(Choice2Of2 entry) ->\n            let state = lock tree.Gate (fun () -> n.State)\n            let run (body: unit -> obj * obj) =\n                current.Value <- n\n                try\n                    try\n                        let mutable result = (null, null)\n                        match entry.Context with\n                        | Some c -> ExecutionContext.Run(c.CreateCopy(), (fun _ -> result <- body ()), null)\n                        | None -> ExecutionContext.Run(tree.Context.CreateCopy(), (fun _ -> result <- body ()), null)\n                        Choice1Of2 result\n                    with e -> Choice2Of2 e\n                finally\n                    current.Value <- null\n            match entry.Operation with\n            | Stop ->\n                lock tree.Gate (fun () ->\n                    if n.Worker = generation then\n                        n.Active <- None\n                        reply entry (Choice1Of2(box ()))\n                        decide tree n.Path false n.Path)\n            | Crash(cause, origin) ->\n                let links = lock tree.Gate (fun () -> if n.Worker = generation then failed tree n (Some entry) cause origin else [])\n                propagate links cause origin\n            | Run handler ->\n                let outcome = run (fun () -> handler state)\n                let links =\n                    lock tree.Gate (fun () ->\n                        if n.Worker <> generation then []\n                        else\n                            match outcome with\n                            | Choice1Of2(answer, next) ->\n                                n.State <- next\n                                n.Checkpoint <- Some next\n                                n.Active <- None\n                                reply entry (Choice1Of2 answer)\n                                []\n                            | Choice2Of2 e -> failed tree n (Some entry) e origin)\n                match outcome with\n                | Choice2Of2 e when not (List.isEmpty links) -> propagate links e origin\n                | _ -> ()\n            | Restart ->\n                let restart = match n.Spec with ActorSpec(_, r, _) -> r | _ -> id\n                let outcome = run (fun () -> box (), restart state)\n                let links =\n                    lock tree.Gate (fun () ->\n                        if n.Worker <> generation then []\n                        else\n                            match outcome with\n                            | Choice1Of2(_, next) ->\n                                n.State <- next\n                                n.Checkpoint <- Some next\n                                n.Active <- None\n                                []\n                            | Choice2Of2 e -> failed tree n (Some entry) e origin)\n                match outcome with\n                | Choice2Of2 e when not (List.isEmpty links) -> propagate links e origin\n                | _ -> ()\n\n// ---------------------------------------------------------------------------\n// Specs\n\n/// An actor: its state's start, and its state after a crash from the last\n/// committed one.\n[<CompiledName(\"Actor\")>]\nlet actor (start: unit -> obj) (restart: obj -> obj) : Spec = ActorSpec(start, restart, null)\n\n/// An actor whose state after a crash is a fresh start.\n[<CompiledName(\"ActorOf\")>]\nlet actorOf (start: unit -> obj) : Spec = ActorSpec(start, (fun _ -> start ()), null)\n\n/// A supervisor: its strategy, at most a number of restarts within a period\n/// (microseconds), and its children in start order, each named and with its\n/// lifetime.\n[<CompiledName(\"Supervisor\")>]\nlet supervisor (strategy: Strategy) (restarts: int) (periodMicros: int64) (children: (string * Lifetime * Spec) list) : Spec =\n    if restarts < 0 || periodMicros <= 0L then fail \"InvalidSupervisor\" \"a supervisor needs restarts >= 0 and a positive period\"\n    let names = children |> List.map (fun (n, _, _) -> n)\n    if List.length names <> List.length (List.distinct names) then fail \"InvalidSupervisor\" \"duplicate child names\"\n    SupervisorSpec(strategy, restarts, periodMicros, children, null)\n\n/// A spec with metadata a generated API reads back from its handle.\n[<CompiledName(\"WithMetadata\")>]\nlet withMetadata (metadata: obj) (spec: Spec) : Spec =\n    match spec with\n    | ActorSpec(s, r, _) -> ActorSpec(s, r, metadata)\n    | SupervisorSpec(st, n, p, c, _) -> SupervisorSpec(st, n, p, c, metadata)\n\n// ---------------------------------------------------------------------------\n// Starting and stopping trees\n\nlet rec private allocate (tree: Tree) path (spec: Spec) parent lifetime =\n    let n = Node(path, spec, parent, lifetime)\n    tree.Nodes.[path] <- n\n    match spec with\n    | SupervisorSpec(_, _, _, children, _) ->\n        n.Children <- children |> List.map (fun (name, _, _) -> name, path @ [ name ])\n        for name, life, child in children do\n            allocate tree (path @ [ name ]) child (Some path) life\n    | ActorSpec _ -> n.Init <- true\n\n/// Stop a handle: an actor finishes the messages it accepted first; a\n/// supervisor stops its whole subtree. Stopping a stopped handle does nothing.\n[<CompiledName(\"Stop\")>]\nlet stop (handle: Handle) =\n    let tree = handle.Tree\n    let wait =\n        lock tree.Gate (fun () ->\n            let n = node tree handle.Path\n            if n.Removed then None\n            elif n.IsActor then\n                n.Accepting <- n.Parent.IsSome && n.Lifetime = Permanent\n                let r = TaskCompletionSource<obj>(TaskCreationOptions.RunContinuationsAsynchronously)\n                n.Waiting.Enqueue { Reply = Some r; Operation = Stop; Context = None }\n                schedule tree n\n                Some r.Task\n            else\n                match n.Parent with\n                | Some _ when n.Lifetime = Permanent -> decide tree handle.Path false handle.Path\n                | _ -> halt tree handle.Path\n                None)\n    match wait with\n    | Some task -> (try task.Wait() with _ -> ())\n    | None -> ()\n\n/// Start a spec. Its actors start in order; a start that fails stops the\n/// tree and fails here. An actor alone runs as the temporary child of a\n/// supervisor with no restarts; its handle is the actor's.\n[<CompiledName(\"Start\")>]\nlet start (spec: Spec) : Handle =\n    let tree = Tree(ExecutionContext.Capture())\n    let root, public' =\n        match spec with\n        | ActorSpec _ -> supervisor OneForOne 0 1L [ \"actor\", Temporary, spec ], [ \"actor\" ]\n        | SupervisorSpec _ -> spec, []\n    allocate tree [] root None Permanent\n    let actors = descendants tree [] |> List.map (node tree) |> List.filter (fun n -> n.IsActor)\n    for n in actors do\n        match n.Spec with\n        | ActorSpec(s, _, _) ->\n            let value =\n                try\n                    let mutable v = null\n                    ExecutionContext.Run(tree.Context.CreateCopy(), (fun _ -> v <- s ()), null)\n                    v\n                with e ->\n                    lock tree.Gate (fun () -> halt tree [])\n                    raise (LawSpecException(\"ActorStartFailed\", e.Message, [], e))\n            lock tree.Gate (fun () ->\n                n.State <- value\n                n.Checkpoint <- Some value\n                n.Init <- false)\n        | SupervisorSpec _ -> ()\n    { Tree = tree; Path = public' }\n\n/// Run a body with a started spec, stopping its tree afterwards.\n[<CompiledName(\"WithSpec\")>]\nlet withSpec (spec: Spec) (body: Handle -> 'a) : 'a =\n    let handle = start spec\n    try body handle\n    finally stop { handle with Path = [] }\n\n// ---------------------------------------------------------------------------\n// Messages\n\nlet private enqueue (handle: Handle) (operation: Operation) (wait: bool) : Task<obj> =\n    let tree = handle.Tree\n    lock tree.Gate (fun () ->\n        let n = node tree handle.Path\n        if obj.ReferenceEquals(current.Value, n) && wait then fail \"ActorSelfCall\" \"an actor cannot call itself\"\n        if not n.IsActor || not n.Accepting || n.Removed then Task.FromException<obj>(stopped ())\n        else\n            let r = TaskCompletionSource<obj>(TaskCreationOptions.RunContinuationsAsynchronously)\n            n.Waiting.Enqueue\n                { Reply = Some r; Operation = operation\n                  Context = Some(ExecutionContext.Capture()) }\n            schedule tree n\n            r.Task)\n\nlet private await (task: Task<obj>) =\n    try task.GetAwaiter().GetResult() with\n    | :? LawSpecException -> reraise ()\n\n/// Send a handler and wait for its reply. The handler gets the state and\n/// gives the reply and the next state.\n[<CompiledName(\"Call\")>]\nlet call (handle: Handle) (handler: obj -> obj * obj) : obj = await (enqueue handle (Run handler) true)\n\n/// Send a handler without waiting for it.\n[<CompiledName(\"Tell\")>]\nlet tell (handle: Handle) (handler: obj -> obj * obj) =\n    let task = enqueue handle (Run handler) false\n    if task.IsFaulted then await task |> ignore\n\n/// The actor's committed state.\n[<CompiledName(\"State\")>]\nlet state (handle: Handle) : obj = call handle (fun s -> s, s)\n\n/// Crash the actor in order with its messages, as a failing handler would.\n[<CompiledName(\"Crash\")>]\nlet crash (handle: Handle) =\n    enqueue handle (Crash(LawSpecException(\"CrashedOnPurpose\", \"\") :> exn, obj ())) true |> await |> ignore\n\n/// Kill the actor's worker now, as an external failure: a handler it is\n/// running commits nothing and its caller learns the actor crashed; the\n/// messages waiting run after its supervisor restarts it.\n[<CompiledName(\"Kill\")>]\nlet kill (handle: Handle) =\n    let tree = handle.Tree\n    let origin = obj ()\n    let links, cause =\n        lock tree.Gate (fun () ->\n            let n = node tree handle.Path\n            if n.Removed || not n.IsActor then [], null\n            else\n                let cause = LawSpecException(\"ActorKilled\", \"the actor's worker was killed\") :> exn\n                n.Worker <- n.Worker + 1\n                n.Incarnation <- n.Incarnation + 1\n                n.Running <- false\n                let links = failed tree n n.Active cause origin\n                schedule tree n\n                links, cause)\n    if not (isNull cause) then propagate links cause origin\n\n/// A supervisor's child by name (stable across restarts).\n[<CompiledName(\"Child\")>]\nlet child (handle: Handle) (name: string) : Handle =\n    lock handle.Tree.Gate (fun () ->\n        match (node handle.Tree handle.Path).Children |> List.tryFind (fun (n, _) -> n = name) with\n        | Some(_, path) -> { handle with Path = path }\n        | None -> fail \"UnknownChild\" name)\n\n/// A supervisor's children that have not stopped for good, in order.\n[<CompiledName(\"Children\")>]\nlet children (handle: Handle) : (string * Handle) list =\n    lock handle.Tree.Gate (fun () ->\n        (node handle.Tree handle.Path).Children\n        |> List.filter (fun (_, p) -> not (node handle.Tree p).Removed)\n        |> List.map (fun (n, p) -> n, { handle with Path = p }))\n\n/// Restarts a supervisor has made in its current period.\n[<CompiledName(\"RestartCount\")>]\nlet restartCount (handle: Handle) : int = lock handle.Tree.Gate (fun () -> List.length (node handle.Tree handle.Path).Restarts)\n\n/// The worker now behind a handle (it changes when the worker is replaced),\n/// or None when the handle has stopped.\n[<CompiledName(\"Worker\")>]\nlet worker (handle: Handle) : int option =\n    lock handle.Tree.Gate (fun () ->\n        let n = node handle.Tree handle.Path\n        if n.Removed then None else Some n.Incarnation)\n\n/// The metadata of the spec a handle was started from.\n[<CompiledName(\"Metadata\")>]\nlet metadata (handle: Handle) : obj =\n    lock handle.Tree.Gate (fun () ->\n        match (node handle.Tree handle.Path).Spec with\n        | ActorSpec(_, _, m) | SupervisorSpec(_, _, _, _, m) -> m)\n\n/// Tell an inbox about a handle's crashes and its stop.\n[<CompiledName(\"Monitor\")>]\nlet monitor (handle: Handle) (inbox: Inbox) =\n    lock handle.Tree.Gate (fun () ->\n        let n = node handle.Tree handle.Path\n        n.Observers <- inbox :: n.Observers)\n\n/// Link two actors: a crash of either crashes the other.\n[<CompiledName(\"Link\")>]\nlet link (left: Handle) (right: Handle) =\n    lock left.Tree.Gate (fun () -> let n = node left.Tree left.Path in n.Links <- right :: n.Links)\n    lock right.Tree.Gate (fun () -> let n = node right.Tree right.Path in n.Links <- left :: n.Links)\n\n/// The next event of a handle in an inbox, waiting at most a number of\n/// milliseconds.\n[<CompiledName(\"ReceiveEvent\")>]\nlet receiveEvent (inbox: Inbox) (handle: Handle) (milliseconds: int) : Event option = inbox.Receive(box handle, milliseconds)\n"
dotnetSource "LawSpec.Runtime/Codecs.fs" = "/// Conversions between portable values and the native .NET types adapters\n/// use. The generated code composes these for each adapter's signature, and\n/// generates one for each data type, so no reflection is involved.\n/// ref:DEC-typed-core-boundary ref:DEC-native-bindings-typed-identity\nnamespace LawSpec.Runtime\n\nopen System\nopen System.Numerics\nopen System.Text\nopen LawSpec\n\n/// To and from a native type.\ntype Codec<'T> =\n    { ToNative: Value -> 'T\n      FromNative: 'T -> Value }\n\nmodule Codec =\n    let private wrong (expected: string) (value: Value) : 'a =\n        Fail.raiseWith \"InvalidNativeValue\" (sprintf \"expected %s, got %A\" expected value)\n\n    let private integer name (value: Value) =\n        match value with\n        | Int n -> n\n        | _ -> wrong name value\n\n    let inline private bounded name (convert: BigInteger -> 'T) (back: 'T -> BigInteger) : Codec<'T> =\n        { ToNative = fun v -> convert (integer name v)\n          FromNative = fun n -> Int(back n) }\n\n    [<CompiledName(\"Int8\")>]\n    let int8 = bounded \"Int8\" sbyte BigInteger\n    [<CompiledName(\"Int16\")>]\n    let int16 = bounded \"Int16\" int16 BigInteger\n    [<CompiledName(\"Int32\")>]\n    let int32 = bounded \"Int32\" int32 (fun (n: int) -> BigInteger n)\n    [<CompiledName(\"Int64\")>]\n    let int64 = bounded \"Int64\" int64 (fun (n: int64) -> BigInteger n)\n    [<CompiledName(\"UInt8\")>]\n    let uint8 = bounded \"UInt8\" byte BigInteger\n    [<CompiledName(\"UInt16\")>]\n    let uint16 = bounded \"UInt16\" uint16 BigInteger\n    [<CompiledName(\"UInt32\")>]\n    let uint32 = bounded \"UInt32\" uint32 (fun (n: uint32) -> BigInteger n)\n    [<CompiledName(\"UInt64\")>]\n    let uint64 = bounded \"UInt64\" uint64 (fun (n: uint64) -> BigInteger n)\n    [<CompiledName(\"BigInteger\")>]\n    let bigint: Codec<BigInteger> = { ToNative = integer \"Integer\"; FromNative = Int }\n\n    [<CompiledName(\"Bool\")>]\n    let bool: Codec<bool> =\n        { ToNative = (function Bool b -> b | v -> wrong \"Bool\" v)\n          FromNative = Bool }\n\n    [<CompiledName(\"Unit\")>]\n    let unit: Codec<unit> =\n        { ToNative = (function Unit -> () | v -> wrong \"Unit\" v)\n          FromNative = fun () -> Unit }\n\n    [<CompiledName(\"Null\")>]\n    let nullValue: Codec<Null> =\n        { ToNative = (function Value.Null -> Null.Null | v -> wrong \"Null\" v)\n          FromNative = fun _ -> Value.Null }\n\n    [<CompiledName(\"Undefined\")>]\n    let undefinedValue: Codec<Undefined> =\n        { ToNative = (function Value.Undefined -> Undefined.Undefined | v -> wrong \"Undefined\" v)\n          FromNative = fun _ -> Value.Undefined }\n\n    [<CompiledName(\"Text\")>]\n    let text: Codec<string> =\n        { ToNative = (function Text s -> s | v -> wrong \"Text\" v)\n          FromNative = fun s ->\n              if isNull s then Fail.raiseWith \"InvalidNativeValue\" \"a null string\"\n              Text s }\n\n    /// Bytes cross as a copy, so neither side can change the other's.\n    [<CompiledName(\"Bytes\")>]\n    let bytes: Codec<byte[]> =\n        { ToNative = (function Bytes b -> Array.copy b | v -> wrong \"Bytes\" v)\n          FromNative = fun b ->\n              if isNull b then Fail.raiseWith \"InvalidNativeValue\" \"a null byte array\"\n              Bytes(Array.copy b) }\n\n    [<CompiledName(\"Char\")>]\n    let rune: Codec<Rune> =\n        { ToNative = fun v -> Rune(int (integer \"Char\" v))\n          FromNative = fun r -> Int(BigInteger r.Value) }\n\n    [<CompiledName(\"CodePoint\")>]\n    let codePoint: Codec<int> = bounded \"CodePoint\" int (fun (n: int) -> BigInteger n)\n\n    [<CompiledName(\"CodeUnit16\")>]\n    let codeUnit16: Codec<char> = bounded \"CodeUnit16\" (fun n -> char (int n)) (fun (c: char) -> BigInteger(int c))\n\n    [<CompiledName(\"CodePointText\")>]\n    let codePointText: Codec<int list> =\n        { ToNative = (function Raw(_, units) -> units | v -> wrong \"CodePointText\" v)\n          FromNative = fun units -> Raw(\"CodePointText\", units) }\n\n    [<CompiledName(\"Utf16Text\")>]\n    let utf16Text: Codec<string> =\n        { ToNative = (function Raw(_, units) -> String(units |> List.map char |> Array.ofList) | v -> wrong \"Utf16Text\" v)\n          FromNative = fun s -> Raw(\"Utf16Text\", s |> Seq.map int |> List.ofSeq) }\n\n    [<CompiledName(\"Float32\")>]\n    let float32: Codec<float32> =\n        { ToNative = (function Float(32, b) -> BitConverter.UInt32BitsToSingle(Operators.uint32 b) | v -> wrong \"Float32\" v)\n          FromNative = Scalar.floatFromSingle }\n\n    [<CompiledName(\"Float64\")>]\n    let float64: Codec<float> =\n        { ToNative = (function Float(64, b) -> BitConverter.UInt64BitsToDouble b | v -> wrong \"Float64\" v)\n          FromNative = Scalar.floatFromDouble }\n\n    [<CompiledName(\"Complex64\")>]\n    let complex64: Codec<Complex64> =\n        { ToNative = (function Complex(_, r, i) -> { Real = float32.ToNative r; Imaginary = float32.ToNative i } | v -> wrong \"Complex64\" v)\n          FromNative = fun c -> Value.Complex(32, float32.FromNative c.Real, float32.FromNative c.Imaginary) }\n\n    [<CompiledName(\"Complex128\")>]\n    let complex128: Codec<Complex> =\n        { ToNative = (function Complex(_, r, i) -> Complex(float64.ToNative r, float64.ToNative i) | v -> wrong \"Complex128\" v)\n          FromNative = fun c -> Value.Complex(64, float64.FromNative c.Real, float64.FromNative c.Imaginary) }\n\n    [<CompiledName(\"Rational\")>]\n    let rational: Codec<Rational> =\n        { ToNative = (function Ratio(n, d) -> Rational.Create(n, d) | v -> wrong \"Rational\" v)\n          FromNative = fun r -> Scalar.ratio r.Numerator r.Denominator }\n\n    [<CompiledName(\"Decimal\")>]\n    let exactDecimal: Codec<ExactDecimal> =\n        { ToNative = (function Decimal(c, e) -> { Coefficient = c; Exponent = e } | v -> wrong \"Decimal\" v)\n          FromNative = fun d -> Value.Decimal(d.Coefficient, d.Exponent) }\n\n    [<CompiledName(\"Symbol\")>]\n    let symbol: Codec<Symbol> =\n        { ToNative = (function Value.Symbol(id, d) -> Symbol(id, d) | v -> wrong \"Symbol\" v)\n          FromNative = fun s ->\n              if isNull s then Fail.raiseWith \"InvalidNativeValue\" \"a null symbol\"\n              Value.Symbol(s.Identity, s.Description) }\n\n    [<CompiledName(\"List\")>]\n    let list (item: Codec<'T>) : Codec<'T list> =\n        { ToNative = (function List items -> items |> List.map item.ToNative | v -> wrong \"List\" v)\n          FromNative = fun items -> List(items |> List.map item.FromNative) }\n\n    [<CompiledName(\"Maybe\")>]\n    let option (item: Codec<'T>) : Codec<'T option> =\n        { ToNative =\n            (function\n            | Data(\"Maybe::Nothing\", []) -> None\n            | Data(\"Maybe::Just\", [ v ]) -> Some(item.ToNative v)\n            | v -> wrong \"Maybe\" v)\n          FromNative =\n            (function\n            | None -> Data(\"Maybe::Nothing\", [])\n            | Some v -> Data(\"Maybe::Just\", [ item.FromNative v ])) }\n\n    [<CompiledName(\"Either\")>]\n    let either (left: Codec<'L>) (right: Codec<'R>) : Codec<Either<'L, 'R>> =\n        { ToNative =\n            (function\n            | Data(\"Either::Left\", [ v ]) -> Either.Left(left.ToNative v)\n            | Data(\"Either::Right\", [ v ]) -> Either.Right(right.ToNative v)\n            | v -> wrong \"Either\" v)\n          FromNative =\n            (function\n            | Either.Left v -> Data(\"Either::Left\", [ left.FromNative v ])\n            | Either.Right v -> Data(\"Either::Right\", [ right.FromNative v ])) }\n\n    [<CompiledName(\"Nullable\")>]\n    let nullable (item: Codec<'T>) : Codec<Nullable<'T>> =\n        { ToNative =\n            (function\n            | Presence(_, None) -> Nullable.Null\n            | Presence(_, Some v) -> Nullable.Present(item.ToNative v)\n            | v -> wrong \"Nullable\" v)\n          FromNative =\n            (function\n            | Nullable.Null -> Presence(\"Nullable\", None)\n            | Nullable.Present v -> Presence(\"Nullable\", Some(item.FromNative v))) }\n\n    [<CompiledName(\"Optional\")>]\n    let optional (item: Codec<'T>) : Codec<Optional<'T>> =\n        { ToNative =\n            (function\n            | Presence(_, None) -> Optional.Undefined\n            | Presence(_, Some v) -> Optional.Present(item.ToNative v)\n            | v -> wrong \"Optional\" v)\n          FromNative =\n            (function\n            | Optional.Undefined -> Presence(\"Optional\", None)\n            | Optional.Present v -> Presence(\"Optional\", Some(item.FromNative v))) }\n\n    /// A handle's identity crosses unchanged.\n    [<CompiledName(\"Handle\")>]\n    let handle<'T when 'T: not struct> (name: string) : Codec<'T> =\n        { ToNative = (function Handle(_, identity) -> unbox<'T> identity | v -> wrong name v)\n          FromNative = fun native ->\n              if isNull (box native) then Fail.raiseWith \"HandleRequiresIdentity\" name\n              Handle(name, box native) }\n\n    /// The value itself, for a type with no native form.\n    [<CompiledName(\"Portable\")>]\n    let portable: Codec<Value> = { ToNative = id; FromNative = id }\n\n    /// A Set as F#'s persistent Set: canonical (sorted, distinct) in the\n    /// portable order whatever F#'s own order of the items.\n    [<CompiledName(\"Set\")>]\n    let set (item: Codec<'T>) : Codec<Set<'T>> =\n        { ToNative =\n            (function\n            | Data(_, [ List items ]) -> items |> List.map item.ToNative |> Set.ofList\n            | v -> wrong \"Set\" v)\n          FromNative = fun s ->\n              let items = s |> Seq.map item.FromNative |> List.ofSeq |> List.sortWith Scalar.compareValues\n              Data(\"lawspec.collections::type::Set::SetItems\", [ List items ]) }\n\n    /// A KeyVal as F#'s persistent Map, its entries in the portable order of\n    /// their keys.\n    [<CompiledName(\"KeyVal\")>]\n    let map (key: Codec<'K>) (value: Codec<'V>) : Codec<Map<'K, 'V>> =\n        { ToNative =\n            (function\n            | Data(_, [ List entries ]) ->\n                entries\n                |> List.map (function\n                    | Data(_, [ k; v ]) -> key.ToNative k, value.ToNative v\n                    | e -> wrong \"Entry\" e)\n                |> Map.ofList\n            | v -> wrong \"KeyVal\" v)\n          FromNative = fun m ->\n              let entries =\n                  m |> Seq.map (fun (KeyValue(k, v)) -> key.FromNative k, value.FromNative v)\n                  |> List.ofSeq |> List.sortWith (fun (a, _) (b, _) -> Scalar.compareValues a b)\n                  |> List.map (fun (k, v) -> Data(\"lawspec.collections::type::Entry::Entry\", [ k; v ]))\n              Data(\"lawspec.collections::type::KeyVal::KeyValEntries\", [ List entries ]) }\n\n    /// A Duration as a TimeSpan of whole microseconds.\n    [<CompiledName(\"Duration\")>]\n    let duration: Codec<TimeSpan> =\n        { ToNative =\n            (function\n            | Data(_, [ Int micros ]) -> TimeSpan.FromTicks(Operators.int64 micros * 10L)\n            | v -> wrong \"Duration\" v)\n          FromNative = fun span ->\n              if span.Ticks % 10L <> 0L then Fail.raiseWith \"InvalidNativeValue\" \"a Duration is a whole number of microseconds\"\n              Data(\"lawspec.time::type::Duration::Duration\", [ Int(BigInteger(span.Ticks / 10L)) ]) }\n"
dotnetSource "LawSpec.Runtime/Crypto.fs" = "/// LawSpec's post-quantum crypto defaults on .NET: SHA3-256 and SHAKE256\n/// (FIPS 202), ML-KEM-768 (FIPS 203), ML-DSA-65 (FIPS 204), SLH-DSA-SHAKE-128f\n/// (FIPS 205) and AES-256-GCM (SP 800-38D). Keys are stored as their FIPS\n/// key-generation seeds, as on every target, so the portable values are the\n/// same. .NET 10's System.Security.Cryptography is used where the platform\n/// supports it; BouncyCastle otherwise, and for the deterministic forms the\n/// known-answer tests need. Both give the standards' bytes.\n/// ref:DEC-typed-core-boundary ref:DEC-fsharp-runtime-from-scratch\nmodule LawSpec.Runtime.Crypto\n\n#nowarn \"57\"\n\nopen System\nopen System.Numerics\nopen System.Security.Cryptography\nopen Org.BouncyCastle.Crypto\nopen Org.BouncyCastle.Crypto.Digests\nopen Org.BouncyCastle.Crypto.Engines\nopen Org.BouncyCastle.Crypto.Generators\nopen Org.BouncyCastle.Crypto.Kems\nopen Org.BouncyCastle.Crypto.Modes\nopen Org.BouncyCastle.Crypto.Parameters\nopen Org.BouncyCastle.Crypto.Signers\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n/// A SecureRandom that hands out fixed bytes in order: the deterministic\n/// randomness a FIPS known-answer test supplies (an encapsulation's message,\n/// an SLH-DSA key's seeds).\ntype private FixedRandom(bytes: byte[]) =\n    inherit Org.BouncyCastle.Security.SecureRandom()\n    let mutable position = 0\n    let take (buffer: byte[]) start length =\n        if position + length > bytes.Length then fail \"FixedRandomExhausted\" \"\"\n        Array.blit bytes position buffer start length\n        position <- position + length\n    override _.NextBytes(buffer: byte[]) = take buffer 0 buffer.Length\n    override _.NextBytes(buffer: byte[], start: int, length: int) = take buffer start length\n    override _.NextBytes(buffer: Span<byte>) =\n        if position + buffer.Length > bytes.Length then fail \"FixedRandomExhausted\" \"\"\n        ReadOnlySpan<byte>(bytes, position, buffer.Length).CopyTo(buffer)\n        position <- position + buffer.Length\n\nlet private secure = Org.BouncyCastle.Security.SecureRandom()\n\n/// Fresh random bytes from the operating system.\n[<CompiledName(\"RandomBytes\")>]\nlet randomBytes (count: int) = RandomNumberGenerator.GetBytes(max 0 count)\n\n// ---------------------------------------------------------------------------\n// FIPS 202\n\n/// SHA3-256 of a message.\n[<CompiledName(\"Sha3\")>]\nlet sha3 (message: byte[]) : byte[] =\n    if SHA3_256.IsSupported then SHA3_256.HashData message\n    else\n        let digest = Sha3Digest(256)\n        digest.BlockUpdate(message, 0, message.Length)\n        let out = Array.zeroCreate 32\n        digest.DoFinal(out, 0) |> ignore\n        out\n\n/// SHAKE256 of a message, a number of bytes long (none when it is not\n/// positive).\n[<CompiledName(\"Shake\")>]\nlet shake (message: byte[]) (count: int) : byte[] =\n    if count <= 0 then [||]\n    elif Shake256.IsSupported then Shake256.HashData(message, count)\n    else\n        let digest = ShakeDigest(256)\n        digest.BlockUpdate(message, 0, message.Length)\n        let out = Array.zeroCreate count\n        digest.OutputFinal(out, 0, count) |> ignore\n        out\n\n/// An AES-256-GCM key for a shared secret and a context.\n[<CompiledName(\"DeriveAeadKey\")>]\nlet deriveAeadKey (secret: byte[]) (context: byte[]) = shake (Array.append secret context) 32\n\n// ---------------------------------------------------------------------------\n// FIPS 203: ML-KEM-768, keys held as their 64-byte seed d || z\n\nlet private kem = MLKemParameters.ml_kem_768\n\n/// The encapsulation key and the expanded decapsulation key of a seed.\n[<CompiledName(\"MlKemExpand\")>]\nlet mlkemExpand (seed: byte[]) : byte[] * byte[] =\n    if seed.Length <> 64 then fail \"InvalidMlKemSeed\" \"\"\n    if MLKem.IsSupported then\n        use key = MLKem.ImportPrivateSeed(MLKemAlgorithm.MLKem768, seed)\n        key.ExportEncapsulationKey(), key.ExportDecapsulationKey()\n    else\n        let key = MLKemPrivateKeyParameters.FromSeed(kem, seed, MLKemPrivateKeyParameters.Format.EncodingOnly)\n        key.GetPublicKeyEncoded(), key.GetEncoded()\n\n/// A key pair from a seed: the public key, and the seed it is kept as.\n[<CompiledName(\"MlKemKeyPair\")>]\nlet mlkemKeyPair (seed: byte[]) = fst (mlkemExpand seed), seed\n\nlet private bcEncapsulate (publicKey: byte[]) (random: Org.BouncyCastle.Security.SecureRandom) =\n    if publicKey.Length <> 1184 then fail \"InvalidMlKemPublicKey\" \"\"\n    let encapsulator = MLKemEncapsulator(kem)\n    encapsulator.Init(ParametersWithRandom(MLKemPublicKeyParameters.FromEncoding(kem, publicKey), random))\n    let ciphertext = Array.zeroCreate encapsulator.EncapsulationLength\n    let shared = Array.zeroCreate encapsulator.SecretLength\n    encapsulator.Encapsulate(ciphertext, 0, ciphertext.Length, shared, 0, shared.Length)\n    ciphertext, shared\n\n/// Encapsulate a fresh shared secret: the ciphertext and the secret.\n[<CompiledName(\"MlKemEncapsulate\")>]\nlet mlkemEncapsulate (publicKey: byte[]) : byte[] * byte[] =\n    if MLKem.IsSupported then\n        if publicKey.Length <> 1184 then fail \"InvalidMlKemPublicKey\" \"\"\n        use key = MLKem.ImportEncapsulationKey(MLKemAlgorithm.MLKem768, publicKey)\n        let mutable ciphertext = null\n        let mutable shared = null\n        key.Encapsulate(&ciphertext, &shared)\n        ciphertext, shared\n    else bcEncapsulate publicKey secure\n\n/// FIPS 203's deterministic encapsulation with a given 32-byte message, for\n/// known-answer tests only.\n[<CompiledName(\"MlKemEncapsulateWith\")>]\nlet mlkemEncapsulateWith (publicKey: byte[]) (message: byte[]) =\n    if message.Length <> 32 then fail \"InvalidMlKemMessage\" \"\"\n    bcEncapsulate publicKey (new FixedRandom(message))\n\n/// Decapsulate with an expanded decapsulation key.\n[<CompiledName(\"MlKemDecapsulateExpanded\")>]\nlet mlkemDecapsulateExpanded (privateKey: byte[]) (ciphertext: byte[]) : byte[] =\n    if MLKem.IsSupported then\n        use key = MLKem.ImportDecapsulationKey(MLKemAlgorithm.MLKem768, privateKey)\n        key.Decapsulate ciphertext\n    else\n        let decapsulator = MLKemDecapsulator(kem)\n        decapsulator.Init(MLKemPrivateKeyParameters.FromEncoding(kem, privateKey))\n        let shared = Array.zeroCreate decapsulator.SecretLength\n        decapsulator.Decapsulate(ciphertext, 0, ciphertext.Length, shared, 0, shared.Length)\n        shared\n\n/// Decapsulate with a key kept as its seed.\n[<CompiledName(\"MlKemDecapsulate\")>]\nlet mlkemDecapsulate (seed: byte[]) (ciphertext: byte[]) = mlkemDecapsulateExpanded (snd (mlkemExpand seed)) ciphertext\n\n// ---------------------------------------------------------------------------\n// FIPS 204: ML-DSA-65, signing keys held as their 32-byte seed\n\nlet private dsa = MLDsaParameters.ml_dsa_65\n\n/// The public key and the expanded private key of a seed.\n[<CompiledName(\"MlDsaExpand\")>]\nlet mldsaExpand (seed: byte[]) : byte[] * byte[] =\n    if seed.Length <> 32 then fail \"InvalidMlDsaSeed\" \"\"\n    if MLDsa.IsSupported then\n        use key = MLDsa.ImportMLDsaPrivateSeed(MLDsaAlgorithm.MLDsa65, seed)\n        key.ExportMLDsaPublicKey(), key.ExportMLDsaPrivateKey()\n    else\n        let key = MLDsaPrivateKeyParameters.FromSeed(dsa, seed, MLDsaPrivateKeyParameters.Format.EncodingOnly)\n        key.GetPublicKeyEncoded(), key.GetEncoded()\n\n/// The public key of a seed.\n[<CompiledName(\"MlDsaPublic\")>]\nlet mldsaPublic (seed: byte[]) = fst (mldsaExpand seed)\n\nlet private bcSign (deterministic: bool) (key: ICipherParameters) (message: byte[]) (context: byte[]) =\n    let signer = MLDsaSigner(dsa, deterministic)\n    let keyed = if deterministic then key else ParametersWithRandom(key, secure) :> ICipherParameters\n    signer.Init(true, ParametersWithContext(keyed, context))\n    signer.BlockUpdate(message, 0, message.Length)\n    signer.GenerateSignature()\n\n/// Sign with a context string; deterministic for known-answer tests, hedged\n/// otherwise.\n[<CompiledName(\"MlDsaSignWith\")>]\nlet mldsaSignWith (seed: byte[]) (message: byte[]) (context: byte[]) (deterministic: bool) : byte[] =\n    if seed.Length <> 32 || context.Length > 255 then fail \"InvalidMlDsaSignature\" \"\"\n    if MLDsa.IsSupported && not deterministic then\n        use key = MLDsa.ImportMLDsaPrivateSeed(MLDsaAlgorithm.MLDsa65, seed)\n        key.SignData(message, context)\n    else\n        bcSign deterministic (MLDsaPrivateKeyParameters.FromSeed(dsa, seed)) message context\n\n/// Sign a message (hedged, with no context).\n[<CompiledName(\"MlDsaSign\")>]\nlet mldsaSign (seed: byte[]) (message: byte[]) = mldsaSignWith seed message [||] false\n\n/// Verify a signature with a context string; a malformed key or signature\n/// does not verify.\n[<CompiledName(\"MlDsaVerifyWith\")>]\nlet mldsaVerifyWith (publicKey: byte[]) (message: byte[]) (signature: byte[]) (context: byte[]) : bool =\n    if publicKey.Length <> 1952 || signature.Length <> 3309 || context.Length > 255 then false\n    elif MLDsa.IsSupported then\n        use key = MLDsa.ImportMLDsaPublicKey(MLDsaAlgorithm.MLDsa65, publicKey)\n        key.VerifyData(message, signature, context)\n    else\n        let signer = MLDsaSigner(dsa, false)\n        signer.Init(false, ParametersWithContext(MLDsaPublicKeyParameters.FromEncoding(dsa, publicKey), context))\n        signer.BlockUpdate(message, 0, message.Length)\n        signer.VerifySignature signature\n\n[<CompiledName(\"MlDsaVerify\")>]\nlet mldsaVerify (publicKey: byte[]) (message: byte[]) (signature: byte[]) = mldsaVerifyWith publicKey message signature [||]\n\n// ---------------------------------------------------------------------------\n// FIPS 205: SLH-DSA-SHAKE-128f, private keys of 64 bytes\n\nlet private slh = SlhDsaParameters.slh_dsa_shake_128f\n\nlet private slhGenerate (random: Org.BouncyCastle.Security.SecureRandom) =\n    let generator = SlhDsaKeyPairGenerator()\n    generator.Init(SlhDsaKeyGenerationParameters(random, slh))\n    let pair = generator.GenerateKeyPair()\n    (pair.Public :?> SlhDsaPublicKeyParameters).GetEncoded(), (pair.Private :?> SlhDsaPrivateKeyParameters).GetEncoded()\n\n/// A fresh key pair: the public key and the private key.\n[<CompiledName(\"SlhKeyPair\")>]\nlet slhKeyPair () : byte[] * byte[] =\n    if SlhDsa.IsSupported then\n        use key = SlhDsa.GenerateKey(SlhDsaAlgorithm.SlhDsaShake128f)\n        key.ExportSlhDsaPublicKey(), key.ExportSlhDsaPrivateKey()\n    else slhGenerate secure\n\n/// The key pair of the 48 bytes SK.seed || SK.prf || PK.seed (known-answer\n/// tests only).\n[<CompiledName(\"SlhKeyPairOf\")>]\nlet slhKeyPairOf (seed: byte[]) =\n    if seed.Length <> 48 then fail \"InvalidSlhDsaSeed\" \"\"\n    slhGenerate (new FixedRandom(seed))\n\n/// Sign with a context string.\n[<CompiledName(\"SlhSignWith\")>]\nlet slhSignWith (privateKey: byte[]) (message: byte[]) (context: byte[]) : byte[] =\n    if privateKey.Length <> 64 || context.Length > 255 then fail \"InvalidSlhDsaSignature\" \"\"\n    if SlhDsa.IsSupported then\n        use key = SlhDsa.ImportSlhDsaPrivateKey(SlhDsaAlgorithm.SlhDsaShake128f, privateKey)\n        key.SignData(message, context)\n    else\n        let signer = SlhDsaSigner(slh, false)\n        signer.Init(true, ParametersWithContext(ParametersWithRandom(SlhDsaPrivateKeyParameters.FromEncoding(slh, privateKey), secure), context))\n        signer.BlockUpdate(message, 0, message.Length)\n        signer.GenerateSignature()\n\n[<CompiledName(\"SlhSign\")>]\nlet slhSign (privateKey: byte[]) (message: byte[]) = slhSignWith privateKey message [||]\n\n/// Verify with a context string; a malformed key or signature does not verify.\n[<CompiledName(\"SlhVerifyWith\")>]\nlet slhVerifyWith (publicKey: byte[]) (message: byte[]) (signature: byte[]) (context: byte[]) : bool =\n    if publicKey.Length <> 32 || signature.Length <> 17088 || context.Length > 255 then false\n    elif SlhDsa.IsSupported then\n        use key = SlhDsa.ImportSlhDsaPublicKey(SlhDsaAlgorithm.SlhDsaShake128f, publicKey)\n        key.VerifyData(message, signature, context)\n    else\n        let signer = SlhDsaSigner(slh, false)\n        signer.Init(false, ParametersWithContext(SlhDsaPublicKeyParameters.FromEncoding(slh, publicKey), context))\n        signer.BlockUpdate(message, 0, message.Length)\n        signer.VerifySignature signature\n\n[<CompiledName(\"SlhVerify\")>]\nlet slhVerify (publicKey: byte[]) (message: byte[]) (signature: byte[]) = slhVerifyWith publicKey message signature [||]\n\n// ---------------------------------------------------------------------------\n// SP 800-38D: AES-256-GCM with a 96-bit nonce and a 128-bit tag\n\n/// The ciphertext followed by its tag.\n[<CompiledName(\"Aes256GcmEncrypt\")>]\nlet aes256GcmEncrypt (key: byte[]) (nonce: byte[]) (message: byte[]) (associated: byte[]) : byte[] =\n    if key.Length <> 32 || nonce.Length <> 12 then fail \"InvalidAeadKey\" \"\"\n    if AesGcm.IsSupported then\n        use aes = new AesGcm(key, 16)\n        let ciphertext = Array.zeroCreate message.Length\n        let tag = Array.zeroCreate 16\n        aes.Encrypt(nonce, message, ciphertext, tag, associated)\n        Array.append ciphertext tag\n    else\n        let cipher = GcmBlockCipher(AesEngine())\n        cipher.Init(true, AeadParameters(KeyParameter(key), 128, nonce, associated))\n        let out = Array.zeroCreate (cipher.GetOutputSize message.Length)\n        let n = cipher.ProcessBytes(message, 0, message.Length, out, 0)\n        cipher.DoFinal(out, n) |> ignore\n        out\n\n/// The plaintext, or None when the tag does not verify.\n[<CompiledName(\"Aes256GcmDecrypt\")>]\nlet aes256GcmDecrypt (key: byte[]) (nonce: byte[]) (sealedBytes: byte[]) (associated: byte[]) : byte[] option =\n    if key.Length <> 32 || nonce.Length <> 12 || sealedBytes.Length < 16 then None\n    elif AesGcm.IsSupported then\n        use aes = new AesGcm(key, 16)\n        let size = sealedBytes.Length - 16\n        let plaintext = Array.zeroCreate size\n        try\n            aes.Decrypt(nonce, sealedBytes.[.. size - 1], sealedBytes.[size ..], plaintext, associated)\n            Some plaintext\n        with :? CryptographicException -> None\n    else\n        let cipher = GcmBlockCipher(AesEngine())\n        cipher.Init(false, AeadParameters(KeyParameter(key), 128, nonce, associated))\n        let out = Array.zeroCreate (cipher.GetOutputSize sealedBytes.Length)\n        try\n            let n = cipher.ProcessBytes(sealedBytes, 0, sealedBytes.Length, out, 0)\n            cipher.DoFinal(out, n) |> ignore\n            Some out\n        with :? InvalidCipherTextException -> None\n\n/// A fresh nonce, then the sealed message.\n[<CompiledName(\"Seal\")>]\nlet seal (key: byte[]) (message: byte[]) (associated: byte[]) =\n    let nonce = randomBytes 12\n    Array.append nonce (aes256GcmEncrypt key nonce message associated)\n\n/// Open what seal made, or None.\n[<CompiledName(\"Unseal\")>]\nlet unseal (key: byte[]) (sealedBytes: byte[]) (associated: byte[]) =\n    if sealedBytes.Length < 12 then None\n    else aes256GcmDecrypt key sealedBytes.[.. 11] sealedBytes.[12 ..] associated\n\n// ---------------------------------------------------------------------------\n// The abilities' default handlers, over portable values\n\nlet private tag name = \"lawspec.crypto::type::\" + name + \"::\" + name\nlet private wrap name (bytes: byte[]) = Data(tag name, [ Bytes bytes ])\nlet private pair name first second = Data(tag name, [ first; second ])\n\nlet private unwrap name (value: Value) =\n    match value with\n    | Data(t, [ Bytes b ]) when t = tag name -> b\n    | _ -> fail \"InvalidCryptoValue\" name\n\nlet private bytes (value: Value) =\n    match value with\n    | Bytes b -> b\n    | _ -> fail \"BytesRequired\" \"\"\n\nlet private signatureHandler (make: unit -> byte[] * byte[]) sign verify =\n    Effects.stateless\n        [ \"signingKeyPair\",\n          (fun _ _ ->\n              let publicKey, secret = make ()\n              pair \"SigningKeyPair\" (wrap \"VerifyingKey\" publicKey) (wrap \"SigningKey\" secret))\n          \"sign\", (fun _ args -> match args with\n                                 | [ secret; message ] -> wrap \"SignatureBytes\" (sign (unwrap \"SigningKey\" secret) (bytes message))\n                                 | _ -> fail \"InvalidArguments\" \"sign\")\n          \"verify\", (fun _ args -> match args with\n                                   | [ publicKey; message; signature ] ->\n                                       Bool(verify (unwrap \"VerifyingKey\" publicKey) (bytes message) (unwrap \"SignatureBytes\" signature))\n                                   | _ -> fail \"InvalidArguments\" \"verify\") ]\n\n/// The SLH-DSA-SHAKE-128f handler of Signature: stateless hash-based\n/// signatures, for programs that choose them over ML-DSA.\n[<CompiledName(\"SlhDsaSignatureHandler\")>]\nlet slhDsaSignatureHandler () = signatureHandler slhKeyPair slhSign slhVerify\n\n/// The default handler of a lawspec.crypto ability.\n[<CompiledName(\"Handler\")>]\nlet handler (key: string) : Effects.Handler =\n    match key with\n    | \"lawspec.crypto::ability::Hash\" ->\n        Effects.stateless\n            [ \"sha3\", (fun _ args -> wrap \"Digest\" (sha3 (bytes (List.head args))))\n              \"shake\",\n              (fun _ args ->\n                  match args with\n                  | [ message; Int count ] -> Bytes(shake (bytes message) (if count > BigInteger(Int32.MaxValue) then Int32.MaxValue else int count))\n                  | _ -> fail \"InvalidArguments\" \"shake\") ]\n    | \"lawspec.crypto::ability::KeyExchange\" ->\n        Effects.stateless\n            [ \"exchangeKeyPair\",\n              (fun _ _ ->\n                  let publicKey, secret = mlkemKeyPair (randomBytes 64)\n                  pair \"ExchangeKeyPair\" (wrap \"ExchangePublicKey\" publicKey) (wrap \"ExchangeSecretKey\" secret))\n              \"encapsulate\",\n              (fun _ args ->\n                  let ciphertext, shared = mlkemEncapsulate (unwrap \"ExchangePublicKey\" (List.head args))\n                  pair \"Encapsulated\" (wrap \"Ciphertext\" ciphertext) (wrap \"SharedSecret\" shared))\n              \"decapsulate\",\n              (fun _ args ->\n                  match args with\n                  | [ secret; ciphertext ] ->\n                      wrap \"SharedSecret\" (mlkemDecapsulate (unwrap \"ExchangeSecretKey\" secret) (unwrap \"Ciphertext\" ciphertext))\n                  | _ -> fail \"InvalidArguments\" \"decapsulate\") ]\n    | \"lawspec.crypto::ability::Signature\" ->\n        signatureHandler (fun () -> let seed = randomBytes 32 in mldsaPublic seed, seed) mldsaSign mldsaVerify\n    | \"lawspec.crypto::ability::Aead\" ->\n        Effects.stateless\n            [ \"aeadKey\", (fun _ _ -> wrap \"AeadKey\" (randomBytes 32))\n              \"deriveAeadKey\",\n              (fun _ args ->\n                  match args with\n                  | [ secret; context ] -> wrap \"AeadKey\" (deriveAeadKey (unwrap \"SharedSecret\" secret) (bytes context))\n                  | _ -> fail \"InvalidArguments\" \"deriveAeadKey\")\n              \"seal\",\n              (fun _ args ->\n                  match args with\n                  | [ key; message; associated ] -> wrap \"Sealed\" (seal (unwrap \"AeadKey\" key) (bytes message) (bytes associated))\n                  | _ -> fail \"InvalidArguments\" \"seal\")\n              \"unseal\",\n              (fun _ args ->\n                  match args with\n                  | [ key; sealedValue; associated ] ->\n                      match unseal (unwrap \"AeadKey\" key) (unwrap \"Sealed\" sealedValue) (bytes associated) with\n                      | Some message -> Data(\"Maybe::Just\", [ Bytes message ])\n                      | None -> Data(\"Maybe::Nothing\", [])\n                  | _ -> fail \"InvalidArguments\" \"unseal\") ]\n    | _ -> fail \"UnknownDefaultHandler\" key\n\n/// Make Defaults.handler answer the lawspec.crypto abilities. The generated\n/// schema module of a program that uses lawspec.crypto calls this once.\n[<CompiledName(\"Install\")>]\nlet install () = Defaults.cryptoHandler <- handler\n"
dotnetSource "LawSpec.Runtime/Defaults.fs" = "/// The default handlers of the built-in abilities on .NET: the real clock,\n/// the run's seeded Random and the operating system's SecureRandom, files,\n/// environment variables and ports, logging, and pausing. Values are\n/// portable; the generated interfaces convert them where native code meets\n/// them. ref:DEC-typed-core-boundary ref:DEC-fsharp-runtime-from-scratch\nmodule LawSpec.Runtime.Defaults\n\nopen System\nopen System.Diagnostics\nopen System.IO\nopen System.Numerics\nopen System.Security.Cryptography\nopen System.Text.Json\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\nlet private just v = Data(\"Maybe::Just\", [ v ])\nlet private nothing = Data(\"Maybe::Nothing\", [])\n\n// The wall clock at start, then the monotonic clock: a later clock\n// correction never moves time backwards.\nlet private origin = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() * 1000L\nlet private started = Stopwatch.GetTimestamp()\n\n/// Microseconds since the Unix epoch, never decreasing.\n[<CompiledName(\"NowMicros\")>]\nlet nowMicros () : int64 =\n    let elapsed = Stopwatch.GetElapsedTime(started)\n    origin + int64 elapsed.Ticks / 10L\n\n/// Sleep at least a number of microseconds.\n[<CompiledName(\"SleepMicros\")>]\nlet sleepMicros (micros: int64) =\n    let deadline = Stopwatch.GetTimestamp() + micros * Stopwatch.Frequency / 1_000_000L\n    let mutable left = deadline - Stopwatch.GetTimestamp()\n    while left > 0L do\n        let ms = max 1L ((left * 1000L + Stopwatch.Frequency - 1L) / Stopwatch.Frequency)\n        Threading.Thread.Sleep(TimeSpan.FromMilliseconds(float ms))\n        left <- deadline - Stopwatch.GetTimestamp()\n\nlet private integer (v: Value) =\n    match v with\n    | Int n -> n\n    | _ -> fail \"IntegerRequired\" (sprintf \"%A\" v)\n\nlet private text (v: Value) =\n    match v with\n    | Text s -> s\n    | _ -> fail \"TextRequired\" (sprintf \"%A\" v)\n\nlet private mask = (BigInteger.One <<< 64) - BigInteger.One\n\nlet private randomStep (s: BigInteger) = (BigInteger 6364136223846793005L * s + BigInteger 1442695040888963407L) &&& mask\n\nlet private secureBelow (bound: int64) =\n    if bound < 1L then 0L\n    else\n        let range = UInt64.MaxValue - (UInt64.MaxValue % uint64 bound + 1UL) % uint64 bound\n        let mutable draw = 0UL\n        let buffer = Array.zeroCreate<byte> 8\n        let mutable found = false\n        while not found do\n            RandomNumberGenerator.Fill(Span<byte>(buffer))\n            draw <- BitConverter.ToUInt64(buffer, 0)\n            found <- draw <= range\n        int64 (draw % uint64 bound)\n\nlet private temporaryRoot () =\n    let candidates =\n        [ \"TMPDIR\"; \"TMP\"; \"TEMP\" ]\n        |> List.choose (fun n -> match Environment.GetEnvironmentVariable n with null | \"\" -> None | p -> Some p)\n    match (candidates @ [ Path.GetTempPath() ]) |> List.tryFind Directory.Exists with\n    | Some root -> Path.GetFullPath root\n    | None -> fail \"NoTemporaryDirectory\" \"\"\n\nlet private temporary (directory: bool) (prefix: string) =\n    if prefix.IndexOfAny([| char 0; '/'; '\\\\' |]) >= 0 then fail \"InvalidTemporaryPrefix\" prefix\n    let rec attempt n =\n        if n = 0 then fail \"TemporaryNameExhausted\" prefix\n        let name = prefix + Convert.ToHexString(RandomNumberGenerator.GetBytes 16).ToLowerInvariant()\n        let path = Path.Combine(temporaryRoot (), name)\n        if Directory.Exists path || File.Exists path then attempt (n - 1)\n        else\n            if directory then\n                Directory.CreateDirectory(path) |> ignore\n                if not (OperatingSystem.IsWindows()) then File.SetUnixFileMode(path, UnixFileMode.UserRead ||| UnixFileMode.UserWrite ||| UnixFileMode.UserExecute)\n            else\n                use _ = new FileStream(path, FileMode.CreateNew, FileAccess.Write)\n                if not (OperatingSystem.IsWindows()) then File.SetUnixFileMode(path, UnixFileMode.UserRead ||| UnixFileMode.UserWrite)\n            path\n    attempt 100\n\nlet private validName (name: string) = name.Length > 0 && name.IndexOfAny([| char 0; '=' |]) < 0\n\nlet private restoreEnvironment (saved: string) =\n    let decoded =\n        try JsonSerializer.Deserialize<Collections.Generic.Dictionary<string, string>>(saved)\n        with _ -> fail \"InvalidEnvironmentSnapshot\" \"\"\n    if isNull decoded || decoded |> Seq.exists (fun kv -> not (validName kv.Key) || isNull kv.Value || kv.Value.Contains(char 0)) then\n        fail \"InvalidEnvironmentSnapshot\" \"\"\n    for entry in Environment.GetEnvironmentVariables() |> Seq.cast<Collections.DictionaryEntry> do\n        let name = string entry.Key\n        if not (decoded.ContainsKey name) then Environment.SetEnvironmentVariable(name, null)\n    for kv in decoded do\n        Environment.SetEnvironmentVariable(kv.Key, kv.Value)\n\n/// A crypto ability's default handler, set by LawSpec.Runtime.Crypto when a\n/// program uses lawspec.crypto.\nlet mutable cryptoHandler: string -> Effects.Handler = fun key -> fail \"UnknownDefaultHandler\" key\n\n/// The default handler of a built-in ability, by its key.\n[<CompiledName(\"Handler\")>]\nlet handler (key: string) : Effects.Handler =\n    match key with\n    | k when k.StartsWith \"lawspec.crypto::ability::\" -> cryptoHandler k\n    | \"lawspec.time::ability::Clock\" ->\n        Effects.stateless\n            [ \"now\", (fun _ _ -> Data(\"lawspec.time::type::Instant::Instant\", [ Int(BigInteger(nowMicros ())) ]))\n              \"sleep\",\n              (fun _ args ->\n                  match args with\n                  | [ Data(_, [ Int micros ]) ] ->\n                      sleepMicros (int64 micros)\n                      Unit\n                  | _ -> fail \"InvalidDuration\" \"\") ]\n    | \"lawspec.randomness::ability::Random\" ->\n        let seed =\n            match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n            | null | \"\" -> BigInteger.Zero\n            | s -> (try BigInteger.Parse s with _ -> BigInteger.Zero)\n        let cell = Effects.Cell(Int(seed &&& mask))\n        Effects.stateless\n            [ \"randomBelow\",\n              (fun _ args ->\n                  let bound = integer (List.head args)\n                  cell.Update(fun state ->\n                      let first = randomStep (integer state)\n                      let second = randomStep first\n                      let bits = ((first >>> 32) <<< 32) ||| (second >>> 32)\n                      let draw = if bound.Sign > 0 then BigInteger.Remainder(bits, bound) else BigInteger.Zero\n                      Int draw, Int second)) ]\n    | \"lawspec.randomness::ability::SecureRandom\" ->\n        Effects.stateless\n            [ \"secureBytes\", (fun _ args -> Bytes(RandomNumberGenerator.GetBytes(max 0 (int (integer (List.head args))))))\n              \"secureBelow\", (fun _ args -> Int(BigInteger(secureBelow (int64 (integer (List.head args))))))\n              \"secureToken\", (fun _ _ -> Text(Convert.ToHexString(RandomNumberGenerator.GetBytes 32).ToLowerInvariant())) ]\n    | \"lawspec.host::ability::FileSystem\" ->\n        Effects.stateless\n            [ \"readBytes\", (fun _ args -> let p = text (List.head args) in if File.Exists p then just (Bytes(File.ReadAllBytes p)) else nothing)\n              \"writeBytes\",\n              (fun _ args ->\n                  match args with\n                  | [ Text p; Bytes b ] ->\n                      File.WriteAllBytes(p, b)\n                      Unit\n                  | _ -> fail \"InvalidArguments\" \"writeBytes\")\n              \"pathExists\", (fun _ args -> let p = text (List.head args) in Bool(File.Exists p || Directory.Exists p))\n              \"removePath\",\n              (fun _ args ->\n                  let p = text (List.head args)\n                  if Directory.Exists p then Directory.Delete(p, true)\n                  elif File.Exists p then File.Delete p\n                  Unit)\n              \"temporaryDirectory\", (fun _ args -> Text(temporary true (text (List.head args))))\n              \"temporaryFile\", (fun _ args -> Text(temporary false (text (List.head args)))) ]\n    | \"lawspec.host::ability::Environment\" ->\n        Effects.stateless\n            [ \"environmentVariable\",\n              (fun _ args ->\n                  let name = text (List.head args)\n                  if not (validName name) then nothing\n                  else\n                      match Environment.GetEnvironmentVariable name with\n                      | null -> nothing\n                      | value -> just (Text value))\n              \"environmentSnapshot\",\n              (fun _ _ ->\n                  let all = Collections.Generic.SortedDictionary<string, string>(StringComparer.Ordinal)\n                  for entry in Environment.GetEnvironmentVariables() |> Seq.cast<Collections.DictionaryEntry> do\n                      all.[string entry.Key] <- string entry.Value\n                  Text(JsonSerializer.Serialize all))\n              \"restoreEnvironment\",\n              (fun _ args ->\n                  restoreEnvironment (text (List.head args))\n                  Unit) ]\n    | \"lawspec.host::ability::Ports\" ->\n        Effects.stateless\n            [ \"freePort\",\n              (fun _ _ ->\n                  let listener = new Net.Sockets.TcpListener(Net.IPAddress.Loopback, 0)\n                  listener.Start()\n                  try Int(BigInteger((listener.LocalEndpoint :?> Net.IPEndPoint).Port))\n                  finally listener.Stop()) ]\n    | \"lawspec.logging::ability::Log\" ->\n        Effects.stateless\n            [ \"logMessage\",\n              (fun _ args ->\n                  match args with\n                  | [ Data(level, []); Text message ] ->\n                      let name = level.Substring(level.LastIndexOf(\"::\") + 2)\n                      let line = sprintf \"[%s] %s\" (name.ToLowerInvariant()) message\n                      if name = \"Warning\" || name = \"Error\" then eprintfn \"%s\" line else printfn \"%s\" line\n                      Unit\n                  | _ -> fail \"InvalidArguments\" \"logMessage\") ]\n    | \"lawspec.logging::ability::Trace\" ->\n        Effects.stateless\n            [ \"traceEvent\",\n              (fun _ args ->\n                  Trace.WriteLine(text (List.head args), \"lawspec\")\n                  Unit) ]\n    | \"lawspec.concurrent::ability::Async\" ->\n        Effects.stateless\n            [ \"pause\",\n              (fun _ _ ->\n                  Threading.Thread.Yield() |> ignore\n                  Unit) ]\n    | _ -> fail \"UnknownDefaultHandler\" key\n"
dotnetSource "LawSpec.Runtime/Descriptors.fs" = "/// Type descriptors and the portable generator over them: models, scenarios\n/// and channels draw, shrink, render and encode their values exactly as every\n/// other runtime does, so one seed replays one run on every target, and the\n/// wire bytes are the same. ref:DEC-portable-seeded-generation\n/// ref:DEC-distribution-canonical-wire ref:DEC-shrink-within-domain\nmodule LawSpec.Runtime.Descriptors\n\nopen System\nopen System.IO\nopen System.Numerics\nopen System.Text\n\n/// A descriptor form: an atom, an integer, a quoted string, the hole `_`, or\n/// a parenthesized list of forms.\n[<StructuralEquality; NoComparison>]\ntype Descriptor =\n    | Atom of string\n    | Number of BigInteger\n    | Quoted of string\n    | Hole\n    | Forms of Descriptor list\n\nlet private fail code : 'a = Fail.raiseWith code \"\"\n\nlet private require condition code = if not condition then fail code\n\n/// Read every form of a descriptor text.\n[<CompiledName(\"Read\")>]\nlet read (text: string) : Descriptor list =\n    let points = Scalar.codePoints text |> Array.ofList\n    let mutable i = 0\n    let isSpace c = c = int ' ' || c = int '\\n' || c = int '\\r' || c = int '\\t'\n    let skip () = while i < points.Length && isSpace points.[i] do i <- i + 1\n    let rec forms () =\n        let acc = ResizeArray()\n        skip ()\n        while i < points.Length && points.[i] <> int ')' do\n            acc.Add(item ())\n            skip ()\n        List.ofSeq acc\n    and item () =\n        if points.[i] = int '(' then\n            i <- i + 1\n            let children = forms ()\n            require (i < points.Length && points.[i] = int ')') \"UnclosedDescriptor\"\n            i <- i + 1\n            Forms children\n        elif points.[i] = int '\"' then\n            i <- i + 1\n            let chars = ResizeArray()\n            let mutable closed = false\n            while not closed do\n                require (i < points.Length) \"UnclosedDescriptorString\"\n                let c = points.[i]\n                if c = int '\\\\' && i + 1 < points.Length then\n                    chars.Add points.[i + 1]\n                    i <- i + 2\n                elif c = int '\"' then\n                    closed <- true\n                    i <- i + 1\n                else\n                    chars.Add c\n                    i <- i + 1\n            Quoted(Scalar.textOfPoints chars)\n        else\n            let start = i\n            while i < points.Length && not (isSpace points.[i]) && points.[i] <> int '(' && points.[i] <> int ')' do\n                i <- i + 1\n            require (i > start) \"EmptyDescriptorAtom\"\n            let word = Scalar.textOfPoints points.[start .. i - 1]\n            if word = \"_\" then Hole\n            else\n                match BigInteger.TryParse(word, Globalization.NumberStyles.AllowLeadingSign, Globalization.CultureInfo.InvariantCulture) with\n                | true, n -> Number n\n                | _ -> Atom word\n    let result = forms ()\n    require (i = points.Length) \"TrailingDescriptorInput\"\n    result\n\nlet private unquote d =\n    match d with\n    | Quoted s -> s\n    | Atom s -> s\n    | _ -> fail \"InvalidDescriptorName\"\n\n/// The named data descriptors of a text, and its last form.\n[<CompiledName(\"FromText\")>]\nlet fromText (text: string) : Map<string, Descriptor> * Descriptor =\n    let forms = read text\n    require (not (List.isEmpty forms)) \"EmptyDescriptor\"\n    let table =\n        forms\n        |> List.choose (function\n            | Forms(Atom \"data\" :: name :: _) as d -> Some(unquote name, d)\n            | _ -> None)\n        |> Map.ofList\n    table, List.last forms\n\n/// A reference resolved through the table.\n[<CompiledName(\"Resolve\")>]\nlet resolve (d: Descriptor) (table: Map<string, Descriptor>) =\n    match d with\n    | Forms [ Atom \"ref\"; name ] -> table.[unquote name]\n    | _ -> d\n\nlet private bound d =\n    match d with\n    | Number n -> Some n\n    | Hole -> None\n    | _ -> fail \"InvalidDescriptorBound\"\n\nlet private generationBounds lo hi =\n    match lo, hi with\n    | None, None -> BigInteger(-1000000), BigInteger 1000000\n    | None, Some h -> BigInteger.Min(BigInteger(-1000000), h - BigInteger 2000000), h\n    | Some l, None -> l, BigInteger.Max(BigInteger 1000000, l + BigInteger 2000000)\n    | Some l, Some h -> l, h\n\nlet rec private mentionsData d =\n    match d with\n    | Forms(Atom \"ref\" :: _) -> true\n    | Forms(Atom \"data\" :: _) -> true\n    | Forms(_ :: fields) -> List.exists mentionsData fields\n    | _ -> false\n\nlet private constructorsOf d =\n    match d with\n    | Forms(Atom \"data\" :: _ :: cs) -> cs\n    | _ -> fail \"InvalidDataDescriptor\"\n\nlet private baseConstructors cs =\n    let found = cs |> List.filter (function Forms(Atom \"ctor\" :: _ :: fields) -> not (List.exists mentionsData fields) | _ -> false)\n    if List.isEmpty found then cs else found\n\nlet private below (n: BigInteger) state = Random.below n state\n\nlet private drawN count draw state =\n    let mutable s = state\n    let values =\n        [ for _ in 1 .. count ->\n              let v, next = draw s\n              s <- next\n              v ]\n    values, s\n\nlet private drawN' items draw state =\n    let mutable s = state\n    let values =\n        [ for item in items ->\n              let v, next = draw item s\n              s <- next\n              v ]\n    values, s\n\n/// A value drawn from a descriptor at a size, and the next state. Every draw,\n/// including each boundary choice, follows the portable algorithm.\n[<CompiledName(\"Generate\")>]\nlet rec generate (d: Descriptor) (table: Map<string, Descriptor>) (state: Random.Seed) (size: int) : Value * Random.Seed =\n    match resolve d table with\n    | Forms [ Atom \"int\"; _; lo; hi ] ->\n        let lo, hi = generationBounds (bound lo) (bound hi)\n        let choice, s1 = below (BigInteger 10) state\n        if choice < BigInteger 2 then\n            let i, s2 = below (BigInteger 4) s1\n            let options = [ lo; hi; BigInteger.Min(BigInteger.Max(BigInteger.Zero, lo), hi); BigInteger.Min(BigInteger.Max(BigInteger.One, lo), hi) ]\n            Int(List.item (int i) options), s2\n        else\n            let n, s2 = below (hi - lo + BigInteger.One) s1\n            Int(lo + n), s2\n    | Forms [ Atom \"bool\" ] ->\n        let n, next = below (BigInteger 2) state\n        Bool n.IsOne, next\n    | Forms [ Atom \"text\" ] ->\n        let count, s1 = below (BigInteger(size + 1)) state\n        let chars, s2 = drawN (int count) (fun s -> let n, s0 = below (BigInteger 95) s in int n + 32, s0) s1\n        Text(String(chars |> List.map char |> Array.ofList)), s2\n    | Forms [ Atom \"unit\" ] -> Unit, state\n    | Forms [ Atom \"list\"; item ] ->\n        let count, s1 = below (BigInteger(size + 1)) state\n        let items, s2 = drawN (int count) (fun s -> generate item table s size) s1\n        List items, s2\n    | Forms [ Atom \"maybe\"; item ] ->\n        let choice, s1 = below (BigInteger 4) state\n        if choice.IsZero then Data(\"Maybe::Nothing\", []), s1\n        else\n            let v, s2 = generate item table s1 size\n            Data(\"Maybe::Just\", [ v ]), s2\n    | Forms [ Atom \"either\"; left; right ] ->\n        let choice, s1 = below (BigInteger 2) state\n        let tag, inner = if choice.IsZero then \"Either::Left\", left else \"Either::Right\", right\n        let v, s2 = generate inner table s1 size\n        Data(tag, [ v ]), s2\n    | Forms(Atom \"data\" :: _ :: cs) ->\n        let choices = if size = 0 then baseConstructors cs else cs\n        let i, s1 = below (BigInteger(List.length choices)) state\n        match List.item (int i) choices with\n        | Forms(Atom \"ctor\" :: tag :: fields) ->\n            let values, s2 = drawN' fields (fun field s -> generate field table s (max (size - 1) 0)) s1\n            Data(unquote tag, values), s2\n        | _ -> fail \"InvalidConstructorDescriptor\"\n    | other -> Fail.raiseWith \"UnsupportedGenerationDescriptor\" (sprintf \"%A\" other)\n\n/// The smallest value of a descriptor.\n[<CompiledName(\"Minimal\")>]\nlet rec minimal (d: Descriptor) (table: Map<string, Descriptor>) : Value =\n    match resolve d table with\n    | Forms [ Atom \"int\"; _; lo; hi ] ->\n        let lo, hi = generationBounds (bound lo) (bound hi)\n        Int(BigInteger.Min(BigInteger.Max(BigInteger.Zero, lo), hi))\n    | Forms [ Atom \"bool\" ] -> Bool false\n    | Forms [ Atom \"text\" ] -> Text \"\"\n    | Forms [ Atom \"unit\" ] -> Unit\n    | Forms [ Atom \"list\"; _ ] -> List []\n    | Forms [ Atom \"maybe\"; _ ] -> Data(\"Maybe::Nothing\", [])\n    | Forms [ Atom \"either\"; left; _ ] -> Data(\"Either::Left\", [ minimal left table ])\n    | Forms(Atom \"data\" :: _ :: cs) ->\n        match baseConstructors cs with\n        | Forms(Atom \"ctor\" :: tag :: fields) :: _ -> Data(unquote tag, fields |> List.map (fun f -> minimal f table))\n        | _ -> fail \"InvalidDataDescriptor\"\n    | other -> Fail.raiseWith \"UnsupportedGenerationDescriptor\" (sprintf \"%A\" other)\n\nlet private shrinkSequence (values: 'a list) =\n    match values with\n    | [] -> []\n    | _ ->\n        [ []; List.take (List.length values / 2) values ]\n        @ [ for i in 0 .. List.length values - 1 -> List.removeAt i values ]\n\nlet private replaceShrinks (values: Value list) (shrink: Value -> Value list) =\n    [ for i, v in List.indexed values do\n          for c in shrink v -> List.updateAt i c values ]\n\nlet private constructorOf tag cs =\n    match cs |> List.filter (function Forms(Atom \"ctor\" :: t :: _) -> unquote t = tag | _ -> false) with\n    | [ c ] -> c\n    | _ -> Fail.raiseWith \"ForeignWireConstructor\" tag\n\n/// The candidates a value shrinks to, in the portable order, without\n/// duplicates or the value itself.\n[<CompiledName(\"Shrink\")>]\nlet rec shrink (d: Descriptor) (value: Value) (table: Map<string, Descriptor>) : Value list =\n    let candidates = shrinkResolved (resolve d table) value table\n    let seen = System.Collections.Generic.HashSet<Value>(HashIdentity.Structural)\n    seen.Add value |> ignore\n    candidates |> List.filter (fun c -> seen.Add c)\n\nand private shrinkResolved d value table =\n    match d, value with\n    | Forms [ Atom \"int\"; _; _; _ ], Int v ->\n        match minimal d table with\n        | Int target when v = target -> []\n        | Int target ->\n            let half = BigInteger.Divide(v - target, BigInteger 2)\n            [ Int target; Int(v - half); Int(v - (if v > target then BigInteger.One else BigInteger.MinusOne)) ]\n        | _ -> []\n    | Forms [ Atom \"bool\" ], Bool true -> [ Bool false ]\n    | Forms [ Atom \"bool\" ], Bool false -> []\n    | Forms [ Atom \"text\" ], Text s -> shrinkSequence (Scalar.codePoints s) |> List.map (Scalar.textOfPoints >> Text)\n    | Forms [ Atom \"list\"; item ], List items ->\n        (shrinkSequence items |> List.map List) @ (replaceShrinks items (fun v -> shrink item v table) |> List.map List)\n    | Forms [ Atom \"maybe\"; item ], Data(\"Maybe::Just\", [ v ]) ->\n        Data(\"Maybe::Nothing\", []) :: (shrink item v table |> List.map (fun c -> Data(\"Maybe::Just\", [ c ])))\n    | Forms [ Atom \"maybe\"; _ ], Data(\"Maybe::Nothing\", []) -> []\n    | Forms [ Atom \"either\"; left; right ], Data(tag, [ v ]) ->\n        let inner = if tag = \"Either::Left\" then left else right\n        shrink inner v table |> List.map (fun c -> Data(tag, [ c ]))\n    | Forms(Atom \"data\" :: name :: cs), Data(tag, fields) ->\n        let fieldDescriptors =\n            match constructorOf tag cs with\n            | Forms(Atom \"ctor\" :: _ :: ds) -> ds\n            | _ -> []\n        let recursive = Forms [ Atom \"ref\"; name ]\n        [ minimal d table ]\n        @ [ for f, fd in List.zip fields fieldDescriptors do if fd = recursive then yield f ]\n        @ [ for i, fd in List.indexed fieldDescriptors do\n                for c in shrink fd (List.item i fields) table -> Data(tag, List.updateAt i c fields) ]\n    | Forms [ Atom \"unit\" ], Unit -> []\n    | _ -> fail \"InvalidShrinkValue\"\n\nlet private quote (s: string) = \"\\\"\" + s.Replace(\"\\\\\", \"\\\\\\\\\").Replace(\"\\\"\", \"\\\\\\\"\") + \"\\\"\"\n\n/// A value as the portable runtimes print it.\n[<CompiledName(\"Render\")>]\nlet rec render (value: Value) : string =\n    match value with\n    | Bool true -> \"true\"\n    | Bool false -> \"false\"\n    | Unit -> \"()\"\n    | Int n -> n.ToString()\n    | Text s -> quote s\n    | List items -> \"[\" + String.Join(\", \", items |> List.map render) + \"]\"\n    | Data(tag, fields) ->\n        let parts = tag.Split(\"::\")\n        let name = parts.[parts.Length - 1]\n        if List.isEmpty fields then name else name + \"(\" + String.Join(\", \", fields |> List.map render) + \")\"\n    | other -> sprintf \"%A\" other\n\n// ---------------------------------------------------------------------------\n// The canonical wire: zigzag varints, length-prefixed bytes, constructor\n// indices. ref:DEC-distribution-canonical-wire\n\n/// A non-negative integer as LEB128.\n[<CompiledName(\"Varint\")>]\nlet varint (n: BigInteger) : byte[] =\n    if n.Sign < 0 then fail \"NegativeVarint\"\n    let bytes = ResizeArray<byte>()\n    let mutable rest = n\n    let mutable go = true\n    while go do\n        let low = int (rest &&& BigInteger 127)\n        rest <- rest >>> 7\n        if rest.IsZero then\n            bytes.Add(byte low)\n            go <- false\n        else bytes.Add(byte (low ||| 128))\n    bytes.ToArray()\n\n/// A LEB128 integer at a position, and the position after it.\n[<CompiledName(\"ReadVarint\")>]\nlet readVarint (bytes: byte[]) (start: int) : BigInteger * int =\n    let mutable n = BigInteger.Zero\n    let mutable shift = 0\n    let mutable i = start\n    let mutable go = true\n    while go do\n        if i >= bytes.Length then fail \"TruncatedWireValue\"\n        let b = bytes.[i]\n        n <- n ||| (BigInteger(int b &&& 127) <<< shift)\n        shift <- shift + 7\n        i <- i + 1\n        if b < 128uy then go <- false\n    n, i\n\nlet private checkInteger (v: BigInteger) lo hi =\n    let ok = (match bound lo with Some l -> v >= l | None -> true) && (match bound hi with Some h -> v <= h | None -> true)\n    if not ok then fail \"WireIntegerOutOfRange\"\n\nlet rec private put (d: Descriptor) (value: Value) (table: Map<string, Descriptor>) (out: MemoryStream) =\n    let write (bytes: byte[]) = out.Write(bytes, 0, bytes.Length)\n    match resolve d table, value with\n    | Forms [ Atom \"int\"; _; lo; hi ], Int v ->\n        checkInteger v lo hi\n        write (varint (if v.Sign >= 0 then v * BigInteger 2 else -v * BigInteger 2 - BigInteger.One))\n    | Forms [ Atom \"bool\" ], Bool b -> out.WriteByte(if b then 1uy else 0uy)\n    | Forms [ Atom \"unit\" ], Unit -> ()\n    | Forms [ Atom(\"text\" | \"end\") ], Text s ->\n        let bytes = Encoding.UTF8.GetBytes s\n        write (varint (BigInteger bytes.Length))\n        write bytes\n    | Forms [ Atom(\"bytes\" | \"end\") ], Bytes b ->\n        write (varint (BigInteger b.Length))\n        write b\n    | Forms [ Atom \"list\"; item ], List items ->\n        write (varint (BigInteger(List.length items)))\n        for v in items do put item v table out\n    | Forms [ Atom \"maybe\"; _ ], Data(\"Maybe::Nothing\", []) -> out.WriteByte 0uy\n    | Forms [ Atom \"maybe\"; item ], Data(\"Maybe::Just\", [ v ]) ->\n        out.WriteByte 1uy\n        put item v table out\n    | Forms [ Atom \"either\"; left; _ ], Data(\"Either::Left\", [ v ]) ->\n        out.WriteByte 0uy\n        put left v table out\n    | Forms [ Atom \"either\"; _; right ], Data(\"Either::Right\", [ v ]) ->\n        out.WriteByte 1uy\n        put right v table out\n    | Forms(Atom \"data\" :: _ :: cs), Data(tag, fields) ->\n        let c = constructorOf tag cs\n        let ds = match c with Forms(Atom \"ctor\" :: _ :: ds) -> ds | _ -> []\n        require (List.length ds = List.length fields) \"WireFieldCount\"\n        let index = cs |> List.findIndex (fun other -> other = c)\n        write (varint (BigInteger index))\n        for fd, v in List.zip ds fields do put fd v table out\n    | other, _ -> Fail.raiseWith \"InvalidWireValue\" (sprintf \"%A\" other)\n\n/// A value's canonical wire bytes.\n[<CompiledName(\"Encode\")>]\nlet encode (d: Descriptor) (value: Value) (table: Map<string, Descriptor>) : byte[] =\n    use out = new MemoryStream()\n    put d value table out\n    out.ToArray()\n\nlet rec private get (d: Descriptor) (bytes: byte[]) (i: int) (table: Map<string, Descriptor>) : Value * int =\n    match resolve d table with\n    | Forms [ Atom \"int\"; _; lo; hi ] ->\n        let z, next = readVarint bytes i\n        let v = if z.IsEven then z / BigInteger 2 else -(z + BigInteger.One) / BigInteger 2\n        checkInteger v lo hi\n        Int v, next\n    | Forms [ Atom \"bool\" ] ->\n        require (i < bytes.Length && bytes.[i] < 2uy) \"InvalidWireValue\"\n        Bool(bytes.[i] = 1uy), i + 1\n    | Forms [ Atom \"unit\" ] -> Unit, i\n    | Forms [ Atom kind ] when kind = \"text\" || kind = \"bytes\" || kind = \"end\" ->\n        let n, start = readVarint bytes i\n        let n = int n\n        require (start + n <= bytes.Length) \"TruncatedWireValue\"\n        let slice = bytes.[start .. start + n - 1]\n        if kind = \"bytes\" then Bytes slice, start + n\n        else\n            let text =\n                try UTF8Encoding(false, true).GetString slice\n                with _ -> fail \"WireInvalidUtf8\"\n            Text text, start + n\n    | Forms [ Atom \"list\"; item ] ->\n        let n, start = readVarint bytes i\n        let mutable position = start\n        let items =\n            [ for _ in 1 .. int n ->\n                  let v, next = get item bytes position table\n                  position <- next\n                  v ]\n        List items, position\n    | Forms [ Atom \"maybe\"; item ] ->\n        require (i < bytes.Length && bytes.[i] < 2uy) \"InvalidWireValue\"\n        if bytes.[i] = 0uy then Data(\"Maybe::Nothing\", []), i + 1\n        else\n            let v, next = get item bytes (i + 1) table\n            Data(\"Maybe::Just\", [ v ]), next\n    | Forms [ Atom \"either\"; left; right ] ->\n        require (i < bytes.Length && bytes.[i] < 2uy) \"InvalidWireValue\"\n        let tag, inner = if bytes.[i] = 0uy then \"Either::Left\", left else \"Either::Right\", right\n        let v, next = get inner bytes (i + 1) table\n        Data(tag, [ v ]), next\n    | Forms(Atom \"data\" :: _ :: cs) ->\n        let index, start = readVarint bytes i\n        require (index < BigInteger(List.length cs)) \"InvalidWireConstructor\"\n        match List.item (int index) cs with\n        | Forms(Atom \"ctor\" :: tag :: ds) ->\n            let mutable position = start\n            let fields =\n                [ for fd in ds ->\n                      let v, next = get fd bytes position table\n                      position <- next\n                      v ]\n            Data(unquote tag, fields), position\n        | _ -> fail \"InvalidWireConstructor\"\n    | other -> Fail.raiseWith \"InvalidWireValue\" (sprintf \"%A\" other)\n\n/// A value from its wire bytes, and the position after it.\n[<CompiledName(\"DecodePrefix\")>]\nlet decodePrefix (d: Descriptor) (bytes: byte[]) (start: int) (table: Map<string, Descriptor>) = get d bytes start table\n\n/// A value from exactly its wire bytes.\n[<CompiledName(\"Decode\")>]\nlet decode (d: Descriptor) (bytes: byte[]) (table: Map<string, Descriptor>) : Value =\n    let v, next = get d bytes 0 table\n    require (next = bytes.Length) \"TrailingWireBytes\"\n    v\n\n/// The values a descriptor text draws from a seed (the generation suite's\n/// conformance vectors).\n[<CompiledName(\"Generated\")>]\nlet generated (text: string) (seed: BigInteger) (size: int) (count: int) : string list =\n    let table, d = fromText text\n    let mutable state = Random.seed seed\n    [ for _ in 1 .. max 0 count ->\n          let v, next = generate d table state size\n          state <- next\n          render v ]\n\n/// The shrink candidates of the first value a descriptor text draws.\n[<CompiledName(\"Shrunk\")>]\nlet shrunk (text: string) (seed: BigInteger) (size: int) : string list =\n    let table, d = fromText text\n    let v, _ = generate d table (Random.seed seed) size\n    shrink d v table |> List.map render\n"
dotnetSource "LawSpec.Runtime/Effects.fs" = "/// Abilities on .NET: lexically scoped handlers, carried in the schema, and\n/// typed failures. A handler is the logical view of an ability's operations;\n/// native code sees the ability's generated interface, and a native handler\n/// becomes a logical one through its generated bridge. State lives in cells\n/// owned by the scope that made the handler, so concurrent steps share it.\n/// ref:DEC-typed-core-boundary ref:DEC-fsharp-runtime-from-scratch\nmodule LawSpec.Runtime.Effects\n\nopen System\nopen System.Collections.Generic\n\n/// An operation's clause: the schema in scope and the arguments to a result.\ntype Clause = Schema.Schema -> Value list -> Value\n\n/// A stateful clause also takes the state, and gives back a pair of the\n/// result and the next state.\ntype StatefulClause = Schema.Schema -> Value list -> Value -> Value\n\n/// Mutable state, read and replaced under a lock.\n[<Sealed>]\ntype Cell(initial: Value) =\n    let mutable value = initial\n    let gate = obj ()\n    member _.Read() = lock gate (fun () -> value)\n    member _.Write(next: Value) = lock gate (fun () -> value <- next)\n    /// Run an update under the cell's lock.\n    member _.Update(update: Value -> 'a * Value) =\n        lock gate (fun () ->\n            let result, next = update value\n            value <- next\n            result)\n\n/// A log of the operations a recording handler saw, in order.\n[<Sealed>]\ntype Log() =\n    let calls = ResizeArray<string * Value list>()\n    member _.Add(operation: string, arguments: Value list) = lock calls (fun () -> calls.Add((operation, arguments)))\n    member _.Calls = lock calls (fun () -> List.ofSeq calls)\n\ntype Handler =\n    | Stateless of Map<string, Clause>\n    | Stateful of Cell * Map<string, StatefulClause>\n    | Recording of Log * Handler\n\n/// A handler scope: it owns the handlers of several abilities made once in\n/// it, and is closed when its body ends.\n[<Sealed>]\ntype Scope() =\n    let shared = Dictionary<string, Handler>()\n    member _.Shared(key: string, make: unit -> Handler) =\n        lock shared (fun () ->\n            match shared.TryGetValue key with\n            | true, h -> h\n            | _ ->\n                let h = make ()\n                shared.[key] <- h\n                h)\n\n/// A native interface made from a logical handler keeps it, so the handler\n/// is recovered, with its state, when the interface crosses back.\ntype IOrigin =\n    abstract Ability: string\n    abstract Symbols: Scalar.SymbolContext\n    abstract Handler: Handler\n    abstract Schema: Schema.Schema\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n/// A handler with no state.\n[<CompiledName(\"Stateless\")>]\nlet stateless (clauses: (string * Clause) list) = Stateless(Map.ofList clauses)\n\n/// A handler with state, from its start.\n[<CompiledName(\"Stateful\")>]\nlet stateful (initial: Value) (clauses: (string * StatefulClause) list) = Stateful(Cell initial, Map.ofList clauses)\n\n/// A handler that logs every operation, then runs another.\n[<CompiledName(\"Recording\")>]\nlet recording (inner: Handler) = Recording(Log(), inner)\n\n/// Handlers installed in a schema, overriding outer ones.\n[<CompiledName(\"Install\")>]\nlet install (schema: Schema.Schema) (handlers: (string * Handler) list) =\n    { schema with Handlers = handlers |> List.fold (fun table (key, h) -> Map.add key (box h) table) schema.Handlers }\n\n/// The handler of an ability in scope.\n[<CompiledName(\"Handler\")>]\nlet handler (schema: Schema.Schema) (ability: string) : Handler =\n    match schema.Handlers.TryFind ability with\n    | Some h -> unbox h\n    | None -> fail \"MissingHandler\" ability\n\n/// Run a body in a new scope with handlers made by factories. A factory\n/// failing leaves no handler behind.\n[<CompiledName(\"WithScope\")>]\nlet withScope (schema: Schema.Schema) (factories: (string * (Schema.Schema -> Handler)) list) (body: Schema.Schema -> 'a) : 'a =\n    let based = { schema with Scope = Some(box (Scope())) }\n    let handlers = factories |> List.map (fun (key, make) -> key, make based)\n    body (install based handlers)\n\n/// A handler of several abilities is made once in a scope, so they share its\n/// state.\n[<CompiledName(\"Shared\")>]\nlet shared (schema: Schema.Schema) (key: string) (make: unit -> Handler) =\n    match schema.Scope with\n    | Some(:? Scope as scope) -> scope.Shared(key, make)\n    | _ -> make ()\n\nlet private clause (clauses: Map<string, 'c>) (operation: string) =\n    match clauses.TryFind operation with\n    | Some c -> c\n    | None -> fail \"MissingHandlerOperation\" operation\n\n/// Run an operation of a handler.\n[<CompiledName(\"Invoke\")>]\nlet rec invoke (h: Handler) (schema: Schema.Schema) (operation: string) (arguments: Value list) : Value =\n    match h with\n    | Stateless clauses -> (clause clauses operation) schema arguments\n    | Stateful(cell, clauses) ->\n        let run = clause clauses operation\n        if schema.EffectPath |> List.exists (fun c -> obj.ReferenceEquals(c, cell)) then\n            fail \"RecursiveHandlerCall\" operation\n        cell.Update(fun state ->\n            match run { schema with EffectPath = box cell :: schema.EffectPath } arguments state with\n            | Data(_, [ result; next ]) -> result, next\n            | other -> fail \"InvalidHandlerResult\" (sprintf \"%A\" other))\n    | Recording(log, inner) ->\n        log.Add(operation, arguments)\n        invoke inner schema operation arguments\n\n/// Perform an operation of an ability through the handler in scope.\n[<CompiledName(\"Perform\")>]\nlet perform (schema: Schema.Schema) (ability: string) (operation: string) (arguments: Value list) =\n    invoke (handler schema ability) schema operation arguments\n\n/// How many times a recording handler saw an operation (with arguments, if\n/// given).\n[<CompiledName(\"CountCalls\")>]\nlet countCalls (schema: Schema.Schema) (ability: string) (operation: string) (arguments: Value list option) : Value =\n    match handler schema ability with\n    | Recording(log, _) ->\n        log.Calls\n        |> List.filter (fun (name, values) ->\n            name = operation && (match arguments with None -> true | Some args -> Scalar.equal (Value.List values) (Value.List args)))\n        |> List.length\n        |> bigint\n        |> Int\n    | _ -> fail \"RecordingRequired\" ability\n\n/// Raise a typed failure of a Fail ability.\n[<CompiledName(\"RaiseFailure\")>]\nlet raiseFailure (ability: string) (failure: Value) : Value = raise (RaisedFailure(ability, failure))\n\n/// Catch a typed failure: Right of the body's value, or Left of the failure.\n[<CompiledName(\"Attempt\")>]\nlet attempt (ability: string) (body: unit -> Value) (right: Value -> Value) (left: Value -> Value) : Value =\n    let outcome =\n        try Choice1Of2(body ())\n        with :? RaisedFailure as f when f.Ability = ability -> Choice2Of2 f.Failure\n    match outcome with\n    | Choice1Of2 v -> right v\n    | Choice2Of2 f -> left f\n\n/// A native adapter's Result: its value, or its error raised as the failure.\n[<CompiledName(\"OfResult\")>]\nlet ofResult (ability: string) (convert: 'E -> Value) (result: Result<'T, 'E>) : 'T =\n    match result with\n    | Ok value -> value\n    | Error failure -> raise (RaisedFailure(ability, convert failure))\n\n/// Exceptions of mapped .NET types become typed failures; the others pass.\n[<CompiledName(\"NativeFailures\")>]\nlet nativeFailures (ability: string) (body: unit -> Value) (mappings: (exn -> Value option) list) : Value =\n    try body () with\n    | :? RaisedFailure -> reraise ()\n    | :? LawSpecException -> reraise ()\n    | e ->\n        match mappings |> List.tryPick (fun m -> m e) with\n        | Some failure -> raise (RaisedFailure(ability, failure))\n        | None -> reraise ()\n\n/// A logical failure crossing to native code: the Result its native form returns.\n[<CompiledName(\"NativeTry\")>]\nlet nativeTry (ability: string) (convert: Value -> 'E) (body: unit -> 'T) : Result<'T, 'E> =\n    try Ok(body ()) with\n    | :? RaisedFailure as f when f.Ability = ability -> Error(convert f.Failure)\n\n/// The handler behind a native interface, if it came from a logical one with\n/// the same symbols.\n[<CompiledName(\"Recover\")>]\nlet recover (native: obj) (ability: string) (symbols: Scalar.SymbolContext) (make: unit -> Handler) : Handler =\n    match native with\n    | :? IOrigin as origin when origin.Ability = ability && obj.ReferenceEquals(origin.Symbols, symbols) -> origin.Handler\n    | :? IOrigin as origin when origin.Ability = ability -> make ()\n    | _ -> make ()\n\nlet rec private stateCell (h: Handler) =\n    match h with\n    | Stateful(cell, _) -> cell\n    | Recording(_, inner) -> stateCell inner\n    | Stateless _ -> fail \"StatelessHandler\" \"\"\n\n/// A spec handler's state, through its native interface.\n[<CompiledName(\"HandlerState\")>]\nlet handlerState (native: obj) : Schema.Schema * Value =\n    match native with\n    | :? IOrigin as origin -> origin.Schema, (stateCell origin.Handler).Read()\n    | _ -> fail \"StatelessHandler\" \"a native handler has no LawSpec state\"\n\n/// Replace a spec handler's state, through its native interface.\n[<CompiledName(\"SetHandlerState\")>]\nlet setHandlerState (native: obj) (state: Value) =\n    match native with\n    | :? IOrigin as origin -> (stateCell origin.Handler).Write state\n    | _ -> fail \"StatelessHandler\" \"a native handler has no LawSpec state\"\n\n/// A cell native code can use for a handler's state.\n[<CompiledName(\"NewCell\")>]\nlet newCell (initial: Value) = Cell initial\n\n/// A production handler made with a resource, asked for where no case has one.\n[<CompiledName(\"ResourceRequired\")>]\nlet resourceRequired (ability: string) : Handler = fail \"ResourceRequired\" ability\n"
dotnetSource "LawSpec.Runtime/LawSpec.Runtime.fsproj" = "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <!-- Generated by LawSpec. Do not edit. The LawSpec runtime for F# and C#. -->\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n    <Nullable>disable</Nullable>\n    <TreatWarningsAsErrors>true</TreatWarningsAsErrors>\n    <GenerateDocumentationFile>false</GenerateDocumentationFile>\n    <IsPackable>false</IsPackable>\n  </PropertyGroup>\n  <ItemGroup>\n    <Compile Include=\"Values.fs\" />\n    <Compile Include=\"Native.fs\" />\n    <Compile Include=\"Scalar.fs\" />\n    <Compile Include=\"Regex.fs\" />\n    <Compile Include=\"Random.fs\" />\n    <Compile Include=\"Descriptors.fs\" />\n    <Compile Include=\"Schema.fs\" />\n    <Compile Include=\"Recorded.fs\" />\n    <Compile Include=\"Portable.fs\" />\n    <Compile Include=\"Codecs.fs\" />\n    <Compile Include=\"Effects.fs\" />\n    <Compile Include=\"Defaults.fs\" />\n    <Compile Include=\"Crypto.fs\" />\n    <Compile Include=\"NetworkCrypto.fs\" />\n    <Compile Include=\"Runtime.fs\" />\n    <Compile Include=\"Policy.fs\" />\n    <Compile Include=\"Tasks.fs\" />\n    <Compile Include=\"Workflow.fs\" />\n    <Compile Include=\"Actors.fs\" />\n  </ItemGroup>\n  <ItemGroup>\n    <PackageReference Include=\"BouncyCastle.Cryptography\" Version=\"2.7.0\" />\n  </ItemGroup>\n</Project>\n"
dotnetSource "LawSpec.Runtime/Native.fs" = "/// The .NET types LawSpec values take at the native boundary, where a .NET\n/// type has no exact counterpart: exact fractions and decimals, single\n/// precision complex numbers, the two kinds of presence, and symbols. Every\n/// other LawSpec type maps to a .NET type directly (sbyte ... uint64, bigint,\n/// string, byte[], list, option, Rune). ref:DEC-fsharp-runtime-from-scratch\nnamespace LawSpec\n\nopen System.Numerics\n\n/// An exact fraction in lowest terms, with a positive denominator.\n[<CustomEquality; CustomComparison>]\ntype Rational =\n    private { N: BigInteger; D: BigInteger }\n    member this.Numerator = this.N\n    member this.Denominator = this.D\n    static member Create(numerator: BigInteger, denominator: BigInteger) =\n        if denominator.IsZero then invalidArg (nameof denominator) \"a rational's denominator is not zero\"\n        let g = BigInteger.GreatestCommonDivisor(numerator, denominator)\n        let s = if denominator.Sign < 0 then BigInteger.MinusOne else BigInteger.One\n        { N = s * numerator / g; D = BigInteger.Abs denominator / g }\n    override this.Equals other =\n        match other with\n        | :? Rational as r -> this.N = r.N && this.D = r.D\n        | _ -> false\n    override this.GetHashCode() = hash (this.N, this.D)\n    override this.ToString() = sprintf \"%O/%O\" this.N this.D\n    interface System.IComparable with\n        member this.CompareTo other =\n            match other with\n            | :? Rational as r -> compare (this.N * r.D) (r.N * this.D)\n            | _ -> invalidArg \"other\" \"a rational compares with a rational\"\n\n/// coefficient * 10 ^ exponent, exactly; 1.50 keeps its two places.\n[<Struct; CustomEquality; NoComparison>]\ntype ExactDecimal =\n    { Coefficient: BigInteger\n      Exponent: int }\n    override this.Equals other =\n        match other with\n        | :? ExactDecimal as d -> this.Coefficient = d.Coefficient && this.Exponent = d.Exponent\n        | _ -> false\n    override this.GetHashCode() = hash (this.Coefficient, this.Exponent)\n    override this.ToString() = sprintf \"%Oe%d\" this.Coefficient this.Exponent\n    /// Both decimals at the smaller exponent.\n    static member private Aligned(a: ExactDecimal, b: ExactDecimal) =\n        let e = min a.Exponent b.Exponent\n        let scale (d: ExactDecimal) = d.Coefficient * BigInteger.Pow(BigInteger 10, d.Exponent - e)\n        scale a, scale b, e\n    /// Exact sum, at the finer of the two scales.\n    static member (+)(a: ExactDecimal, b: ExactDecimal) =\n        let x, y, e = ExactDecimal.Aligned(a, b)\n        { Coefficient = x + y; Exponent = e }\n    /// Exact difference, at the finer of the two scales.\n    static member (-)(a: ExactDecimal, b: ExactDecimal) =\n        let x, y, e = ExactDecimal.Aligned(a, b)\n        { Coefficient = x - y; Exponent = e }\n    /// Exact product.\n    static member (*)(a: ExactDecimal, b: ExactDecimal) =\n        { Coefficient = a.Coefficient * b.Coefficient; Exponent = a.Exponent + b.Exponent }\n\n/// A complex number of two single precision floats (Complex128 is\n/// System.Numerics.Complex).\n[<Struct>]\ntype Complex64 = { Real: float32; Imaginary: float32 }\n\n/// A value that may be null, distinct from an absent Optional.\n[<RequireQualifiedAccess>]\ntype Nullable<'T> =\n    | Null\n    | Present of 'T\n\n/// A value that may be undefined, distinct from a null Nullable.\n[<RequireQualifiedAccess>]\ntype Optional<'T> =\n    | Undefined\n    | Present of 'T\n\n/// Either of two values; Left conventionally the failure.\n[<RequireQualifiedAccess>]\ntype Either<'L, 'R> =\n    | Left of left: 'L\n    | Right of right: 'R\n\n/// LawSpec's Null value.\ntype Null = | Null\n\n/// LawSpec's Undefined value.\ntype Undefined = | Undefined\n\n/// A symbol: equal only to itself.\n[<Sealed; AllowNullLiteral>]\ntype Symbol(identity: obj, description: string) =\n    new(description) = Symbol(obj (), description)\n    member _.Identity = identity\n    member _.Description = description\n    override _.Equals other =\n        match other with\n        | :? Symbol as s -> obj.ReferenceEquals(identity, s.Identity)\n        | _ -> false\n    override _.GetHashCode() = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode identity\n    override _.ToString() = \"Symbol(\" + description + \")\"\n"
dotnetSource "LawSpec.Runtime/NetworkCrypto.fs" = "/// The secure transport's version 1 records (\"LS\" 1): a node's ML-DSA-65\n/// identity, the signed hello and welcome of the ML-KEM-768 handshake, the\n/// session key derived with SHAKE256, and AES-256-GCM sealed frames. The\n/// bytes are the same as every other target's, so nodes interoperate.\n/// ref:DEC-distribution-canonical-wire ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.NetworkCrypto\n\nopen System.Text\n\n/// A node's identity: its signing seed and public key.\ntype Identity =\n    private { Seed: byte[]; PublicKey: byte[] }\n    member this.Public = this.PublicKey\n\nlet private fail code : 'a = Fail.raiseWith code \"\"\n\n/// The identity of a 32-byte seed.\n[<CompiledName(\"Identity\")>]\nlet identity (seed: byte[]) =\n    if isNull seed || seed.Length <> 32 then fail \"InvalidNodeIdentity\"\n    { Seed = Array.copy seed; PublicKey = Crypto.mldsaPublic seed }\n\n[<CompiledName(\"Public\")>]\nlet publicKey (identity: Identity) = identity.PublicKey\n\n/// The lowercase hex SHA3-256 of a node's public key.\n[<CompiledName(\"Fingerprint\")>]\nlet fingerprint (identity: Identity) = (System.Convert.ToHexString(Crypto.sha3 identity.PublicKey)).ToLowerInvariant()\n\n[<CompiledName(\"Sign\")>]\nlet sign (identity: Identity) (bytes: byte[]) = Crypto.mldsaSign identity.Seed bytes\n\n[<CompiledName(\"Verify\")>]\nlet verify (publicKey: byte[]) (bytes: byte[]) (signature: byte[]) = Crypto.mldsaVerify publicKey bytes signature\n\nlet private bytesType = Descriptors.Forms [ Descriptors.Atom \"bytes\" ]\n\n/// Byte strings as consecutive length-prefixed wire fields.\n[<CompiledName(\"Fields\")>]\nlet fields (values: byte[] list) : byte[] =\n    values |> List.map (fun v -> Descriptors.encode bytesType (Bytes v) Map.empty) |> Array.concat\n\nlet private readFields (count: int) (bytes: byte[]) (start: int) =\n    let mutable position = start\n    let values =\n        [ for _ in 1 .. count ->\n              match Descriptors.decodePrefix bytesType bytes position Map.empty with\n              | Bytes b, next ->\n                  position <- next\n                  b\n              | _ -> fail \"InvalidSecureRecord\" ]\n    values, position\n\n/// A handshake hello: session, address, public key and KEM public key.\n[<CompiledName(\"Hello\")>]\nlet hello (session: byte[]) (address: byte[]) (publicKey: byte[]) (kem: byte[]) = fields [ session; address; publicKey; kem ]\n\n/// A handshake welcome, bound to the hello it answers.\n[<CompiledName(\"Welcome\")>]\nlet welcome (session: byte[]) (address: byte[]) (publicKey: byte[]) (ciphertext: byte[]) (helloBytes: byte[]) =\n    fields [ session; address; publicKey; ciphertext; Crypto.sha3 helloBytes ]\n\n/// The session key of a shared secret and the handshake that agreed it.\n[<CompiledName(\"Key\")>]\nlet key (shared: byte[]) (helloBytes: byte[]) (welcomeBytes: byte[]) =\n    Crypto.shake (Array.concat [ shared; Encoding.ASCII.GetBytes \"lawspec-session-v1\"; Crypto.sha3 helloBytes; Crypto.sha3 welcomeBytes ]) 32\n\n/// A signed handshake record of a kind (1 hello, 2 welcome).\n[<CompiledName(\"Record\")>]\nlet record (kind: byte) (body: byte[]) (signature: byte[]) =\n    Array.concat [ [| byte 'L'; byte 'S'; 1uy; kind |]; body; fields [ signature ] ]\n\n/// A record as read off the wire.\ntype Read =\n    /// A hello (1) or welcome (2): its fields, the signed body and the signature.\n    | Handshake of kind: int * values: byte[] list * body: byte[] * signature: byte[]\n    /// A sealed frame: session, direction and sealed bytes.\n    | Frame of session: byte[] * direction: byte * sealedBytes: byte[]\n\n/// Read a version 1 record.\n[<CompiledName(\"Read\")>]\nlet read (bytes: byte[]) : Read =\n    if bytes.Length < 4 || bytes.[0] <> byte 'L' || bytes.[1] <> byte 'S' || bytes.[2] <> 1uy then fail \"InvalidSecureRecord\"\n    match bytes.[3] with\n    | 1uy | 2uy as kind ->\n        let count = if kind = 1uy then 4 else 5\n        let values, bodyEnd = readFields count bytes 4\n        let signature, finish = readFields 1 bytes bodyEnd\n        if finish <> bytes.Length then fail \"InvalidSecureRecord\"\n        Handshake(int kind, values, bytes.[4 .. bodyEnd - 1], List.head signature)\n    | 3uy ->\n        let session, next = readFields 1 bytes 4\n        if next >= bytes.Length then fail \"InvalidSecureRecord\"\n        let direction = bytes.[next]\n        let sealedField, finish = readFields 1 bytes (next + 1)\n        if finish <> bytes.Length then fail \"InvalidSecureRecord\"\n        Frame(List.head session, direction, List.head sealedField)\n    | _ -> fail \"InvalidSecureRecord\"\n\nlet private associated (session: byte[]) (direction: byte) =\n    Array.concat [ Encoding.ASCII.GetBytes \"lawspec-frame-v1\"; session; [| direction |] ]\n\n/// A frame sealed with a given nonce.\n[<CompiledName(\"SealWith\")>]\nlet sealWith (key: byte[]) (session: byte[]) (direction: byte) (frame: byte[]) (nonce: byte[]) =\n    let sealedBytes = Array.append nonce (Crypto.aes256GcmEncrypt key nonce frame (associated session direction))\n    Array.concat [ [| byte 'L'; byte 'S'; 1uy; 3uy |]; fields [ session ]; [| direction |]; fields [ sealedBytes ] ]\n\n/// A frame sealed with a fresh nonce.\n[<CompiledName(\"Seal\")>]\nlet seal (key: byte[]) (session: byte[]) (direction: byte) (frame: byte[]) = sealWith key session direction frame (Crypto.randomBytes 12)\n\n/// Open a sealed frame's bytes, or None.\n[<CompiledName(\"Open\")>]\nlet openFrame (key: byte[]) (session: byte[]) (direction: byte) (sealedBytes: byte[]) =\n    Crypto.unseal key sealedBytes (associated session direction)\n"
dotnetSource "LawSpec.Runtime/Policy.fs" = "/// Workflow policies as values: retry strategies and their delays, jitter\n/// drawn from an explicit SplitMix64 state, the gates a stage passes\n/// (breakers, rate limits, bulkheads) and the logical failures a stage gives.\n/// Durations are whole microseconds. The policy's random stream is separate\n/// from the Random ability's. ref:DEC-domain-modeling-primitives ref:splitmix\n/// ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Policy\n\nopen System.Numerics\n\n/// How long to wait before each retry.\ntype Strategy =\n    | Immediate\n    | Fixed of delay: int64\n    | Linear of delay: int64 * step: int64\n    | Exponential of delay: int64 * factor: int64 * cap: int64 option\n    | Fibonacci of delay: int64\n    /// A checked definition decides: attempt (Int), error, previous delay\n    /// (a Duration) to a RetryDecision.\n    | Custom of decide: (Value -> Value -> Value -> Value)\n\n/// How a delay is randomized.\ntype Jitter =\n    | NoJitter\n    | FullJitter\n    | EqualJitter\n    | DecorrelatedJitter\n\n/// Attempts count the first try; zero attempts retries without a bound.\ntype Retry =\n    { Strategy: Strategy\n      Attempts: int64\n      Jitter: Jitter\n      /// Whether an error is worth retrying (a portable Bool).\n      When: (Value -> Value) option }\n\ntype GateKind =\n    | Breaker\n    | Limit\n    | Bulkhead\n\n/// How long a stage may wait at a gate that answers WaitFor.\ntype Wait =\n    | NoWait\n    | Forever\n    | Within of int64\n\n/// A gate: its state starts at a time, admits at a time (giving the next\n/// state and a Gate decision), and may record how an admitted call ended.\n/// Times are portable Ints, the outcome a portable Bool.\ntype Gate =\n    { Kind: GateKind\n      Start: Value -> Value\n      Admit: Value -> Value -> Value\n      Finish: (Value -> Value -> Value -> Value) option\n      Wait: Wait }\n\n/// A stage's policies, as a definition with a policy declares them.\ntype StagePolicy =\n    { Key: string\n      Stage: string\n      Retry: Retry option\n      Timeout: int64 option\n      Gates: Gate list\n      Cache: int64 option\n      Compensate: (Value -> Value) option\n      Wraps: bool\n      /// A further attempt starts after the delay, up to most in all.\n      Hedge: (int64 * int64) option }\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\nlet rec private power (b: int64) (n: int64) : int64 =\n    if n = 0L then 1L\n    elif n % 2L = 0L then power (b * b) (n / 2L)\n    else b * power (b * b) (n / 2L)\n\nlet rec private fibonacci (n: int64) (a: int64) (b: int64) = if n <= 1L then a else fibonacci (n - 1L) b (a + b)\n\n/// The delay before an attempt (from the second) of a strategy.\n[<CompiledName(\"RetryDelay\")>]\nlet retryDelay (strategy: Strategy) (attempt: int64) : int64 =\n    if attempt < 2L then fail \"InvalidRetryAttempt\" (string attempt)\n    match strategy with\n    | Immediate -> 0L\n    | Fixed delay -> delay\n    | Linear(delay, step) -> delay + step * (attempt - 2L)\n    | Exponential(delay, factor, cap) ->\n        let value = delay * power factor (attempt - 2L)\n        match cap with\n        | Some c -> min value c\n        | None -> value\n    | Fibonacci delay -> delay * fibonacci (attempt - 1L) 1L 1L\n    | Custom _ -> fail \"CustomRetryDelay\" \"a custom strategy decides its own delays\"\n\nlet private below (bound: int64) state =\n    let n, next = Random.below (BigInteger bound) state\n    int64 n, next\n\n/// A jittered delay and the next random state.\n[<CompiledName(\"Jittered\")>]\nlet jitter (kind: Jitter) (delay: int64) (previous: int64) (baseDelay: int64) (state: Random.Seed) : int64 * Random.Seed =\n    match kind with\n    | NoJitter -> delay, state\n    | FullJitter -> below (delay + 1L) state\n    | EqualJitter ->\n        let half = delay / 2L\n        let r, next = below (delay - half + 1L) state\n        half + r, next\n    | DecorrelatedJitter ->\n        let high = max baseDelay (previous * 3L)\n        let r, next = below (high - baseDelay + 1L) state\n        min delay (baseDelay + r), next\n\n/// A custom strategy's RetryDecision: Some delay to wait, None to stop.\n[<CompiledName(\"RetryDecision\")>]\nlet retryDecision (decision: Value) : int64 option =\n    match decision with\n    | Data(\"lawspec.time::type::RetryDecision::RetryAfter\", [ Data(_, [ Int delay ]) ]) -> Some(int64 delay)\n    | Data(\"lawspec.time::type::RetryDecision::Stop\", []) -> None\n    | other -> fail \"InvalidRetryDecision\" (sprintf \"%A\" other)\n\n/// Whether a stage's result is a failure (a Left).\n[<CompiledName(\"Failed\")>]\nlet failed (result: Value) =\n    match result with\n    | Data(\"Either::Left\", [ _ ]) -> true\n    | _ -> false\n\n/// A stage's own failure: TimedOut, RateLimited, CircuitOpen or Saturated.\n[<CompiledName(\"StageFailure\")>]\nlet stageFailure (kind: string) : Value =\n    match kind with\n    | \"TimedOut\" | \"RateLimited\" | \"CircuitOpen\" | \"Saturated\" ->\n        Data(\"Either::Left\", [ Data(\"lawspec.resilience::type::StageFailure::\" + kind, []) ])\n    | _ -> fail \"UnknownStageFailure\" kind\n\n// ---------------------------------------------------------------------------\n// Builders, as generated code writes a policy\n\n[<CompiledName(\"Immediate\")>]\nlet immediate () = Immediate\n\n[<CompiledName(\"Fixed\")>]\nlet fixedDelay (delay: int64) = Fixed delay\n\n[<CompiledName(\"Linear\")>]\nlet linear (delay: int64) (step: int64) = Linear(delay, step)\n\n[<CompiledName(\"Exponential\")>]\nlet exponential (delay: int64) (factor: int64) (cap: int64 option) = Exponential(delay, factor, cap)\n\n[<CompiledName(\"Fibonacci\")>]\nlet fibonacciDelay (delay: int64) = Fibonacci delay\n\n[<CompiledName(\"Custom\")>]\nlet custom (decide: Value -> Value -> Value -> Value) = Custom decide\n\n/// A jitter by name: none, full, equal or decorrelated.\n[<CompiledName(\"JitterOf\")>]\nlet jitterOf (name: string) =\n    match name with\n    | \"none\" -> NoJitter\n    | \"full\" -> FullJitter\n    | \"equal\" -> EqualJitter\n    | \"decorrelated\" -> DecorrelatedJitter\n    | _ -> fail \"UnknownJitter\" name\n\n[<CompiledName(\"Retry\")>]\nlet retry (strategy: Strategy) (attempts: int64) (jitter: Jitter) (condition: (Value -> Value) option) =\n    { Strategy = strategy; Attempts = attempts; Jitter = jitter; When = condition }\n\n[<CompiledName(\"NoWait\")>]\nlet noWait () = NoWait\n\n[<CompiledName(\"Forever\")>]\nlet forever () = Forever\n\n[<CompiledName(\"Within\")>]\nlet within (micros: int64) = Within micros\n\n[<CompiledName(\"Breaker\")>]\nlet breaker (start: Value -> Value) (admit: Value -> Value -> Value) (finish: Value -> Value -> Value -> Value) =\n    { Kind = Breaker; Start = start; Admit = admit; Finish = Some finish; Wait = NoWait }\n\n[<CompiledName(\"Limit\")>]\nlet limit (start: Value -> Value) (admit: Value -> Value -> Value) (wait: Wait) =\n    { Kind = Limit; Start = start; Admit = admit; Finish = None; Wait = wait }\n\n[<CompiledName(\"Bulkhead\")>]\nlet bulkhead (start: Value -> Value) (admit: Value -> Value -> Value) (finish: Value -> Value -> Value -> Value) (wait: Wait) =\n    { Kind = Bulkhead; Start = start; Admit = admit; Finish = Some finish; Wait = wait }\n\n/// A stage's policy.\n[<CompiledName(\"Stage\")>]\nlet stage (key: string) (stageName: string) (retry: Retry option) (timeout: int64 option) (gates: Gate list)\n          (cache: int64 option) (compensate: (Value -> Value) option) (wraps: bool) (hedge: (int64 * int64) option) =\n    { Key = key; Stage = stageName; Retry = retry; Timeout = timeout; Gates = gates; Cache = cache\n      Compensate = compensate; Wraps = wraps; Hedge = hedge }\n"
dotnetSource "LawSpec.Runtime/Portable.fs" = "/// LawSpec's portable equality, hash and order over native .NET values. The\n/// generated records and unions use it, so a native value orders as its\n/// portable value does on every target: text by code point, constructors by\n/// their identities, fields left to right. ref:DEC-portable-exact-arithmetic\n/// ref:DEC-idiomatic-generated-types\nmodule LawSpec.Runtime.Portable\n\nopen System\nopen System.Collections\nopen System.Numerics\nopen System.Text\nopen LawSpec\n\nlet private noOrder (a: obj) = Fail.raiseWith \"NoPortableOrder\" (if isNull a then \"null\" else a.GetType().Name)\n\n/// Equality: structural, with floats compared by their bits (so it is\n/// reflexive, as .NET collections require).\n[<CompiledName(\"Equal\")>]\nlet rec equal (a: obj) (b: obj) : bool =\n    match a, b with\n    | null, null -> true\n    | null, _ | _, null -> false\n    | (:? float as x), (:? float as y) -> BitConverter.DoubleToInt64Bits x = BitConverter.DoubleToInt64Bits y\n    | (:? float32 as x), (:? float32 as y) -> BitConverter.SingleToInt32Bits x = BitConverter.SingleToInt32Bits y\n    | (:? string as x), (:? string as y) -> String.Equals(x, y, StringComparison.Ordinal)\n    | (:? (byte[]) as x), (:? (byte[]) as y) -> ReadOnlySpan<byte>(x).SequenceEqual(ReadOnlySpan<byte>(y))\n    | (:? IStructuralEquatable as x), _ when not (a :? string) -> x.Equals(b, StructuralComparisons.StructuralEqualityComparer)\n    | _ -> a.Equals b\n\n/// A hash consistent with equal.\n[<CompiledName(\"Hash\")>]\nlet rec hash (a: obj) : int =\n    match a with\n    | null -> 0\n    | :? float as x -> BitConverter.DoubleToInt64Bits(x).GetHashCode()\n    | :? float32 as x -> BitConverter.SingleToInt32Bits(x)\n    | :? (byte[]) as x ->\n        let mutable h = 17\n        for b in x do h <- h * 31 + int b\n        h\n    | :? IStructuralEquatable as x -> x.GetHashCode(StructuralComparisons.StructuralEqualityComparer)\n    | _ -> a.GetHashCode()\n\n/// Generated records and unions implement this: their CompareTo is the\n/// portable order.\ntype IPortable =\n    inherit IComparable\n\nlet private unionCache = Collections.Concurrent.ConcurrentDictionary<Type, (obj -> int) * (obj -> obj[])>()\n\nlet private unionParts (t: Type) =\n    unionCache.GetOrAdd(t, fun t ->\n        let tag = Reflection.FSharpValue.PreComputeUnionTagReader(t)\n        let readers =\n            Reflection.FSharpType.GetUnionCases(t)\n            |> Array.map (fun c -> Reflection.FSharpValue.PreComputeUnionReader(c))\n        tag, (fun v -> readers.[tag v] v))\n\n/// The portable order of two native values of one type.\n[<CompiledName(\"Compare\")>]\nlet rec compare (a: obj) (b: obj) : int =\n    match a, b with\n    | null, null -> 0\n    | null, _ -> -1\n    | _, null -> 1\n    | (:? string as x), (:? string as y) -> Scalar.compareText x y\n    | (:? (byte[]) as x), (:? (byte[]) as y) -> Scalar.compareBytes x y\n    | (:? bool as x), (:? bool as y) -> Operators.compare x y\n    | (:? BigInteger as x), (:? BigInteger as y) -> sign (BigInteger.Compare(x, y))\n    | (:? Rune as x), (:? Rune as y) -> Operators.compare x.Value y.Value\n    | (:? float as x), _ -> noOrder x\n    | (:? float32 as x), _ -> noOrder x\n    | (:? Symbol as x), _ -> noOrder x\n    | (:? IPortable as x), _ -> sign (x.CompareTo b)\n    | (:? IComparable as x), _ when a.GetType().IsPrimitive -> sign (x.CompareTo b)\n    | _ when Reflection.FSharpType.IsUnion(a.GetType()) && not (a :? IEnumerable) ->\n        let tag, fields = unionParts (a.GetType())\n        let ta, tb = tag a, tag b\n        if ta <> tb then Operators.compare ta tb\n        else compareSequence (fields a :> IEnumerable) (fields b :> IEnumerable)\n    | (:? IEnumerable as xs), (:? IEnumerable as ys) -> compareSequence xs ys\n    | (:? IComparable as x), _ -> sign (x.CompareTo b)\n    | _ -> noOrder a\n\nand private compareSequence (xs: IEnumerable) (ys: IEnumerable) =\n    let ys = ys.GetEnumerator()\n    let xs = xs.GetEnumerator()\n    let mutable result = None\n    while result.IsNone do\n        match xs.MoveNext(), ys.MoveNext() with\n        | false, false -> result <- Some 0\n        | false, true -> result <- Some -1\n        | true, false -> result <- Some 1\n        | true, true ->\n            match compare xs.Current ys.Current with\n            | 0 -> ()\n            | c -> result <- Some c\n    result.Value\n\n/// Compare two constructors' ranks and then their fields.\n[<CompiledName(\"CompareData\")>]\nlet compareData (rankA: int) (fieldsA: obj list) (rankB: int) (fieldsB: obj list) =\n    if rankA <> rankB then Operators.compare rankA rankB\n    else\n        let rec go xs ys =\n            match xs, ys with\n            | x :: xs, y :: ys ->\n                match compare x y with\n                | 0 -> go xs ys\n                | c -> c\n            | [], [] -> 0\n            | [], _ -> -1\n            | _, [] -> 1\n        go fieldsA fieldsB\n\n/// Whether two constructors' fields are equal.\n[<CompiledName(\"EqualData\")>]\nlet equalData (rankA: int) (fieldsA: obj list) (rankB: int) (fieldsB: obj list) =\n    rankA = rankB && List.length fieldsA = List.length fieldsB && List.forall2 equal fieldsA fieldsB\n\n/// A hash of a constructor and its fields.\n[<CompiledName(\"HashData\")>]\nlet hashData (rank: int) (fields: obj list) = fields |> List.fold (fun h f -> h * 31 + hash f) (rank + 7)\n"
dotnetSource "LawSpec.Runtime/Random.fs" = "/// The portable SplitMix64 sequence. Its state is passed explicitly, so\n/// concurrent callers never draw from one another's stream, and the same seed\n/// replays the same run on every target. ref:splitmix\n/// ref:DEC-portable-seeded-generation\nmodule LawSpec.Runtime.Random\n\nopen System.Numerics\n\n/// A SplitMix64 state.\n[<Struct>]\ntype Seed = Seed of uint64\n\n/// The state for a seed (any integer, reduced to 64 bits).\n[<CompiledName(\"SeedOf\")>]\nlet seed (n: BigInteger) = Seed(uint64 (n &&& BigInteger(System.UInt64.MaxValue)))\n\n/// The next output and state.\n[<CompiledName(\"Next\")>]\nlet next (Seed state) =\n    let s = state + 0x9e3779b97f4a7c15UL\n    let a = (s ^^^ (s >>> 30)) * 0xbf58476d1ce4e5b9UL\n    let b = (a ^^^ (a >>> 27)) * 0x94d049bb133111ebUL\n    b ^^^ (b >>> 31), Seed s\n\n/// A draw below a bound (0 for a bound that is not positive), as every\n/// runtime reduces it: the output modulo the bound.\n[<CompiledName(\"Below\")>]\nlet below (bound: BigInteger) (state: Seed) =\n    if bound.Sign <= 0 then BigInteger.Zero, state\n    else\n        let n, next' = next state\n        BigInteger.Remainder(BigInteger n, bound), next'\n\n/// Two independent states from one, for generators that branch.\n[<CompiledName(\"Split\")>]\nlet split (state: Seed) =\n    let a, s1 = next state\n    let b, _ = next s1\n    Seed a, Seed b\n"
dotnetSource "LawSpec.Runtime/Recorded.fs" = "/// Typed text for recorded values. Every target writes a recording the same\n/// way, so one recorded file checks every implementation. Identities (symbols\n/// and handles) are numbered within one recording. ref:REQ-law-primitives\n/// ref:DEC-portable-exact-arithmetic\nmodule LawSpec.Runtime.Recorded\n\nopen System\nopen System.Numerics\n\nlet private quote (s: string) = \"\\\"\" + s.Replace(\"\\\\\", \"\\\\\\\\\").Replace(\"\\\"\", \"\\\\\\\"\") + \"\\\"\"\n\nlet private lastPart (tag: string) =\n    let parts = tag.Split(\"::\")\n    parts.[parts.Length - 1]\n\nlet rec private trimDecimal (c: BigInteger) e =\n    if c.IsZero then BigInteger.Zero, 0\n    elif (c % BigInteger 10).IsZero then trimDecimal (c / BigInteger 10) (e + 1)\n    else c, e\n\nlet private floatText value =\n    match value with\n    | Float(w, bits) ->\n        let name = \"float\" + string w\n        if Scalar.floatClass value = \"nan\" then name + \"NaN\"\n        else name + \"Bits(\\\"\" + bits.ToString(if w = 32 then \"x8\" else \"x16\") + \"\\\")\"\n    | _ -> Fail.raiseWith \"InvalidRecordedScalar\" \"float\"\n\nlet private units name (values: int seq) =\n    name + \"([\" + String.Join(\", \", values |> Seq.map string) + \"])\"\n\nlet private scalar value (t: string) =\n    match t, value with\n    | \"Bool\", Bool b -> if b then \"true\" else \"false\"\n    | \"Unit\", Unit -> \"()\"\n    | \"Null\", Null -> \"null\"\n    | \"Undefined\", Undefined -> \"undefined\"\n    | \"Text\", Text s -> quote s\n    | \"Char\", Int n -> quote (Text.Rune(int n).ToString())\n    | (\"CodePoint\" | \"CodeUnit16\"), Int n -> n.ToString()\n    | \"Bytes\", Bytes b -> units \"bytes\" (b |> Seq.map int)\n    | \"CodePointText\", Raw(_, us) -> units \"codePoints\" us\n    | \"Utf16Text\", Raw(_, us) -> units \"utf16\" us\n    | \"Decimal\", Decimal(c, e) ->\n        let c, e = trimDecimal c e\n        c.ToString() + \"e\" + string e\n    | \"Rational\", Ratio(n, d) -> \"rational(\" + n.ToString() + \", \" + d.ToString() + \")\"\n    | (\"Float32\" | \"Float64\"), Float _ -> floatText value\n    | \"Complex64\", Complex(_, r, i) -> \"Complex64(\" + floatText r + \", \" + floatText i + \")\"\n    | \"Complex128\", Complex(_, r, i) -> \"Complex128(\" + floatText r + \", \" + floatText i + \")\"\n    | _, Int n when Scalar.isIntegerType t -> n.ToString()\n    | _ -> Fail.raiseWith \"InvalidRecordedScalar\" t\n\ntype private Ids = Map<string, (obj * int) list>\n\nlet private identity kind (value: obj) (ids: Ids) =\n    let known = defaultArg (ids.TryFind kind) []\n    match known |> List.tryFind (fun (v, _) -> Object.ReferenceEquals(v, value) || v.Equals value) with\n    | Some(_, n) -> n, ids\n    | None ->\n        let n = List.length known + 1\n        n, ids.Add(kind, known @ [ value, n ])\n\nlet rec private render (value: Value) (t: TypeRef) (schema: Schema.Schema option) (ids: Ids) : string * Ids =\n    match t, value with\n    | Named(\"List\", [ element ]), List items ->\n        let (parts: string list), next = sequence items (items |> List.map (fun _ -> element)) schema ids\n        \"[\" + String.Join(\", \", parts) + \"]\", next\n    | Named(kind, [ _ ]), Presence(_, None) -> (if kind = \"Nullable\" then \"null\" else \"undefined\"), ids\n    | Named(kind, [ inner ]), Presence(_, Some v) ->\n        let part, next = render v inner schema ids\n        (if kind = \"Nullable\" then \"nullable(\" else \"optional(\") + part + \")\", next\n    | Named(\"Symbol\", []), Symbol(id, description) ->\n        let n, next = identity \"symbol\" id ids\n        \"symbol(\" + string n + \", \" + quote description + \")\", next\n    | Named(name, []), Handle(_, id) ->\n        let n, next = identity (\"handle \" + name) id ids\n        lastPart name + \"#\" + string n, next\n    | _, Data(tag, fields) ->\n        let types =\n            match t, tag with\n            | _, \"Maybe::Nothing\" -> []\n            | Named(\"Maybe\", [ inner ]), _ -> [ inner ]\n            | Named(\"Either\", [ l; _ ]), \"Either::Left\" -> [ l ]\n            | Named(\"Either\", [ _; r ]), \"Either::Right\" -> [ r ]\n            | _ ->\n                match schema with\n                | Some s -> Schema.fieldTypes value t s\n                | None -> Fail.raiseWith \"RecordingNeedsSchema\" tag\n        let (parts: string list), next = sequence fields types schema ids\n        (if List.isEmpty parts then lastPart tag else lastPart tag + \"(\" + String.Join(\", \", parts) + \")\"), next\n    | Named(name, []), _ -> scalar value name, ids\n    | _ -> Fail.raiseWith \"InvalidRecordedValue\" (Scalar.typeKey t)\n\nand private sequence (values: Value list) (types: TypeRef list) schema ids : string list * Ids =\n    List.zip values types\n    |> List.fold (fun (parts, ids) (v, t) ->\n        let part, next = render v t schema ids\n        parts @ [ part ], next) ([], ids)\n\n/// A value's recorded text at its type.\n[<CompiledName(\"Text\")>]\nlet text (value: Value) (t: TypeRef) (schema: Schema.Schema option) = fst (render value t schema Map.empty)\n\n/// The untyped rendering a model's recorded state uses.\n[<CompiledName(\"Render\")>]\nlet rec renderPlain (value: Value) : string =\n    match value with\n    | Bool true -> \"true\"\n    | Bool false -> \"false\"\n    | Unit -> \"()\"\n    | Int n -> n.ToString()\n    | Text s -> quote s\n    | List items -> \"[\" + String.Join(\", \", items |> List.map renderPlain) + \"]\"\n    | Data(tag, []) -> lastPart tag\n    | Data(tag, fields) -> lastPart tag + \"(\" + String.Join(\", \", fields |> List.map renderPlain) + \")\"\n    | _ -> sprintf \"%A\" value\n"
dotnetSource "LawSpec.Runtime/Regex.fs" = "/// LawSpec's portable regex grammar, on Unicode scalar values rather than\n/// .NET's regex engine and its character classes. A match covers the whole\n/// text, and matching tracks reachable positions, so an ambiguous repeat\n/// never backtracks exponentially. ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Regex\n\nopen System.Collections.Concurrent\n\n/// A compiled pattern.\ntype Node =\n    /// A character set: negated, and items each (negated, ranges).\n    | Set of negated: bool * items: (bool * (int * int) list) list\n    | Sequence of Node list\n    | Alternatives of Node list\n    | Repeat of Node * low: int * high: int option\n\nlet private fail reason : 'a = Fail.raiseWith \"NonPortableRegex\" reason\n\nlet private require condition reason = if not condition then fail reason\n\nlet private escape (cs: int list) =\n    match cs with\n    | c :: rest when c = int 'd' || c = int 'D' -> (c = int 'D', [ 48, 57 ]), rest\n    | c :: rest when c = int 'w' || c = int 'W' -> (c = int 'W', [ 48, 57; 65, 90; 95, 95; 97, 122 ]), rest\n    | c :: rest when c = int 's' || c = int 'S' -> (c = int 'S', [ 9, 13; 32, 32 ]), rest\n    | c :: rest ->\n        let named = [ int 'n', 10; int 't', 9; int 'r', 13; int 'f', 12; int 'v', 11 ]\n        match List.tryFind (fun (k, _) -> k = c) named with\n        | Some(_, v) -> (false, [ v, v ]), rest\n        | None ->\n            require (\"\\\\.^$|?*+()[]{}-/\" |> Seq.exists (fun x -> int x = c)) \"UnsupportedEscape\"\n            (false, [ c, c ]), rest\n    | [] -> fail \"TrailingEscape\"\n\nlet private classItem cs =\n    match cs with\n    | c :: rest when c = int '\\\\' -> escape rest\n    | c :: _ when c = int '[' -> fail \"UnescapedClassOpen\"\n    | c :: rest -> (false, [ c, c ]), rest\n    | [] -> fail \"UnclosedClass\"\n\nlet rec private charClass cs negated acc =\n    match cs with\n    | [] -> fail \"UnclosedClass\"\n    | c :: _ when c = int ']' && List.isEmpty acc -> fail \"EmptyClass\"\n    | c :: rest when c = int ']' -> Set(negated, List.rev acc), rest\n    | _ ->\n        let item, rest = classItem cs\n        match item, rest with\n        | (false, [ lo, lo' ]), dash :: c :: tail when lo = lo' && dash = int '-' && c <> int ']' ->\n            match classItem (c :: tail) with\n            | (false, [ hi, hi' ]), next when hi = hi' && hi >= lo -> charClass next negated ((false, [ lo, hi ]) :: acc)\n            | _ -> fail \"InvalidClassRange\"\n        | _ -> charClass rest negated (item :: acc)\n\nlet private count cs =\n    let digits = cs |> List.takeWhile (fun c -> c >= int '0' && c <= int '9')\n    require (not (List.isEmpty digits)) \"MissingRepetitionCount\"\n    let value = digits |> List.fold (fun n d -> n * 10 + (d - int '0')) 0\n    value, List.skip digits.Length cs\n\nlet private repeat node low high cs =\n    require (low <= 1000 && (match high with None -> true | Some h -> h <= 1000 && h >= low)) \"InvalidRepetitionCount\"\n    match cs with\n    | c :: _ -> require (not (\"*+?{\" |> Seq.exists (fun x -> int x = c))) \"RepeatedQuantifier\"\n    | [] -> ()\n    Repeat(node, low, high), cs\n\nlet private quantified node cs =\n    match cs with\n    | c :: rest when c = int '*' -> repeat node 0 None rest\n    | c :: rest when c = int '+' -> repeat node 1 None rest\n    | c :: rest when c = int '?' -> repeat node 0 (Some 1) rest\n    | c :: rest when c = int '{' ->\n        let low, after = count rest\n        match after with\n        | c :: next when c = int '}' -> repeat node low (Some low) next\n        | c :: d :: next when c = int ',' && d = int '}' -> repeat node low None next\n        | c :: tail when c = int ',' ->\n            let high, after = count tail\n            match after with\n            | d :: next when d = int '}' -> repeat node low (Some high) next\n            | _ -> fail \"UnclosedRepetition\"\n        | _ -> fail \"InvalidRepetition\"\n    | _ -> node, cs\n\nlet rec private alternatives cs =\n    let branch, rest = sequence cs []\n    let rec more rest acc =\n        match rest with\n        | c :: tail when c = int '|' ->\n            let next, after = sequence tail []\n            more after (next :: acc)\n        | _ ->\n            match acc with\n            | [ only ] -> only, rest\n            | _ -> Alternatives(List.rev acc), rest\n    more rest [ branch ]\n\nand private sequence cs acc =\n    match cs with\n    | [] -> Sequence(List.rev acc), []\n    | c :: _ when c = int ')' || c = int '|' -> Sequence(List.rev acc), cs\n    | _ ->\n        let atom, rest = atom cs\n        let node, next = quantified atom rest\n        sequence next (node :: acc)\n\nand private atom cs =\n    match cs with\n    | o :: q :: c :: rest when o = int '(' && q = int '?' && c = int ':' -> group rest\n    | o :: q :: _ when o = int '(' && q = int '?' -> fail \"UnsupportedGroup\"\n    | o :: rest when o = int '(' -> group rest\n    | o :: n :: rest when o = int '[' && n = int '^' -> charClass rest true []\n    | o :: rest when o = int '[' -> charClass rest false []\n    | d :: rest when d = int '.' -> Set(true, [ false, [ 10, 10 ] ]), rest\n    | b :: rest when b = int '\\\\' ->\n        let item, after = escape rest\n        Set(false, [ item ]), after\n    | c :: rest ->\n        require (not (\"*+?{^$]}\" |> Seq.exists (fun x -> int x = c))) \"UnexpectedCharacter\"\n        Set(false, [ false, [ c, c ] ]), rest\n    | [] -> fail \"MissingAtom\"\n\nand private group cs =\n    let node, rest = alternatives cs\n    match rest with\n    | c :: next when c = int ')' -> node, next\n    | _ -> fail \"UnclosedGroup\"\n\nlet private cache = ConcurrentDictionary<string, Node>()\n\n/// Compile a pattern once; compiled patterns are shared.\nlet compile (pattern: string) =\n    cache.GetOrAdd(pattern, fun pattern ->\n        if not (Scalar.isWellFormed pattern) then Fail.raiseWith \"InvalidUnicode\" \"\"\n        let node, rest = alternatives (Scalar.codePoints pattern)\n        require (List.isEmpty rest) \"UnmatchedClosingParenthesis\"\n        node)\n\nlet private inSet (c: int) items =\n    items |> List.exists (fun (negated, ranges) -> negated <> (ranges |> List.exists (fun (lo, hi) -> c >= lo && c <= hi)))\n\nlet rec private reach node (text: int[]) (positions: Set<int>) : Set<int> =\n    match node with\n    | Set(negated, items) ->\n        positions\n        |> Seq.filter (fun p -> p < text.Length && inSet text.[p] items <> negated)\n        |> Seq.map (fun p -> p + 1)\n        |> Set.ofSeq\n    | Sequence nodes -> nodes |> List.fold (fun ps n -> reach n text ps) positions\n    | Alternatives nodes -> nodes |> List.map (fun n -> reach n text positions) |> Set.unionMany\n    | Repeat(inner, low, high) ->\n        let mutable required = positions\n        let mutable i = 0\n        while i < low && not required.IsEmpty do\n            required <- reach inner text required\n            i <- i + 1\n        let mutable seen = required\n        let mutable frontier = required\n        let mutable remaining = high |> Option.map (fun h -> h - low)\n        while not frontier.IsEmpty && remaining <> Some 0 do\n            let next = Set.difference (reach inner text frontier) seen\n            seen <- Set.union seen next\n            frontier <- next\n            remaining <- remaining |> Option.map (fun r -> r - 1)\n        seen\n\n/// Whether a compiled pattern matches the whole text.\nlet run (node: Node) (text: string) =\n    let points = Scalar.codePoints text |> Array.ofList\n    reach node points (Set.singleton 0) |> Set.contains points.Length\n\n/// Whether a pattern matches the whole text.\n[<CompiledName(\"Matches\")>]\nlet matches (pattern: string) (text: string) = run (compile pattern) text\n"
dotnetSource "LawSpec.Runtime/Runtime.fs" = "/// Services the generated definitions and laws share: contracts, equations,\n/// helpers, recordings and concurrent groups. Values stay portable until a\n/// native boundary. ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Runtime\n\nopen System\nopen System.IO\nopen System.Threading.Tasks\n\n/// A portable boolean as a .NET one.\n[<CompiledName(\"Truth\")>]\nlet truth (value: Value) =\n    match value with\n    | Bool b -> b\n    | _ -> Fail.raiseWith \"BoolRequired\" (sprintf \"%A\" value)\n\n[<CompiledName(\"Not\")>]\nlet not (value: Value) = Bool(Operators.not (truth value))\n\n/// The item of a list of values at a position.\n[<CompiledName(\"Item\")>]\nlet item (index: int) (values: Value list) = List.item index values\n\n/// The item of a list at a position.\n[<CompiledName(\"Nth\")>]\nlet nth (index: int) (items: 'a list) = List.item index items\n\n[<CompiledName(\"Some\")>]\nlet some (value: 'a) = Some value\n\n/// A data value's field at a position (a list's head and tail).\n[<CompiledName(\"Field\")>]\nlet field (value: Value) (index: int) =\n    match value, index with\n    | Data(_, fields), _ -> List.item index fields\n    | List(head :: _), 0 -> head\n    | List(_ :: tail), 1 -> List tail\n    | _ -> Fail.raiseWith \"ExpectedData\" (sprintf \"%A\" value)\n\n/// Whether a value was built by a constructor.\n[<CompiledName(\"HasTag\")>]\nlet hasTag (tag: string) (value: Value) =\n    match value with\n    | Data(t, _) -> t = tag\n    | List [] -> tag = \"List::Nil\"\n    | List _ -> tag = \"List::Cons\"\n    | _ -> false\n\n/// A match no branch covers.\n[<CompiledName(\"NoMatch\")>]\nlet noMatch (value: Value) : Value = Fail.raiseWith \"MatchFailure\" (sprintf \"%A\" value)\n\n/// Whether every element of a list satisfies a predicate.\n[<CompiledName(\"AllElements\")>]\nlet allElements (value: Value) (predicate: Value -> Value) =\n    match value with\n    | List items -> Bool(items |> List.forall (predicate >> truth))\n    | _ -> Fail.raiseWith \"ListRequired\" \"\"\n\n/// Whether every payload of a container satisfies its parameter's predicate.\n[<CompiledName(\"AllPayloads\")>]\nlet allPayloads (value: Value) (t: TypeRef) (predicates: (Value -> Value) list) (schema: Schema.Schema) =\n    Bool(Schema.allPayloads value t (predicates |> List.map (fun p -> p >> truth)) schema)\n\n/// Nullable or Optional, absent.\n[<CompiledName(\"Absent\")>]\nlet absent (kind: string) = Presence(kind, None)\n\n/// Nullable or Optional, present.\n[<CompiledName(\"Present\")>]\nlet present (kind: string) (value: Value) = Presence(kind, Some value)\n\n/// Fail a contract unless it holds.\n[<CompiledName(\"Require\")>]\nlet require (holds: Value) (context: string) : unit =\n    match holds with\n    | Bool true -> ()\n    | Bool false -> Fail.raiseWith \"ContractFailed\" context\n    | _ -> Fail.raiseWith \"NonBooleanContract\" context\n\n/// Where two unequal values first differ: the path to the item or field,\n/// and both values there.\nlet private difference (actual: Value) (expected: Value) =\n    let rec walk (a: Value) (b: Value) (path: string list) =\n        match a, b with\n        | List xs, List ys ->\n            let firstDiff =\n                Seq.zip xs ys |> Seq.tryFindIndex (fun (x, y) -> Recorded.renderPlain x <> Recorded.renderPlain y)\n            match firstDiff with\n            | Some i -> walk (List.item i xs) (List.item i ys) (path @ [ sprintf \"item %d\" (i + 1) ])\n            | None when List.length xs = List.length ys -> None\n            | None -> Some(path @ [ \"length\" ], string (List.length xs), string (List.length ys))\n        | Data(tx, fx), Data(ty, fy) when tx = ty && List.length fx = List.length fy ->\n            let name = tx.Substring(tx.LastIndexOf(\"::\") + 2)\n            match List.zip fx fy |> List.tryFindIndex (fun (x, y) -> Recorded.renderPlain x <> Recorded.renderPlain y) with\n            | Some i -> walk (List.item i fx) (List.item i fy) (path @ [ sprintf \"field %d of %s\" (i + 1) name ])\n            | None -> None\n        | _ when List.isEmpty path -> None\n        | _ -> Some(path, Recorded.renderPlain a, Recorded.renderPlain b)\n    match walk actual expected [] with\n    | Some(path, shownActual, shownExpected) ->\n        sprintf \" | first difference at %s: expected %s, actual %s\" (String.Join(\", \", path)) shownExpected shownActual\n    | None -> \"\"\n\n/// An equation of a law: both sides are kept for the report.\n[<CompiledName(\"AssertEqual\")>]\nlet assertEqual (actual: Value) (expected: Value) (label: string) : Value =\n    if Scalar.equal actual expected then Bool true\n    else\n        Fail.raiseWith \"EquationFailed\"\n            (sprintf \"%s: actual %s, expected %s%s\" label (Recorded.renderPlain actual) (Recorded.renderPlain expected) (difference actual expected))\n\n/// Name the definition or law a LawSpec failure happened in.\n[<CompiledName(\"Contextual\")>]\nlet contextual (identity: string) (body: unit -> 'a) : 'a =\n    try body () with\n    | :? LawSpecException as e -> raise (e.Within identity)\n\nlet private recordedRoot () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_RECORDED\" with\n    | null | \"\" ->\n        let start = Directory.GetCurrentDirectory()\n        let rec find (folder: string) =\n            if File.Exists(Path.Combine(folder, \"lawspec.json\")) || Directory.Exists(Path.Combine(folder, \"recorded\")) then\n                Path.Combine(folder, \"recorded\")\n            else\n                match Directory.GetParent folder with\n                | null -> Path.Combine(start, \"recorded\")\n                | parent -> find parent.FullName\n        find start\n    | given -> given\n\n/// Compare a value's text with its recording, or record it under\n/// LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded).\n[<CompiledName(\"RecordedText\")>]\nlet recordedText (key: string) (text: string) : Value =\n    let path = Path.Combine(Array.append [| recordedRoot () |] (key.Split '/'))\n    if Environment.GetEnvironmentVariable \"LAWSPEC_UPDATE_RECORDED\" = \"1\" then\n        Directory.CreateDirectory(Path.GetDirectoryName path) |> ignore\n        File.WriteAllText(path, text + \"\\n\")\n        Bool true\n    elif File.Exists path then\n        let stored = File.ReadAllText path\n        let stored = if stored.EndsWith \"\\n\" then stored.Substring(0, stored.Length - 1) else stored\n        if stored = text then Bool true\n        else\n            Fail.raiseWith \"RecordingDiffers\"\n                (\"recorded/\" + key + \" differs: expected \" + stored + \", actual \" + text\n                 + \" (lawspec test --update-recorded records the new value)\")\n    else\n        Fail.raiseWith \"RecordingMissing\"\n            (\"no recording recorded/\" + key + \"; run lawspec test --update-recorded to record \" + text)\n\n/// A recorded value, at its type.\n[<CompiledName(\"Recorded\")>]\nlet recorded (key: Value) (value: Value) (t: TypeRef) (schema: Schema.Schema) : Value =\n    match key with\n    | Text k -> recordedText k (Recorded.text value t (Some schema))\n    | _ -> Fail.raiseWith \"TextRequired\" \"recorded\"\n\n/// A built-in helper by name.\n[<CompiledName(\"Helper\")>]\nlet helper (name: string) (values: Value list) (types: string list) (bits: int) : Value =\n    match name, values with\n    | \"unreachable\", _ -> Fail.raiseWith \"Unreachable\" \"\"\n    | \"regexMatches\", [ Text pattern; Text text ] -> Bool(Regex.matches pattern text)\n    | \"recorded\", [ Text key; value ] when List.length types < 2 -> recordedText key (Recorded.renderPlain value)\n    | \"recorded\", [ key; value ] -> recorded key value (Scalar.typeOf (List.item 1 types)) (Schema.create [] [] bits)\n    | _ -> Scalar.helper name values types bits\n\nlet private unwrap (e: exn) =\n    match e with\n    | :? AggregateException as a when a.InnerExceptions.Count = 1 -> a.InnerExceptions.[0]\n    | _ -> e\n\n/// Run steps concurrently, each on the thread pool, and return their values\n/// in source order. Every step finishes before the first failure in source\n/// order is raised.\n[<CompiledName(\"Concurrently\")>]\nlet concurrently (steps: (unit -> Value) list) : Value list =\n    let tasks = steps |> List.map (fun step -> Task.Run(fun () -> step ())) |> Array.ofList\n    try Task.WaitAll(tasks |> Array.map (fun t -> t :> Task)) with _ -> ()\n    tasks\n    |> Array.map (fun t ->\n        if t.IsFaulted then raise (unwrap t.Exception)\n        elif t.IsCanceled then Fail.raiseWith \"ConcurrentStepCancelled\" \"\"\n        else t.Result)\n    |> List.ofArray\n\n/// Await an async adapter's task where it is called.\n[<CompiledName(\"Await\")>]\nlet await (task: Task<'a>) : 'a =\n    try task.GetAwaiter().GetResult() with e -> raise (unwrap e)\n\n/// Discard a value computed for its checks.\n[<CompiledName(\"Ignore\")>]\nlet ignore (_: Value) = ()\n\n/// An integer value from its digits.\n[<CompiledName(\"Integer\")>]\nlet integer (digits: string) = Int(Numerics.BigInteger.Parse digits)\n"
dotnetSource "LawSpec.Runtime/Scalar.fs" = "/// LawSpec's scalar domain on .NET. Exact arithmetic never goes through a\n/// native float, and IEEE values are rounded once, from an exact ratio, to\n/// nearest with ties to even. Every generated law and dynamic definition uses\n/// these operations, so F# and C# agree with each other and with the other\n/// targets. ref:DEC-portable-exact-arithmetic ref:ieee-754\n/// ref:DEC-explicit-machine-profile\nmodule LawSpec.Runtime.Scalar\n\nopen System\nopen System.Collections.Concurrent\nopen System.Numerics\nopen System.Text\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n// ---------------------------------------------------------------------------\n// Type keys\n\nlet private tokenize (text: string) =\n    let tokens = ResizeArray<string>()\n    let word = StringBuilder()\n    let flush () =\n        if word.Length > 0 then\n            tokens.Add(word.ToString())\n            word.Clear() |> ignore\n    for c in text do\n        match c with\n        | '(' | ')' ->\n            flush ()\n            tokens.Add(string c)\n        | ' ' | '\\t' -> flush ()\n        | c -> word.Append(c) |> ignore\n    flush ()\n    List.ofSeq tokens\n\nlet rec private application parts =\n    match parts with\n    | [ Named(name, []) ] -> Named(name, [])\n    | Named(name, []) :: args when List.contains name [ \"List\"; \"Maybe\"; \"Optional\"; \"Nullable\" ] ->\n        Named(name, [ application args ])\n    | Named(name, []) :: args -> Named(name, args)\n    | [ t ] -> t\n    | _ -> fail \"InvalidTypeKey\" \"\"\n\nlet rec private parts tokens acc =\n    match tokens with\n    | [] -> List.rev acc, []\n    | \")\" :: _ -> List.rev acc, tokens\n    | \"(\" :: rest ->\n        let inner, after = parts rest []\n        match after with\n        | \")\" :: next -> parts next (application inner :: acc)\n        | _ -> fail \"InvalidTypeKey\" \"\"\n    | word :: rest when word.StartsWith \"$\" -> parts rest (Parameter(int (word.Substring 1)) :: acc)\n    | word :: rest -> parts rest (Named(word, []) :: acc)\n\nlet private typeCache = ConcurrentDictionary<string, TypeRef>()\n\n/// The type a key names: `Either (Int8) (Text)`, `List Int8`, `Maybe (List Text)`.\n/// Parentheses keep nested Either and presence arguments apart.\n[<CompiledName(\"TypeOf\")>]\nlet typeOf (key: string) : TypeRef =\n    typeCache.GetOrAdd(key, fun key ->\n        let found, rest = parts (tokenize key) []\n        if not (List.isEmpty rest) then fail \"InvalidTypeKey\" key\n        application found)\n\n/// The key of a type, as typeOf reads it.\n[<CompiledName(\"TypeKey\")>]\nlet rec typeKey (t: TypeRef) =\n    match t with\n    | Named(name, []) -> name\n    | Named(name, args) -> name + String.Join(\"\", args |> List.map (fun a -> \" (\" + typeKey a + \")\"))\n    | Parameter i -> sprintf \"$%d\" i\n\nlet private nameOf (t: TypeRef) =\n    match t with\n    | Named(name, _) -> name\n    | Parameter _ -> \"\"\n\n// ---------------------------------------------------------------------------\n// Integers\n\nlet private integerTypes =\n    set [ \"Int8\"; \"Int16\"; \"Int32\"; \"Int64\"; \"UInt8\"; \"UInt16\"; \"UInt32\"; \"UInt64\"\n          \"IntSize\"; \"UIntSize\"; \"UIntPtr\"; \"Integer\"; \"BigInt\"; \"BigUInt\" ]\n\n/// Whether a scalar name is one of LawSpec's integer types.\n[<CompiledName(\"IsIntegerType\")>]\nlet isIntegerType name = integerTypes.Contains name\n\nlet private pow2 (n: int) = BigInteger.One <<< n\n\nlet private signed (width: int) = Some(-(pow2 (width - 1))), Some(pow2 (width - 1) - BigInteger.One)\n\n/// An integer type's inclusive bounds under a machine profile (32 or 64 bits).\n[<CompiledName(\"Bounds\")>]\nlet bounds (name: string) (bits: int) : BigInteger option * BigInteger option =\n    if bits <> 32 && bits <> 64 then fail \"InvalidMachineBits\" (string bits)\n    match name with\n    | \"Integer\" | \"BigInt\" -> None, None\n    | \"BigUInt\" -> Some BigInteger.Zero, None\n    | \"IntSize\" -> signed bits\n    | \"UIntSize\" | \"UIntPtr\" -> Some BigInteger.Zero, Some(pow2 bits - BigInteger.One)\n    | _ when name.StartsWith \"UInt\" -> Some BigInteger.Zero, Some(pow2 (int (name.Substring 4)) - BigInteger.One)\n    | _ when name.StartsWith \"Int\" -> signed (int (name.Substring 3))\n    | _ -> fail \"UnknownInteger\" name\n\nlet private checkBounds (value: BigInteger) name bits =\n    let lo, hi = bounds name bits\n    let below = match lo with Some l -> value < l | None -> false\n    let above = match hi with Some h -> value > h | None -> false\n    if below || above then fail \"IntegerOutOfRange\" (sprintf \"%s %O\" name value)\n    Int value\n\n// ---------------------------------------------------------------------------\n// Exact numbers\n\n/// A normalized fraction.\n[<CompiledName(\"Ratio\")>]\nlet ratio (n: BigInteger) (d: BigInteger) =\n    if d.IsZero then fail \"InvalidRational\" \"zero denominator\"\n    let g = BigInteger.GreatestCommonDivisor(n, d)\n    let s = if d.Sign < 0 then BigInteger.MinusOne else BigInteger.One\n    Ratio(s * n / g, BigInteger.Abs d / g)\n\nlet private pow10 (n: int) = BigInteger.Pow(BigInteger(10), n)\n\nlet private normalized n d =\n    match ratio n d with\n    | Ratio(a, b) -> a, b\n    | _ -> failwith \"unreachable\"\n\n// IEEE layouts: fraction bits, exponent bits, bias.\nlet private format width =\n    match width with\n    | 32 -> 23, 8, 127\n    | 64 -> 52, 11, 1023\n    | _ -> fail \"InvalidIeeeWidth\" (string width)\n\ntype private Decoded =\n    | Finite of sign: int * mantissa: BigInteger * exponent: int\n    | Infinity of sign: int\n    | NaN\n\nlet private decode width (bits: uint64) =\n    let p, e, bias = format width\n    let sign = int (bits >>> (width - 1)) &&& 1\n    let exponent = int ((bits >>> p) &&& ((1UL <<< e) - 1UL))\n    let fraction = bits &&& ((1UL <<< p) - 1UL)\n    let top = (1 <<< e) - 1\n    if exponent = top then (if fraction = 0UL then Infinity sign else NaN)\n    elif exponent = 0 then Finite(sign, BigInteger(fraction), 1 - bias - p)\n    else Finite(sign, BigInteger((1UL <<< p) + fraction), exponent - bias - p)\n\n/// The exact ratio of an exact number or a finite float.\n[<CompiledName(\"Exact\")>]\nlet exact (value: Value) : BigInteger * BigInteger =\n    match value with\n    | Int n -> n, BigInteger.One\n    | Ratio(n, d) -> n, d\n    | Decimal(c, _) when c.IsZero -> BigInteger.Zero, BigInteger.One\n    | Decimal(c, e) when e >= 0 -> c * pow10 e, BigInteger.One\n    | Decimal(c, e) -> normalized c (pow10 -e)\n    | Float(w, b) ->\n        match decode w b with\n        | Finite(sign, m, e) ->\n            let signedM = if sign = 0 then m else -m\n            if e >= 0 then signedM <<< e, BigInteger.One else normalized signedM (pow2 -e)\n        | _ -> fail \"NonFiniteExactConversion\" \"\"\n    | _ -> fail \"ExactNumberRequired\" (sprintf \"%A\" value)\n\nlet private isExact value =\n    match value with\n    | Int _ | Ratio _ | Decimal _ -> true\n    | _ -> false\n\nlet rec private factors (n: BigInteger) (factor: BigInteger) count =\n    if (n % factor).IsZero then factors (n / factor) factor (count + 1) else n, count\n\n/// A decimal for an exact ratio, when its expansion terminates in base ten.\nlet private finiteDecimal n d =\n    let rn, rd = normalized n d\n    let d2, twos = factors rd (BigInteger 2) 0\n    let d5, fives = factors d2 (BigInteger 5) 0\n    if not d5.IsOne then fail \"NonTerminatingDecimal\" \"\"\n    let scale = max twos fives\n    Value.Decimal(rn * BigInteger.Pow(BigInteger 2, scale - twos) * BigInteger.Pow(BigInteger 5, scale - fives), -scale)\n\n// ---------------------------------------------------------------------------\n// IEEE floats\n\nlet private floatValue width (bits: uint64) =\n    if width = 32 && bits > 0xFFFFFFFFUL then fail \"InvalidIeeeBits\" \"\"\n    Float(width, bits)\n\nlet private zero width sign = Float(width, uint64 sign <<< (width - 1))\n\nlet private infinity width sign =\n    let p, e, _ = format width\n    Float(width, (uint64 sign <<< (width - 1)) ||| (((1UL <<< e) - 1UL) <<< p))\n\nlet private nan width =\n    let p, _, _ = format width\n    match infinity width 0 with\n    | Float(_, inf) -> Float(width, inf ||| (1UL <<< (p - 1)))\n    | _ -> failwith \"unreachable\"\n\nlet private floorLog2 (n: BigInteger) (d: BigInteger) =\n    let guess = int (n.GetBitLength()) - int (d.GetBitLength())\n    let below = if guess >= 0 then n < (d <<< guess) else (n <<< -guess) < d\n    if below then guess - 1 else guess\n\nlet private roundRatio (n: BigInteger) (d: BigInteger) =\n    let q = BigInteger.Divide(n, d)\n    let r = n - q * d\n    if BigInteger 2 * r > d || (BigInteger 2 * r = d && not q.IsEven) then q + BigInteger.One else q\n\n/// The float of a width nearest an exact ratio; a zero takes the given sign.\n[<CompiledName(\"FloatFromRatio\")>]\nlet floatFromRatio width (n: BigInteger) (d: BigInteger) zeroSign =\n    if d.IsZero then fail \"ZeroDenominator\" \"\"\n    if n.IsZero then zero width zeroSign else\n    let p, _, bias = format width\n    let s = if (n.Sign < 0) <> (d.Sign < 0) then 1 else 0\n    let an, ad = BigInteger.Abs n, BigInteger.Abs d\n    let exponent = max (1 - bias) (floorLog2 an ad)\n    let shift = p - exponent\n    let mantissa = if shift >= 0 then roundRatio (an <<< shift) ad else roundRatio an (ad <<< -shift)\n    let m, e = if mantissa >= pow2 (p + 1) then mantissa >>> 1, exponent + 1 else mantissa, exponent\n    if e > bias then infinity width s\n    else\n        let encoded = if m < pow2 p then 0UL else uint64 (e + bias)\n        let fraction = uint64 (m &&& (pow2 p - BigInteger.One))\n        Float(width, (uint64 s <<< (width - 1)) ||| (encoded <<< p) ||| fraction)\n\n/// A float's class: \"nan\", \"infinity\", \"zero\" or \"finite\".\n[<CompiledName(\"FloatClass\")>]\nlet floatClass value =\n    match value with\n    | Float(w, b) ->\n        match decode w b with\n        | NaN -> \"nan\"\n     