ration\" op\n        Value.Complex(w, r, i)\n    | _ -> fail \"ComplexRequired\" op\n\n/// A binary operator on two values of the given types (by key).\n[<CompiledName(\"Binary\")>]\nlet binary (op: string) (a: Value) (b: Value) (ta: string) (tb: string) : Value =\n    match op with\n    | \"==\" -> Bool(equal a b)\n    | \"!=\" -> Bool(not (equal a b))\n    | \"<\" | \"<=\" | \">\" | \">=\" ->\n        let ordering =\n            if inexactWidth ta > 0 || inexactWidth tb > 0 then floatCompare a b\n            else Some(compareValues a b)\n        Bool(relation op ordering)\n    | _ ->\n        if (inexactWidth ta > 0) <> (inexactWidth tb > 0) then fail \"ExactInexactMixing\" op\n        match max (inexactWidth ta) (inexactWidth tb) with\n        | 0 -> exactBinary op a b ta tb\n        | width when isComplexType ta || isComplexType tb -> complexBinary op (toComplex a width) (toComplex b width)\n        | _ -> floatBinary op a b\n\n// ---------------------------------------------------------------------------\n// Helpers\n\nlet private sequenceItems value (kind: string) =\n    match value with\n    | List items -> items\n    | Text s when kind = \"Text\" -> codePoints s |> List.map (BigInteger >> Int)\n    | Text s -> Encoding.UTF8.GetBytes s |> Seq.map (int >> BigInteger >> Int) |> List.ofSeq\n    | Bytes b -> b |> Seq.map (int >> BigInteger >> Int) |> List.ofSeq\n    | _ -> fail \"SequenceRequired\" kind\n\nlet private sequenceLike value (kind: string) (items: Value list) =\n    let ints = items |> List.map (function Int n -> int n | _ -> fail \"SequenceRequired\" kind)\n    match value with\n    | List _ -> List items\n    | Text _ when kind = \"Text\" -> Text(textOfPoints ints)\n    | _ -> Bytes(ints |> List.map byte |> Array.ofList)\n\nlet private bool value =\n    match value with\n    | Bool b -> b\n    | _ -> fail \"BoolRequired\" \"\"\n\nlet private integer value =\n    match value with\n    | Int n -> n\n    | _ -> fail \"IntegerRequired\" \"\"\n\nlet private text value =\n    match value with\n    | Text s -> s\n    | _ -> fail \"TextRequired\" \"\"\n\nlet private clamp (n: BigInteger) (lo: BigInteger) (hi: BigInteger) = if n < lo then lo elif n > hi then hi else n\n\n/// A built-in helper by name, with its arguments and their type keys.\n[<CompiledName(\"Helper\")>]\nlet helper (name: string) (values: Value list) (types: string list) (bits: int) : Value =\n    match name, values with\n    | \"isNaN\", [ f ] -> Bool(floatClass f = \"nan\")\n    | \"isInfinite\", [ f ] -> Bool(floatClass f = \"infinity\")\n    | \"isFinite\", [ f ] -> Bool(let c = floatClass f in c = \"finite\" || c = \"zero\")\n    | \"isNegativeZero\", [ f ] -> Bool(floatClass f = \"zero\" && floatSign f = 1)\n    | \"length\", [ List items ] -> Int(BigInteger(List.length items))\n    | \"length\", [ Bytes b ] -> Int(BigInteger b.Length)\n    | \"length\", [ Text s ] -> Int(BigInteger(List.length (codePoints s)))\n    | \"length\", [ Raw(_, units) ] -> Int(BigInteger(List.length units))\n    | (\"real\"), [ Value.Complex(_, r, _) ] -> r\n    | (\"imag\" | \"imaginary\"), [ Value.Complex(_, _, i) ] -> i\n    | \"conjugate\", [ Value.Complex(w, r, i) ] -> Value.Complex(w, r, negate i)\n    | \"abs\", [ v ] when isExact v -> if fst (exact v) < BigInteger.Zero then negate v else v\n    | \"abs\", [ Float(w, b) ] -> Float(w, b &&& ((1UL <<< (w - 1)) - 1UL))\n    | \"round\", [ v; Int places ] ->\n        let n, d = exact v\n        let places = int places\n        let sn, sd = if places >= 0 then n * pow10 places, d else n, d * pow10 -places\n        let q = roundRatio (BigInteger.Abs sn) sd\n        Value.Decimal((if sn.Sign < 0 then -q else q), -places)\n    | \"startsWith\", [ Text t; Text p ] -> Bool(t.StartsWith(p, StringComparison.Ordinal))\n    | \"endsWith\", [ Text t; Text s ] -> Bool(t.EndsWith(s, StringComparison.Ordinal))\n    | \"textContains\", [ Text t; Text p ] -> Bool(p = \"\" || t.Contains(p, StringComparison.Ordinal))\n    | \"checked\", [ _ ] -> Bool true\n    | \"select\", [ Bool c; a; b ] -> if c then a else b\n    | \"compare\", [ a; b ] ->\n        let tag =\n            match compareValues a b with\n            | -1 -> \"Less\"\n            | 0 -> \"Equal\"\n            | _ -> \"Greater\"\n        Data(\"lawspec.collections::type::Ordering::\" + tag, [])\n    | \"isPresent\", [ Presence(_, p) ] -> Bool(Option.isSome p)\n    | \"presentValue\", [ Presence(_, Some v) ] -> v\n    | \"presentValue\", [ Presence(_, None) ] -> fail \"AbsentPresenceValue\" \"\"\n    | \"negate\", [ v ] -> negate v\n    | \"append\", [ List a; List b ] -> List(a @ b)\n    | \"append\", [ Text a; Text b ] -> Text(a + b)\n    | \"append\", [ Bytes a; Bytes b ] -> Bytes(Array.append a b)\n    | \"slice\", [ x; Int from; Int until ] ->\n        let kind = List.head types\n        let items = sequenceItems x kind\n        let count = BigInteger(List.length items)\n        let i = clamp from BigInteger.Zero count\n        let j = clamp until i count\n        sequenceLike x kind (items |> List.skip (int i) |> List.take (int (j - i)))\n    | \"at\", [ x; Int i ] ->\n        let items = sequenceItems x (List.head types)\n        if i.Sign >= 0 && i < BigInteger(List.length items) then Data(\"Maybe::Just\", [ List.item (int i) items ])\n        else Data(\"Maybe::Nothing\", [])\n    | \"range\", [ Int lo; Int hi ] ->\n        List [ let mutable n = lo\n               while n < hi do\n                   yield Int n\n                   n <- n + BigInteger.One ]\n    | \"octets\", [ Bytes b ] -> List(b |> Seq.map (int >> BigInteger >> Int) |> List.ofSeq)\n    | \"bytesOf\", [ List items ] -> Bytes(items |> List.map (integer >> int >> byte) |> Array.ofList)\n    | \"utf8\", [ Text t ] -> Bytes(Encoding.UTF8.GetBytes t)\n    | \"textOf\", [ Int n ] -> Text(n.ToString())\n    | \"join\", [ Text separator; List parts ] -> Text(String.Join(separator, parts |> List.map text))\n    | (\"quot\" | \"rem\" | \"pow\"), [ a; b ] -> binary name a b (List.item 0 types) (List.item 1 types)\n    | _, [ v ] -> convert v (typeOf name) bits\n    | _ -> fail \"UnknownHelper\" name\n\n// ---------------------------------------------------------------------------\n// Symbols\n\n/// A fresh symbol with a description.\n[<CompiledName(\"NewSymbol\")>]\nlet newSymbol (description: string) = Symbol(obj (), description)\n\n/// Literal symbols share identities within one context (a law's run).\ntype SymbolContext() =\n    let symbols = ConcurrentDictionary<string, obj>()\n    member _.Identity(id: string) = symbols.GetOrAdd(id, fun _ -> obj ())\n\n/// A literal symbol, interned in its context.\n[<CompiledName(\"Symbol\")>]\nlet symbol (context: SymbolContext) (id: string) (description: string) = Symbol(context.Identity id, description)\n\n// ---------------------------------------------------------------------------\n// Literals, as the generated code writes them\n\n[<CompiledName(\"Integer\")>]\nlet integerLiteral (digits: string) = Int(BigInteger.Parse(digits, Globalization.CultureInfo.InvariantCulture))\n\n[<CompiledName(\"DecimalOf\")>]\nlet decimalOf (coefficient: string) (exponent: int) =\n    Value.Decimal(BigInteger.Parse(coefficient, Globalization.CultureInfo.InvariantCulture), exponent)\n\n[<CompiledName(\"RationalOf\")>]\nlet rationalOf (numerator: string) (denominator: string) =\n    ratio (BigInteger.Parse(numerator, Globalization.CultureInfo.InvariantCulture))\n        (BigInteger.Parse(denominator, Globalization.CultureInfo.InvariantCulture))\n\n[<CompiledName(\"FloatBits\")>]\nlet floatBits (width: int) (hex: string) =\n    floatValue width (UInt64.Parse(hex, Globalization.NumberStyles.HexNumber))\n\n[<CompiledName(\"TextUnits\")>]\nlet textUnits (points: int list) = Text(textOfPoints points)\n\n[<CompiledName(\"BytesOf\")>]\nlet bytesOf (units: int list) = Bytes(units |> List.map (checkedUnit \"Bytes\" >> byte) |> Array.ofList)\n\n[<CompiledName(\"RawOf\")>]\nlet rawOf (kind: string) (units: int list) = Raw(kind, units |> List.map (checkedUnit kind))\n"
dotnetSource "LawSpec.Runtime/Schema.fs" = "/// The checked shapes of a program's data: constructors, field types, GADT\n/// equations, existential witnesses, index guards and field contracts, all\n/// checked by one walk. ref:DEC-typed-core-boundary\n/// ref:DEC-gadts-and-index-arithmetic\nmodule LawSpec.Runtime.Schema\n\nopen System\nopen System.Numerics\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n/// Bounds and hints that steer the generation of one constructor field from\n/// the fields drawn before it. ref:DEC-shrink-within-domain\ntype FieldHints =\n    { Bounds: (string * Value) list\n      Lengths: (string * Value) list\n      Hints: Value list }\n\n/// A data constructor; Arguments and WitnessValues are filled in when it is\n/// instantiated at a type.\ntype Constructor =\n    { Tag: string\n      Fields: (string * TypeRef) list\n      Predicates: (Schema -> TypeRef list -> Value list -> bool) list\n      /// By field position, from 1.\n      Generators: Map<int, Schema -> TypeRef list -> Value list -> FieldHints>\n      Indices: string list\n      Refinements: (int * TypeRef) list\n      Existentials: int\n      Witnesses: int list\n      Arguments: TypeRef list\n      WitnessValues: Value list }\n\nand DataDefinition =\n    { Name: string\n      Parameters: int\n      Constructors: Constructor list\n      Handle: bool }\n\nand Schema =\n    { Definitions: Map<string, DataDefinition>\n      Arities: Map<string, int>\n      Bits: int\n      /// The handlers in scope, by ability key (LawSpec.Runtime.Effects).\n      Handlers: Map<string, obj>\n      /// The innermost handler scope, which owns handler state.\n      Scope: obj option\n      /// The stateful handlers whose operations are running, innermost first.\n      EffectPath: obj list }\n\n/// A constructor with only a tag and fields; the generated schema adds the rest.\nlet constructor tag fields =\n    { Tag = tag\n      Fields = fields\n      Predicates = []\n      Generators = Map.empty\n      Indices = []\n      Refinements = []\n      Existentials = 0\n      Witnesses = []\n      Arguments = []\n      WitnessValues = [] }\n\n/// The type parameters' types, by position.\nlet rec substitute (t: TypeRef) (known: Map<int, TypeRef>) =\n    match t with\n    | Parameter i -> defaultArg (known.TryFind i) t\n    | Named(name, args) -> Named(name, args |> List.map (fun a -> substitute a known))\n\nlet rec private checkScope (t: TypeRef) scope (schema: Schema) =\n    match t with\n    | Parameter i -> if i < 0 || i >= scope then fail \"UnboundSchemaParameter\" (string i)\n    | Named(name, args) ->\n        match schema.Arities.TryFind name with\n        | Some arity when arity = List.length args -> args |> List.iter (fun a -> checkScope a scope schema)\n        | _ -> fail \"UnknownTypeOrArity\" name\n\n/// Check that a closed type is known, with the right number of arguments.\nlet checkType (t: TypeRef) (schema: Schema) = checkScope t 0 schema\n\nlet private builtins = [ \"List\", 1; \"Maybe\", 1; \"Either\", 2; \"Nullable\", 1; \"Optional\", 1 ]\n\n/// A program's schema, from its data definitions and the scalar names.\nlet create (definitions: DataDefinition list) (primitives: string list) (bits: int) =\n    if bits <> 32 && bits <> 64 then fail \"InvalidMachineBits\" (string bits)\n    let names = (definitions |> List.map (fun d -> d.Name)) @ primitives @ (builtins |> List.map fst)\n    if List.length names <> List.length (List.distinct names) then fail \"DuplicateType\" \"\"\n    let arities =\n        Map.ofList ((primitives |> List.map (fun p -> p, 0)) @ builtins @ (definitions |> List.map (fun d -> d.Name, d.Parameters)))\n    let schema =\n        { Definitions = definitions |> List.map (fun d -> d.Name, d) |> Map.ofList\n          Arities = arities\n          Bits = bits\n          Handlers = Map.empty\n          Scope = None\n          EffectPath = [] }\n    let tags = definitions |> List.collect (fun d -> d.Constructors |> List.map (fun c -> c.Tag))\n    if List.length tags <> List.length (List.distinct tags) then fail \"DuplicateConstructor\" \"\"\n    for d in definitions do\n        for c in d.Constructors do\n            let scope = d.Parameters + c.Existentials\n            for _, t in c.Fields do\n                checkScope t scope schema\n    schema\n\nlet rec private unify (pattern: TypeRef) (actual: TypeRef) (known: Map<int, TypeRef> option) =\n    match known with\n    | None -> None\n    | Some k ->\n        match pattern with\n        | Parameter i ->\n            match k.TryFind i with\n            | None -> Some(k.Add(i, actual))\n            | Some t when t = actual -> known\n            | Some _ -> None\n        | Named(name, ps) ->\n            match actual with\n            | Named(n, xs) when n = name && List.length ps = List.length xs ->\n                List.fold2 (fun acc p a -> unify p a acc) known ps xs\n            | _ -> None\n\nlet private instantiate (c: Constructor) (args: TypeRef list) =\n    let known = args |> List.mapi (fun i a -> i, a) |> Map.ofList\n    let bound =\n        c.Refinements |> List.fold (fun acc (i, pattern) -> unify pattern (List.item i args) acc) (Some known)\n    bound\n    |> Option.map (fun b ->\n        { c with\n            Arguments = args\n            Fields = c.Fields |> List.map (fun (n, t) -> n, substitute t b) })\n\nlet private builtinConstructors name (args: TypeRef list) =\n    match name, args with\n    | \"Maybe\", [ t ] -> Some [ constructor \"Maybe::Nothing\" []; constructor \"Maybe::Just\" [ \"value\", t ] ]\n    | \"Either\", [ a; b ] -> Some [ constructor \"Either::Left\" [ \"value\", a ]; constructor \"Either::Right\" [ \"value\", b ] ]\n    | _ -> None\n\n/// The constructors of a data type at its arguments, or None for a scalar or\n/// a list. A GADT constructor whose equations the arguments refute is absent.\nlet constructors (t: TypeRef) (schema: Schema) : Constructor list option =\n    checkType t schema\n    match t with\n    | Named(name, args) ->\n        match schema.Definitions.TryFind name with\n        | None -> builtinConstructors name args\n        | Some d -> Some(d.Constructors |> List.choose (fun c -> instantiate c args))\n    | Parameter _ -> None\n\n/// Each instance of a constructor's free existentials over Core's finite\n/// witness pool (Bool and Int32).\nlet witnessInstances (c: Constructor) =\n    let pool = [ Named(\"Bool\", []); Named(\"Int32\", []) ]\n    let assignments =\n        c.Witnesses |> List.fold (fun previous i -> [ for known in previous do for t in pool -> Map.add i t known ]) [ Map.empty ]\n    let kept = List.length c.Fields - List.length c.Witnesses\n    [ for known in assignments ->\n          { c with\n              Fields = c.Fields |> List.take kept |> List.map (fun (n, t) -> n, substitute t known)\n              WitnessValues = c.Witnesses |> List.map (fun i -> Text(Scalar.typeKey known.[i])) } ]\n\nlet private findConstructor tag (cs: Constructor list) =\n    match cs |> List.filter (fun c -> c.Tag = tag) with\n    | [ c ] -> c\n    | _ -> fail \"ForeignConstructor\" tag\n\nlet private witnessed (c: Constructor) (values: Value list) (schema: Schema) =\n    let texts = values |> List.skip (List.length values - List.length c.Witnesses)\n    let known =\n        List.zip c.Witnesses texts\n        |> List.map (fun (i, v) ->\n            match v with\n            | Text key -> i, Scalar.typeOf key\n            | _ -> fail \"InvalidWitness\" \"\")\n        |> Map.ofList\n    known |> Map.iter (fun _ t -> checkType t schema)\n    c.Fields |> List.map (fun (n, t) -> n, substitute t known)\n\n// ---------------------------------------------------------------------------\n// Index terms\n\nlet private tokens (text: string) = text.Split(' ', StringSplitOptions.RemoveEmptyEntries) |> List.ofArray\n\nlet private guard tokens =\n    match tokens with\n    | (\"==\" | \">=\") :: _ -> true\n    | _ -> false\n\nlet private indexBinary op (a: BigInteger option) (b: BigInteger option) =\n    match a, b with\n    | Some a, Some b ->\n        match op with\n        | \"+\" -> Some(a + b)\n        | \"-\" when a >= b -> Some(a - b)\n        | \"*\" -> Some(a * b)\n        | \"div\" when b.Sign > 0 -> Some(BigInteger.Divide(a, b))\n        | \"mod\" when b.Sign > 0 -> Some(BigInteger.Remainder(a, b))\n        | \"^\" when b.Sign >= 0 && b <= BigInteger 64 -> Some(BigInteger.Pow(a, int b))\n        | _ -> None\n    | _ -> None\n\nlet rec private evalIndex terms (c: Constructor) (values: Value list) schema =\n    match terms with\n    | (term: string) :: rest when term.StartsWith \"c\" -> Some(BigInteger.Parse(term.Substring 1)), rest\n    | term :: rest when term.StartsWith \"f\" ->\n        let position, inner =\n            match term.Substring(1).Split('.') with\n            | [| p |] -> int p, 0\n            | [| p; i |] -> int p, int i\n            | _ -> fail \"InvalidIndexTerm\" term\n        let _, t = List.item position c.Fields\n        Some(index (List.item position values) t inner schema), rest\n    | op :: rest ->\n        let a, next = evalIndex rest c values schema\n        let b, after = evalIndex next c values schema\n        indexBinary op a b, after\n    | [] -> fail \"InvalidIndexTerm\" \"\"\n\n/// The index at a position of an indexed family's value.\nand index (value: Value) (t: TypeRef) (position: int) (schema: Schema) : BigInteger =\n    match value, constructors t schema with\n    | Data(tag, values), Some cs ->\n        let c0 = findConstructor tag cs\n        let c = { c0 with Fields = witnessed c0 values schema }\n        let terms = c.Indices |> List.map tokens |> List.filter (guard >> not)\n        if position < 0 || position >= List.length terms then fail \"NoIndex\" \"\"\n        match evalIndex (List.item position terms) c values schema with\n        | Some v, [] -> v\n        | _ -> fail \"UndefinedIndex\" tag\n    | _ -> fail \"IndexedTypeRequiresData\" (Scalar.typeKey t)\n\nlet private checkIndices (c: Constructor) values schema =\n    for text in c.Indices do\n        match tokens text with\n        | ((\"==\" | \">=\") as op) :: rest ->\n            let a, next = evalIndex rest c values schema\n            let b, _ = evalIndex next c values schema\n            let holds =\n                match a, b with\n                | Some a, Some b -> if op = \"==\" then a = b else a >= b\n                | _ -> false\n            if not holds then fail \"RefinementViolation\" (\"index guard \" + text)\n        | _ -> ()\n\n// ---------------------------------------------------------------------------\n// Validation\n\nlet rec private strictOrder values =\n    match values with\n    | a :: (b :: _ as rest) -> Scalar.compareValues a b = -1 && strictOrder rest\n    | _ -> true\n\nlet private checkCollection (name: string) (fields: Value list) =\n    match name, fields with\n    | \"lawspec.collections::type::Set\", [ List items ] ->\n        if not (strictOrder items) then fail \"RefinementViolation\" name\n    | \"lawspec.collections::type::KeyVal\", [ List entries ] ->\n        let keys = entries |> List.map (function Data(_, [ k; _ ]) -> k | _ -> fail \"InvalidValue\" name)\n        if not (strictOrder keys) then fail \"RefinementViolation\" name\n    | _ -> ()\n\nlet private checkPredicates (c: Constructor) args values schema =\n    for predicate in c.Predicates do\n        if not (predicate schema args values) then fail \"RefinementViolation\" c.Tag\n\n/// Check a value against a type: shape, field contracts, index guards and the\n/// canonical order of collections. Returns the value.\nlet rec validate (value: Value) (t: TypeRef) (schema: Schema) : Value =\n    checkType t schema\n    walk value t schema true\n\nand private walk value t schema deep =\n    match t, value with\n    | Named(\"List\", [ element ]), List items -> List(items |> List.map (fun v -> walk v element schema deep))\n    | Named((\"Optional\" | \"Nullable\") as kind, [ inner ]), Presence(k, present) when k = kind ->\n        Presence(kind, present |> Option.map (fun v -> walk v inner schema deep))\n    | Named(name, _), _ ->\n        match schema.Definitions.TryFind name with\n        | Some d when d.Handle ->\n            match value with\n            | Handle(n, _) when n = name -> value\n            | _ -> fail \"InvalidHandle\" name\n        | _ ->\n            match constructors t schema with\n            | None -> Scalar.validate value t schema.Bits\n            | Some cs -> walkData value t cs schema deep\n    | Parameter _, _ -> fail \"UnboundSchemaParameter\" \"\"\n\nand private walkData value t cs schema deep =\n    match value with\n    | Data(tag, fields) ->\n        let c = findConstructor tag cs\n        if List.length fields <> List.length c.Fields then fail \"WrongFieldCount\" tag\n        let typed = witnessed c fields schema\n        let converted = if deep then List.map2 (fun f (_, ft) -> walk f ft schema deep) fields typed else fields\n        let args = match t with Named(_, a) -> a | _ -> []\n        checkPredicates c args converted schema\n        checkIndices { c with Fields = typed } converted schema\n        checkCollection (match t with Named(n, _) -> n | _ -> \"\") converted\n        Data(tag, converted)\n    | _ -> fail \"ExpectedData\" (Scalar.typeKey t)\n\n/// Build a value from checked fields: the fields are not walked again, but\n/// the constructor's contracts are checked.\nlet construct (tag: string) (fields: Value list) (t: TypeRef) (schema: Schema) : Value =\n    match tag, fields with\n    | \"List::Nil\", [] -> List []\n    | \"List::Cons\", [ head; List tail ] -> List(head :: tail)\n    | _ ->\n        checkType t schema\n        match constructors t schema with\n        | Some cs -> walkData (Data(tag, fields)) t cs schema false\n        | None -> fail \"ExpectedData\" (Scalar.typeKey t)\n\n/// Branch on a value's constructor.\nlet matchValue (value: Value) (branches: Map<string, Value list -> 'a>) : 'a =\n    match value with\n    | List [] -> branches.[\"List::Nil\"] []\n    | List(head :: tail) -> branches.[\"List::Cons\"] [ head; List tail ]\n    | Data(tag, fields) ->\n        match branches.TryFind tag with\n        | Some branch -> branch fields\n        | None -> fail \"MatchFailure\" tag\n    | _ -> fail \"ExpectedData\" \"\"\n\n/// The field types of a checked data value (a recording uses them to tell Text\n/// from Bytes and Char from an integer).\nlet fieldTypes (value: Value) (t: TypeRef) (schema: Schema) =\n    match value, constructors t schema with\n    | Data(tag, values), Some cs ->\n        let c = findConstructor tag cs\n        witnessed c values schema |> List.map snd\n    | _ -> fail \"ExpectedData\" (Scalar.typeKey t)\n\n// ---------------------------------------------------------------------------\n// Payloads\n\ntype private Recipe =\n    | NoPayload\n    | Predicate of (Value -> bool)\n    | Container of string * Recipe list\n\nlet rec private recipe (t: TypeRef) (args: Recipe list) =\n    match t with\n    | Parameter i -> if i < List.length args then List.item i args else NoPayload\n    | Named(name, fields) ->\n        let children = fields |> List.map (fun f -> recipe f args)\n        if children |> List.forall (function NoPayload -> true | _ -> false) then NoPayload\n        else Container(name, children)\n\nlet rec private payload (r: Recipe) (value: Value) (schema: Schema) =\n    match r, value with\n    | NoPayload, _ -> true\n    | Predicate p, _ -> p value\n    | Container(\"List\", [ inner ]), List items -> items |> List.forall (fun v -> payload inner v schema)\n    | Container(_, [ _ ]), Presence(_, None) -> true\n    | Container(_, [ inner ]), Presence(_, Some v) -> payload inner v schema\n    | Container(\"Maybe\", _), Data(\"Maybe::Nothing\", []) -> true\n    | Container(\"Maybe\", [ inner ]), Data(\"Maybe::Just\", [ v ]) -> payload inner v schema\n    | Container(\"Either\", [ inner; _ ]), Data(\"Either::Left\", [ v ]) -> payload inner v schema\n    | Container(\"Either\", [ _; inner ]), Data(\"Either::Right\", [ v ]) -> payload inner v schema\n    | Container(name, args), Data(tag, values) ->\n        let c = findConstructor tag schema.Definitions.[name].Constructors\n        List.forall2 (fun (_, ft) v -> payload (recipe ft args) v schema) c.Fields values\n    | _ -> fail \"InvalidPayload\" \"\"\n\n/// Whether every payload of a container (each value at a type parameter)\n/// satisfies that parameter's predicate.\nlet allPayloads (value: Value) (t: TypeRef) (predicates: (Value -> bool) list) (schema: Schema) =\n    match t with\n    | Named(name, args) ->\n        if List.length args <> List.length predicates then fail \"PayloadArityMismatch\" name\n        validate value t schema |> ignore\n        payload (Container(name, predicates |> List.map Predicate)) value schema\n    | Parameter _ -> fail \"UnboundSchemaParameter\" \"\"\n\n// ---------------------------------------------------------------------------\n// Builders, as the generated schema module writes a program's data\n\n/// A field's name and type (by key).\nlet field (name: string) (key: string) = name, Scalar.typeOf key\n\n/// A data definition.\nlet definition (name: string) (parameters: int) (constructors: Constructor list) (handle: bool) =\n    { Name = name; Parameters = parameters; Constructors = constructors; Handle = handle }\n\nlet withPredicates predicates (c: Constructor) = { c with Predicates = predicates }\n\nlet withGenerators (generators: (int * (Schema -> TypeRef list -> Value list -> FieldHints)) list) (c: Constructor) =\n    { c with Generators = Map.ofList generators }\n\nlet withIndices indices (c: Constructor) = { c with Indices = indices }\n\nlet withRefinements refinements (c: Constructor) = { c with Refinements = refinements }\n\nlet withExistentials count (c: Constructor) = { c with Existentials = count }\n\nlet withWitnesses witnesses (c: Constructor) = { c with Witnesses = witnesses }\n\n/// A refinement of a parameter, by position, to a type (by key).\nlet refinement (index: int) (key: string) = index, Scalar.typeOf key\n\n/// A constructor contract's known parameter types, by position.\nlet known (types: TypeRef list) = types |> List.mapi (fun i t -> i, t) |> Map.ofList\n\n/// A field's generation hints.\nlet hints bounds lengths values = { Bounds = bounds; Lengths = lengths; Hints = values }\n"
dotnetSource "LawSpec.Runtime/Tasks.fs" = "/// Cancellation scopes: a scope owns the work started beneath it, including\n/// nested scopes, and closing it cancels that work. .NET cannot kill a\n/// running task, so cancellation is cooperative: a scope's token is the one\n/// its work observes, and a closed scope never waits for work that ignores\n/// it. ref:DEC-async-native-tasks ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Tasks\n\nopen System\nopen System.Threading\nopen System.Threading.Tasks\n\n/// A cancellation scope and the work it owns.\n[<Sealed; AllowNullLiteral>]\ntype Scope(parent: Scope, parentToken: CancellationToken) =\n    let source =\n        if isNull (box parent) then new CancellationTokenSource()\n        else CancellationTokenSource.CreateLinkedTokenSource(parentToken)\n    let work = ResizeArray<Task>()\n    member _.Parent = parent\n    member _.Token = source.Token\n    member _.IsClosed = source.IsCancellationRequested\n    /// Register work started in this scope.\n    member _.Own(task: Task) = lock work (fun () -> work.Add task)\n    member _.Work = lock work (fun () -> List.ofSeq work)\n    /// Cancel everything the scope owns.\n    member _.Close() =\n        try source.Cancel() with _ -> ()\n\nlet private current = AsyncLocal<Scope>()\n\n/// The innermost scope, or null outside any.\n[<CompiledName(\"Current\")>]\nlet currentScope () = current.Value\n\n/// The token of the innermost scope (none outside any).\n[<CompiledName(\"Token\")>]\nlet token () =\n    match current.Value with\n    | null -> CancellationToken.None\n    | scope -> scope.Token\n\n/// Run a body in a new scope, closing it (and cancelling its work) after.\n[<CompiledName(\"WithScope\")>]\nlet withScope (body: Scope -> 'a) : 'a =\n    let previous = current.Value\n    let scope = Scope(previous, (match previous with null -> CancellationToken.None | p -> p.Token))\n    current.Value <- scope\n    try body scope\n    finally\n        current.Value <- previous\n        scope.Close()\n\n/// Start work in the current scope; it sees the caller's ambient context\n/// (handlers, workflow runtime) and the scope's token.\n[<CompiledName(\"Start\")>]\nlet start (body: unit -> 'a) : Task<'a> =\n    let scope = current.Value\n    let task = Task.Run((fun () -> body ()), (match scope with null -> CancellationToken.None | s -> s.Token))\n    match scope with\n    | null -> ()\n    | s -> s.Own task\n    task\n\n/// Fail with OperationCanceledException if the current scope was closed.\n[<CompiledName(\"Check\")>]\nlet check () = token().ThrowIfCancellationRequested()\n"
dotnetSource "LawSpec.Runtime/Values.fs" = "/// LawSpec's portable values, as the generated laws and the dynamic\n/// definitions see them. Native F# and C# code never handles these directly:\n/// generated codecs convert at the boundary to records, unions and the .NET\n/// types the adapters use. ref:DEC-fsharp-runtime-from-scratch\n/// ref:DEC-typed-core-boundary\nnamespace LawSpec.Runtime\n\nopen System\nopen System.Numerics\n\n/// A value in LawSpec's portable domain. Exact numbers stay exact, IEEE\n/// values keep their bits (so a NaN payload and a negative zero survive), and\n/// data is a constructor tag with its fields in declaration order.\n[<StructuralEquality; NoComparison>]\ntype Value =\n    | Bool of bool\n    | Int of BigInteger\n    /// A normalized fraction: positive denominator, lowest terms.\n    | Ratio of numerator: BigInteger * denominator: BigInteger\n    /// coefficient * 10 ^ exponent, with the scale it was written with.\n    | Decimal of coefficient: BigInteger * exponent: int\n    | Float of width: int * bits: uint64\n    | Complex of width: int * real: Value * imaginary: Value\n    /// Unicode text; it never holds a lone surrogate.\n    | Text of string\n    | Bytes of byte[]\n    /// CodePointText and Utf16Text: their units, without validation as text.\n    | Raw of kind: string * units: int list\n    | Unit\n    | Null\n    | Undefined\n    /// Two symbols are equal when they share an identity.\n    | Symbol of identity: obj * description: string\n    | List of Value list\n    | Data of tag: string * fields: Value list\n    /// Nullable or Optional: absent, or present with a value.\n    | Presence of kind: string * value: Value option\n    /// A handle's identity crosses the native boundary unchanged.\n    | Handle of name: string * identity: obj\n\n/// A type as the runtime checks it: a name applied to arguments, or a data\n/// declaration's parameter by position.\n[<StructuralEquality; StructuralComparison>]\ntype TypeRef =\n    | Named of name: string * arguments: TypeRef list\n    | Parameter of index: int\n\n/// A broken contract, an unmet law or a malformed value. The code names the\n/// kind of failure (StrategyOutsideRefinement, EquationFailed, ...), so test\n/// output names it the same way on every .NET target.\ntype LawSpecException(code: string, detail: string, context: string list, inner: exn) =\n    inherit Exception(\n        (match context with\n         | [] -> \"\"\n         | _ -> String.Join(\": \", List.rev context) + \": \")\n        + code\n        + (if String.IsNullOrEmpty detail then \"\" else \" \" + detail),\n        inner)\n    new(code, detail) = LawSpecException(code, detail, [], null)\n    member _.Code = code\n    member _.Detail = detail\n    member _.Context = context\n    /// The same failure, inside one more definition or law.\n    member this.Within(identity: string) =\n        LawSpecException(code, detail, identity :: context, this.InnerException)\n\n/// A failure an operation raised with `raise`, carrying its portable value\n/// until an `attempt` catches it. ref:DEC-typed-native-definitions\ntype RaisedFailure(ability: string, failure: Value) =\n    inherit Exception(\"LawSpec failure raised by \" + ability + \": \" + sprintf \"%A\" failure)\n    member _.Ability = ability\n    member _.Failure = failure\n\n/// Helpers for raising LawSpec's failures.\nmodule Fail =\n    /// Raise a LawSpec failure with a code and detail.\n    let inline raiseWith code detail : 'a = raise (LawSpecException(code, detail))\n\n    /// Fail unless the condition holds.\n    let inline require condition code detail =\n        if not condition then raiseWith code detail\n"
dotnetSource "LawSpec.Runtime/Workflow.fs" = "/// Workflows on .NET: stages run under their policies (gates, retries with\n/// jittered backoff, timeouts, hedges, caches) and a workflow compensates\n/// the stages that succeeded when it fails. A workflow runtime owns the\n/// policy state, the virtual time and the trace; it is ambient (AsyncLocal),\n/// so a test's calls and their concurrent work share it. Without one,\n/// workflows share the default runtime on the real clock, and a Clock in\n/// scope supplies its view of time. ref:DEC-domain-modeling-primitives\n/// ref:DEC-async-native-tasks ref:DEC-portable-seeded-generation\nmodule LawSpec.Runtime.Workflow\n\nopen System\nopen System.Diagnostics\nopen System.Numerics\nopen System.Threading\nopen System.Threading.Tasks\nopen LawSpec.Runtime.Policy\n\n/// Something that happened in a stage: start, finish, sleep, wait, hedge,\n/// cached or compensate, with the attempt (or delay) number.\ntype Event =\n    { Kind: string\n      Stage: string\n      Number: int64\n      Succeeded: bool }\n\n/// Where a runtime's time comes from.\ntype Clock =\n    | RealClock\n    | VirtualClock\n    | ClockCallbacks of now: (unit -> int64) * sleep: (int64 -> unit) * isVirtual: bool\n\ntype private StageRecord =\n    { StageKey: string\n      mutable Passed: ((string * GateKind) * Gate) list\n      mutable Time: int64 }\n\n/// A runtime's policy state: virtual time, the jitter stream, the trace,\n/// gate states, the cache, compensation frames and running stages. Every\n/// change is under its lock; gate callbacks are pure checked definitions.\n[<Sealed>]\ntype State(seed: BigInteger, time: int64) =\n    let gate = obj ()\n    let mutable now = time\n    let mutable random = Random.seed seed\n    let trace = ResizeArray<Event>()\n    let mutable states: Map<string * GateKind, Value> = Map.empty\n    let mutable cache: Map<string, (Value * Value * int64) list> = Map.empty\n    let frames = Collections.Generic.Dictionary<int64, (string * (unit -> Value)) list>()\n    let stages = Collections.Generic.Dictionary<int64, StageRecord>()\n    let mutable counter = 0L\n    member _.Now = lock gate (fun () -> now)\n    member _.SetTime(t: int64) = lock gate (fun () -> now <- t)\n    member _.Sleep(delay: int64) = lock gate (fun () -> now <- now + max 0L delay)\n    member _.Jitter(kind, delay, previous, baseDelay) =\n        lock gate (fun () ->\n            let value, next = Policy.jitter kind delay previous baseDelay random\n            random <- next\n            value)\n    member _.Event(e: Event) = lock gate (fun () -> trace.Add e)\n    member _.Trace = lock gate (fun () -> List.ofSeq trace)\n    member _.Cached(key: string, input: Value, at: int64) =\n        lock gate (fun () ->\n            let live = defaultArg (cache.TryFind key) [] |> List.filter (fun (_, _, until) -> at < until)\n            cache <- cache.Add(key, live)\n            live |> List.tryPick (fun (k, v, _) -> if Scalar.equal k input then Some v else None))\n    member _.Cache(key: string, input: Value, value: Value, at: int64, ttl: int64) =\n        lock gate (fun () ->\n            let live =\n                defaultArg (cache.TryFind key) []\n                |> List.filter (fun (k, _, until) -> at < until && not (Scalar.equal k input))\n            cache <- cache.Add(key, (input, value, at + ttl) :: live))\n    member _.NewFrame() =\n        lock gate (fun () ->\n            counter <- counter + 1L\n            frames.[counter] <- []\n            counter)\n    member _.Undo(frame: int64, stage: string, undo: unit -> Value) =\n        lock gate (fun () ->\n            match frames.TryGetValue frame with\n            | true, undos -> frames.[frame] <- (stage, undo) :: undos\n            | _ -> ())\n    member _.TakeFrame(frame: int64) =\n        lock gate (fun () ->\n            match frames.TryGetValue frame with\n            | true, undos ->\n                frames.Remove frame |> ignore\n                undos\n            | _ -> [])\n    member _.NewStage(key: string, at: int64) =\n        lock gate (fun () ->\n            counter <- counter + 1L\n            stages.[counter] <- { StageKey = key; Passed = []; Time = at }\n            counter)\n    /// A gate's decision for a running stage, updating the gate's state.\n    member _.Gate(stage: int64, g: Gate, at: int64) =\n        lock gate (fun () ->\n            let record = stages.[stage]\n            let key = record.StageKey, g.Kind\n            let before =\n                match states.TryFind key with\n                | Some s -> s\n                | None -> g.Start(Int(BigInteger at))\n            match g.Admit before (Int(BigInteger at)) with\n            | Data(_, [ after; decision ]) ->\n                states <- states.Add(key, after)\n                match decision with\n                | Data(\"lawspec.resilience::type::Gate::Admit\", []) -> record.Passed <- record.Passed @ [ key, g ]\n                | _ -> ()\n                record.Time <- at\n                decision\n            | other -> Fail.raiseWith \"InvalidGateStep\" (sprintf \"%A\" other))\n    /// A stage ended: each gate it passed records the outcome.\n    member _.FinishStage(stage: int64, at: int64, succeeded: bool) =\n        lock gate (fun () ->\n            match stages.TryGetValue stage with\n            | true, record ->\n                stages.Remove stage |> ignore\n                for key, g in record.Passed do\n                    match g.Finish with\n                    | Some finish -> states <- states.Add(key, finish states.[key] (Int(BigInteger at)) (Bool succeeded))\n                    | None -> ()\n            | _ -> ())\n\n/// A workflow runtime: its state, its clock, whether gates and caches\n/// apply, and whether it was installed explicitly (an explicit runtime's\n/// clock is not replaced by a Clock in scope).\ntype Runtime =\n    { State: State\n      Clock: Clock\n      Gates: bool\n      Explicit: bool }\n\nlet private ambient = AsyncLocal<Runtime option>()\nlet private shared = lazy { State = State(BigInteger.Zero, 0L); Clock = RealClock; Gates = true; Explicit = false }\n\nlet private scoped (runtime: Runtime) (body: Runtime -> 'a) : 'a =\n    let previous = ambient.Value\n    ambient.Value <- Some runtime\n    try body runtime\n    finally ambient.Value <- previous\n\nlet private seedOf () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n    | null | \"\" -> BigInteger.Zero\n    | s -> (try BigInteger.Parse s with _ -> BigInteger.Zero)\n\n/// Run a body with its own runtime on a clock, from a seed.\n[<CompiledName(\"WithClock\")>]\nlet withClock (clock: Clock) (seed: BigInteger) (body: Runtime -> 'a) : 'a =\n    scoped { State = State(seed, 0L); Clock = clock; Gates = true; Explicit = true } body\n\n/// A runtime on a virtual clock that starts at 0 and moves only when told.\n[<CompiledName(\"WithVirtual\")>]\nlet withVirtual (seed: BigInteger) (body: Runtime -> 'a) : 'a = withClock VirtualClock seed body\n\n/// A runtime on the real clock.\n[<CompiledName(\"WithReal\")>]\nlet withReal (seed: BigInteger) (body: Runtime -> 'a) : 'a = withClock RealClock seed body\n\n/// A runtime whose clock is two callbacks (microseconds).\n[<CompiledName(\"WithClockCallbacks\")>]\nlet withClockCallbacks (now: unit -> int64) (sleep: int64 -> unit) (isVirtual: bool) (seed: BigInteger) (body: Runtime -> 'a) : 'a =\n    withClock (ClockCallbacks(now, sleep, isVirtual)) seed body\n\n/// A law's runtime: virtual time and no gates or caches, from the run's\n/// seed; a Clock in scope (`using virtual clock`) supplies the time.\n[<CompiledName(\"WithTestRuntime\")>]\nlet withTestRuntime (body: unit -> 'a) : 'a =\n    scoped { State = State(seedOf (), 0L); Clock = VirtualClock; Gates = false; Explicit = false } (fun _ -> body ())\n\nlet rec private isRealClock (handler: Effects.Handler) =\n    match handler with\n    | Effects.Recording(_, inner) -> isRealClock inner\n    | Effects.Stateless clauses ->\n        // The default Clock's clauses are closures of the Defaults module.\n        match clauses.TryFind \"now\" with\n        | Some clause -> clause.GetType().FullName.StartsWith \"LawSpec.Runtime.Defaults\"\n        | None -> false\n    | Effects.Stateful _ -> false\n\n/// The runtime a stage runs under: the ambient one (or the shared default),\n/// timed by the Clock in scope unless the runtime was installed explicitly.\n[<CompiledName(\"Current\")>]\nlet current (schema: Schema.Schema) : Runtime =\n    let baseRuntime = defaultArg ambient.Value shared.Value\n    match baseRuntime.Explicit, schema.Handlers.TryFind \"lawspec.time::ability::Clock\" with\n    | false, Some boxed ->\n        let handler: Effects.Handler = unbox boxed\n        let now () =\n            match Effects.invoke handler schema \"now\" [] with\n            | Data(_, [ Int t ]) -> int64 t\n            | other -> Fail.raiseWith \"InvalidInstant\" (sprintf \"%A\" other)\n        let sleep (delay: int64) =\n            Effects.invoke handler schema \"sleep\" [ Data(\"lawspec.time::type::Duration::Duration\", [ Int(BigInteger delay) ]) ]\n            |> ignore\n        { baseRuntime with Clock = ClockCallbacks(now, sleep, not (isRealClock handler)) }\n    | _ -> baseRuntime\n\n/// The ambient runtime (the shared default outside any).\n[<CompiledName(\"Ambient\")>]\nlet ambientRuntime () = defaultArg ambient.Value shared.Value\n\nlet private isVirtual (runtime: Runtime) =\n    match runtime.Clock with\n    | VirtualClock -> true\n    | RealClock -> false\n    | ClockCallbacks(_, _, v) -> v\n\n/// The runtime's time, in microseconds.\n[<CompiledName(\"Now\")>]\nlet now (runtime: Runtime) : int64 =\n    match runtime.Clock with\n    | RealClock -> Defaults.nowMicros ()\n    | VirtualClock -> runtime.State.Now\n    | ClockCallbacks(read, _, _) -> read ()\n\n/// Let time pass: at once on a virtual clock.\n[<CompiledName(\"Sleep\")>]\nlet sleep (runtime: Runtime) (delay: int64) =\n    if delay > 0L then\n        match runtime.Clock with\n        | RealClock -> Defaults.sleepMicros delay\n        | VirtualClock -> runtime.State.Sleep delay\n        | ClockCallbacks(_, wait, _) -> wait delay\n\n/// Set a virtual runtime's time.\n[<CompiledName(\"SetTime\")>]\nlet setTime (runtime: Runtime) (time: int64) =\n    match runtime.Clock with\n    | VirtualClock -> runtime.State.SetTime time\n    | _ -> Fail.raiseWith \"NotVirtual\" \"only a virtual runtime's time is set\"\n\n/// What happened, in order.\n[<CompiledName(\"Trace\")>]\nlet trace (runtime: Runtime) : Event list = runtime.State.Trace\n\nlet private event (runtime: Runtime) (policy: StagePolicy) kind number succeeded =\n    runtime.State.Event { Kind = kind; Stage = policy.Stage; Number = number; Succeeded = succeeded }\n\n// ---------------------------------------------------------------------------\n// Real-clock timeouts and hedges. ref:DEC-async-native-tasks\n\nlet private micros () = Stopwatch.GetTimestamp() * 1_000_000L / Stopwatch.Frequency\n\n/// Run attempts of a body on the real clock: a hedge starts another after\n/// the delay, up to most; the first success wins, or the last failure after\n/// every attempt; past the deadline the stage is TimedOut. Losing attempts\n/// are cancelled through their scope, never awaited.\n[<CompiledName(\"RunAttempts\")>]\nlet runAttempts (timeout: int64 option) (hedge: (int64 * int64) option) (body: unit -> Value) (onHedge: int64 -> unit) : Value =\n    Tasks.withScope (fun _ ->\n        let start = micros ()\n        let deadline =\n            match timeout with\n            | Some t when t > 0L -> Some(start + t)\n            | _ -> None\n        let delay, most =\n            match hedge with\n            | Some(d, m) -> max 0L d, max 1L m\n            | None -> 0L, 1L\n        let launch (number: int64) =\n            if number > 1L then onHedge number\n            Tasks.start (fun () ->\n                let result = try Choice1Of2(body ()) with e -> Choice2Of2 e\n                micros (), result)\n        let mutable workers = [ launch 1L ]\n        let mutable started = 1L\n        let mutable next = start + delay\n        let mutable outcome = None\n        while outcome.IsNone do\n            let current = micros ()\n            let timer =\n                let hedgeAt = if started < most then Some next else None\n                match deadline, hedgeAt with\n                | Some d, Some h -> Some(min d h)\n                | Some d, None -> Some d\n                | None, h -> h\n            let waitMs =\n                match timer with\n                | Some t -> int (max 0L ((t - current + 999L) / 1000L))\n                | None -> -1\n            let finished = Task.WaitAny((workers |> List.map (fun t -> t :> Task) |> Array.ofList), waitMs)\n            if finished >= 0 then\n                let worker = List.item finished workers\n                let rest = workers |> List.filter (fun w -> not (obj.ReferenceEquals(w, worker)))\n                workers <- rest\n                let ended, result = worker.Result\n                match result with\n                | _ when deadline.IsSome && ended > deadline.Value -> outcome <- Some(stageFailure \"TimedOut\")\n                | Choice2Of2 e -> raise e\n                | Choice1Of2 value when not (failed value) -> outcome <- Some value\n                | Choice1Of2 value when List.isEmpty rest && started >= most -> outcome <- Some value\n                | Choice1Of2 _ when List.isEmpty rest ->\n                    if deadline.IsNone || micros () < deadline.Value then\n                        started <- started + 1L\n                        workers <- [ launch started ]\n                        next <- micros () + delay\n                    else outcome <- Some(stageFailure \"TimedOut\")\n                | Choice1Of2 _ -> ()\n            else\n                let at = micros ()\n                if deadline.IsSome && at >= deadline.Value then outcome <- Some(stageFailure \"TimedOut\")\n                elif started < most && at >= next then\n                    started <- started + 1L\n                    workers <- workers @ [ launch started ]\n                    next <- micros () + delay\n        outcome.Value)\n\n// ---------------------------------------------------------------------------\n// Stages and workflows\n\ntype private Frame = { FrameState: State; Id: int64 }\n\nlet private frame = AsyncLocal<Frame option>()\n\nlet rec private virtualHedge (hedge: (int64 * int64) option) (body: unit -> Value) (onHedge: int64 -> unit) (started: int64) =\n    match hedge with\n    | None -> body ()\n    | Some(_, most) ->\n        let result = body ()\n        if failed result && started < most then\n            onHedge (started + 1L)\n            virtualHedge hedge body onHedge (started + 1L)\n        else result\n\nlet private timed (runtime: Runtime) (policy: StagePolicy) (body: unit -> Value) =\n    let onHedge n = event runtime policy \"hedge\" n true\n    if isVirtual runtime then\n        let began = now runtime\n        let result = virtualHedge policy.Hedge body onHedge 1L\n        match policy.Timeout with\n        | Some t when t > 0L && now runtime - began > t -> stageFailure \"TimedOut\"\n        | _ -> result\n    elif runtime.Gates && (policy.Timeout.IsSome || policy.Hedge.IsSome) then\n        runAttempts policy.Timeout policy.Hedge body onHedge\n    else body ()\n\nlet private retryError (wraps: bool) (error: Value) =\n    match wraps, error with\n    | false, _ -> Some error\n    | true, Data(\"lawspec.resilience::type::StageFailure::StepFailed\", [ inner ]) -> Some inner\n    | true, Data(\"lawspec.resilience::type::StageFailure::TimedOut\", []) -> Some error\n    | true, _ -> None\n\nlet private retryWait (runtime: Runtime) (retry: Retry) (number: int64) (reason: Value) (previous: int64) =\n    match retry.Strategy with\n    | Custom decide ->\n        decide (Int(BigInteger number)) reason (Data(\"lawspec.time::type::Duration::Duration\", [ Int(BigInteger previous) ]))\n        |> retryDecision\n    | strategy ->\n        let delay = retryDelay strategy number\n        let baseDelay = retryDelay strategy 2L\n        Some(runtime.State.Jitter(retry.Jitter, delay, previous, baseDelay))\n\nlet rec private attempts (runtime: Runtime) (policy: StagePolicy) (body: unit -> Value) (number: int64) (previous: int64) =\n    event runtime policy \"start\" number false\n    let result = timed runtime policy body\n    let isFailure = failed result\n    event runtime policy \"finish\" number (not isFailure)\n    match isFailure, policy.Retry, result with\n    | true, Some retry, Data(_, [ error ]) ->\n        match retryError policy.Wraps error with\n        | None -> result\n        | Some reason ->\n            let exhausted = retry.Attempts > 0L && number >= retry.Attempts\n            let refused =\n                match retry.When with\n                | Some condition ->\n                    match condition reason with\n                    | Bool holds -> not holds\n                    | other -> Fail.raiseWith \"BoolRequired\" (sprintf \"%A\" other)\n                | None -> false\n            if exhausted || refused then result\n            else\n                match retryWait runtime retry (number + 1L) reason previous with\n                | None -> result\n                | Some delay ->\n                    event runtime policy \"sleep\" delay true\n                    sleep runtime delay\n                    attempts runtime policy body (number + 1L) delay\n    | _ -> result\n\nlet private gateFailure (kind: GateKind) =\n    match kind with\n    | Breaker -> \"CircuitOpen\"\n    | Limit -> \"RateLimited\"\n    | Bulkhead -> \"Saturated\"\n\nlet rec private passGate (runtime: Runtime) (stage: int64) (policy: StagePolicy) (g: Gate) (waited: int64) =\n    match runtime.State.Gate(stage, g, now runtime) with\n    | Data(\"lawspec.resilience::type::Gate::Admit\", []) -> None\n    | Data(\"lawspec.resilience::type::Gate::Reject\", []) -> Some(gateFailure g.Kind)\n    | _ when g.Wait = NoWait -> Some(gateFailure g.Kind)\n    | Data(\"lawspec.resilience::type::Gate::WaitFor\", [ Int d ]) ->\n        let delay = int64 d\n        match g.Wait with\n        | Within most when waited + delay > most -> Some(gateFailure g.Kind)\n        | _ ->\n            event runtime policy \"wait\" delay true\n            sleep runtime delay\n            passGate runtime stage policy g (waited + delay)\n    | other -> Fail.raiseWith \"InvalidGateDecision\" (sprintf \"%A\" other)\n\nlet private passGates runtime stage policy (gates: Gate list) =\n    gates |> List.tryPick (fun g -> passGate runtime stage policy g 0L)\n\nlet private rememberUndo (runtime: Runtime) (policy: StagePolicy) (result: Value) =\n    match frame.Value, policy.Compensate with\n    | Some f, Some undo when obj.ReferenceEquals(f.FrameState, runtime.State) ->\n        let value =\n            match result with\n            | Data(\"Either::Right\", [ inner ]) -> inner\n            | _ -> result\n        runtime.State.Undo(f.Id, policy.Stage, fun () -> undo value)\n    | _ -> ()\n\n/// Run a stage of a workflow under its policy. The input is the stage's\n/// argument, the key of its cache.\n[<CompiledName(\"RunStage\")>]\nlet runStage (schema: Schema.Schema) (policy: StagePolicy) (body: unit -> Value) (input: Value) : Value =\n    let runtime = current schema\n    let caching = runtime.Gates && policy.Cache.IsSome\n    let cached = if caching then runtime.State.Cached(policy.Key, input, now runtime) else None\n    match cached with\n    | Some value ->\n        event runtime policy \"cached\" 0L true\n        value\n    | None ->\n        let stage = runtime.State.NewStage(policy.Key, now runtime)\n        let gates = if runtime.Gates then policy.Gates else []\n        let outcome =\n            try\n                Choice1Of2(\n                    match passGates runtime stage policy gates with\n                    | None -> attempts runtime policy body 1L 0L\n                    | Some kind -> stageFailure kind\n                )\n            with e -> Choice2Of2 e\n        let succeeded =\n            match outcome with\n            | Choice1Of2 v -> not (failed v)\n            | Choice2Of2 _ -> false\n        runtime.State.FinishStage(stage, now runtime, succeeded)\n        match outcome with\n        | Choice2Of2 e -> raise e\n        | Choice1Of2 value ->\n            if succeeded then\n                rememberUndo runtime policy value\n                if caching then runtime.State.Cache(policy.Key, input, value, now runtime, policy.Cache.Value)\n            value\n\n/// Run a workflow: when it fails, undo the stages that succeeded, the\n/// latest first.\n[<CompiledName(\"RunWorkflow\")>]\nlet runWorkflow (schema: Schema.Schema) (body: unit -> Value) : Value =\n    let runtime = current schema\n    let id = runtime.State.NewFrame()\n    let previous = frame.Value\n    frame.Value <- Some { FrameState = runtime.State; Id = id }\n    let outcome =\n        try\n            try Choice1Of2(body ())\n            with e -> Choice2Of2 e\n        finally\n            frame.Value <- previous\n    let undos = runtime.State.TakeFrame id\n    match outcome with\n    | Choice2Of2 e -> raise e\n    | Choice1Of2 result ->\n        if failed result then\n            for stageName, undo in undos do\n                runtime.State.Event { Kind = \"compensate\"; Stage = stageName; Number = 0L; Succeeded = true }\n                undo () |> ignore\n        result\n"
dotnetSource "LawSpec.Testing/CryptoVectors.fs" = "/// NIST known-answer checks of the default crypto primitives, over the\n/// vectors every target shares (runtime/defaults/vectors.txt, provenance in\n/// docs/reference/language/cryptography.md). ref:DEC-tests-cite-requirements\nmodule LawSpec.Testing.CryptoVectors\n\nopen System\nopen LawSpec.Runtime\n\nlet private fail (kind: string) (detail: string) : 'a = Fail.raiseWith \"CryptoVectorFailed\" (kind + \": \" + detail)\n\nlet private hex (text: string) = if text = \"-\" then [||] else Convert.FromHexString text\nlet private digest (bytes: byte[]) = Convert.ToHexString(Crypto.sha3 bytes).ToLowerInvariant()\nlet private flip (bytes: byte[]) =\n    let copy = Array.copy bytes\n    copy.[0] <- copy.[0] ^^^ 1uy\n    copy\n\nlet private same (kind: string) (what: string) (expected: byte[]) (actual: byte[]) =\n    if expected <> actual then fail kind (what + \" differs\")\n\nlet private holds (kind: string) (what: string) (condition: bool) = if not condition then fail kind what\n\n/// Check every vector of a kind in the vectors text.\n[<CompiledName(\"Check\")>]\nlet check (vectors: string) (kind: string) =\n    let rows =\n        vectors.Split('\\n')\n        |> Array.map (fun line -> line.Split(' ', StringSplitOptions.RemoveEmptyEntries))\n        |> Array.filter (fun fields -> fields.Length > 0 && fields.[0] = kind)\n        |> Array.map (fun fields -> List.ofArray fields.[1..])\n    if rows.Length = 0 then fail kind \"no vectors\"\n    for row in rows do\n        match kind, row with\n        | \"sha3-256\", [ message; expected ] -> same kind \"digest\" (hex expected) (Crypto.sha3 (hex message))\n        | \"shake256\", [ message; count; expected ] -> same kind \"output\" (hex expected) (Crypto.shake (hex message) (int count))\n        | \"aes-256-gcm\", [ key; nonce; message; associated; ciphertext; tag ] ->\n            let key, nonce, message, associated = hex key, hex nonce, hex message, hex associated\n            let expected = Array.append (hex ciphertext) (hex tag)\n            same kind \"sealed\" expected (Crypto.aes256GcmEncrypt key nonce message associated)\n            holds kind \"decrypts\" (Crypto.aes256GcmDecrypt key nonce expected associated = Some message)\n            holds kind \"rejects a changed ciphertext\" (Crypto.aes256GcmDecrypt key nonce (flip expected) associated = None)\n        | \"mlkem768-keygen\", [ d; z; publicDigest; privateDigest ] ->\n            let seed = hex (d + z)\n            let publicKey, privateKey = Crypto.mlkemExpand seed\n            holds kind \"public key\" (digest publicKey = publicDigest)\n            holds kind \"private key\" (digest privateKey = privateDigest)\n            holds kind \"key pair\" (Crypto.mlkemKeyPair seed = (publicKey, seed))\n        | \"mlkem768-encaps\", [ publicKey; message; ciphertext; shared ] ->\n            let c, s = Crypto.mlkemEncapsulateWith (hex publicKey) (hex message)\n            same kind \"ciphertext\" (hex ciphertext) c\n            same kind \"shared secret\" (hex shared) s\n        | \"mlkem768-decaps\", [ privateKey; ciphertext; shared ] ->\n            same kind \"shared secret\" (hex shared) (Crypto.mlkemDecapsulateExpanded (hex privateKey) (hex ciphertext))\n        | \"mlkem768-decaps-seed\", [ seed; ciphertext; shared ] ->\n            same kind \"shared secret\" (hex shared) (Crypto.mlkemDecapsulate (hex seed) (hex ciphertext))\n        | \"mldsa65-keygen\", [ seed; publicDigest; privateDigest ] ->\n            let publicKey, privateKey = Crypto.mldsaExpand (hex seed)\n            holds kind \"public key\" (digest publicKey = publicDigest)\n            holds kind \"private key\" (digest privateKey = privateDigest)\n            same kind \"public key of the seed\" publicKey (Crypto.mldsaPublic (hex seed))\n        | \"mldsa65-verify\", [ publicKey; message; context; signature; passed ] ->\n            holds kind \"verification\" (Crypto.mldsaVerifyWith (hex publicKey) (hex message) (hex signature) (hex context) = (passed = \"true\"))\n        | \"mldsa65-sign-seed\", [ seed; message; signature ] ->\n            let seed, message = hex seed, hex message\n            let signed = Crypto.mldsaSignWith seed message [||] true\n            same kind \"signature\" (hex signature) signed\n            let publicKey = Crypto.mldsaPublic seed\n            holds kind \"verifies\" (Crypto.mldsaVerify publicKey message signed)\n            holds kind \"rejects a changed message\" (not (Crypto.mldsaVerify publicKey (flip message) signed))\n        | \"slhdsa128f-keygen\", [ s; p; x; publicHex; privateDigest ] ->\n            let publicKey, privateKey = Crypto.slhKeyPairOf (hex (s + p + x))\n            same kind \"public key\" (hex publicHex) publicKey\n            holds kind \"private key\" (digest privateKey = privateDigest)\n            let message = Text.Encoding.ASCII.GetBytes \"LawSpec\"\n            let signature = Crypto.slhSign privateKey message\n            holds kind \"verifies\" (Crypto.slhVerify publicKey message signature)\n            holds kind \"rejects a changed message\" (not (Crypto.slhVerify publicKey (Text.Encoding.ASCII.GetBytes \"LawSpeC\") signature))\n        | \"slhdsa128f-verify\", [ publicKey; message; context; signature; passed ] ->\n            let publicKey, message, signature, context = hex publicKey, hex message, hex signature, hex context\n            holds kind \"verification\" (Crypto.slhVerifyWith publicKey message signature context = (passed = \"true\"))\n            holds kind \"rejects a changed message\" (not (Crypto.slhVerifyWith publicKey (flip message) signature context))\n        | _ -> fail kind (sprintf \"unexpected row of %d fields\" row.Length)\n"
dotnetSource "LawSpec.Testing/Gen.fs" = "/// LawSpec's property engine for .NET: seeded SplitMix64 generation with\n/// integrated shrinking. A generator yields a rose tree, the value with the\n/// smaller values it may shrink to, so shrinking a bound input rebuilds the\n/// inputs that depend on it and every candidate stays inside the domain.\n/// ref:DEC-portable-seeded-generation ref:DEC-shrink-within-domain\n/// ref:DEC-fsharp-runtime-from-scratch\nnamespace LawSpec.Testing\n\nopen System.Numerics\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Random\n\n/// A value and, lazily, the values it shrinks to, best first.\ntype Tree<'a> =\n    { Value: 'a\n      Children: seq<Tree<'a>> }\n\nmodule Tree =\n    let leaf value = { Value = value; Children = Seq.empty }\n\n    let rec map (f: 'a -> 'b) (tree: Tree<'a>) =\n        { Value = f tree.Value\n          Children = tree.Children |> Seq.map (map f) }\n\n    /// Keep only the candidates a predicate accepts, with their own candidates.\n    let rec filter (keep: 'a -> bool) (tree: Tree<'a>) =\n        { tree with Children = tree.Children |> Seq.filter (fun t -> keep t.Value) |> Seq.map (filter keep) }\n\n    /// Candidates from a function of a value, unfolded.\n    let rec unfold (shrink: 'a -> seq<'a>) (value: 'a) =\n        { Value = value\n          Children = shrink value |> Seq.map (unfold shrink) }\n\n/// A generator: a seed and a size to a tree, or None for an empty domain,\n/// which discards the whole tuple of inputs.\ntype Gen<'a> = Gen of (Seed -> int -> Tree<'a> option)\n\nmodule Gen =\n    let run (Gen g) seed size = g seed size\n\n    let constant value = Gen(fun _ _ -> Some(Tree.leaf value))\n\n    /// An empty domain: the case is discarded and redrawn.\n    let empty<'a> : Gen<'a> = Gen(fun _ _ -> None)\n\n    let map f (Gen g) = Gen(fun seed size -> g seed size |> Option.map (Tree.map f))\n\n    let rec private bindTree (tree: Tree<'a>) (k: 'a -> Tree<'b> option) : Tree<'b> option =\n        k tree.Value\n        |> Option.map (fun inner ->\n            { Value = inner.Value\n              Children =\n                Seq.append\n                    (tree.Children |> Seq.choose (fun child -> bindTree child k))\n                    inner.Children })\n\n    /// A generator that depends on another's value. Shrinking the first value\n    /// regenerates the second from the same seed.\n    let bind (Gen g) (k: 'a -> Gen<'b>) =\n        Gen(fun seed size ->\n            let s1, s2 = split seed\n            g s1 size |> Option.bind (fun tree -> bindTree tree (fun a -> run (k a) s2 size)))\n\n    let sized (f: int -> Gen<'a>) = Gen(fun seed size -> run (f size) seed size)\n\n    let resize size (Gen g) = Gen(fun seed _ -> g seed size)\n\n    let private towards (origin: BigInteger) (value: BigInteger) =\n        if value = origin then Seq.empty\n        else\n            seq {\n                yield origin\n                let mutable distance = (value - origin) / BigInteger 2\n                while not distance.IsZero do\n                    yield value - distance\n                    distance <- distance / BigInteger 2\n                if BigInteger.Abs(value - origin) > BigInteger.One then\n                    yield (if value > origin then value - BigInteger.One else value + BigInteger.One)\n            }\n            |> Seq.distinct\n\n    /// An integer in an inclusive range, shrinking towards the value nearest\n    /// zero. An open end is limited by the size, exponentially, so large\n    /// magnitudes appear as the size grows.\n    let integer (lo: BigInteger option) (hi: BigInteger option) =\n        Gen(fun seed size ->\n            let reach = BigInteger.Pow(BigInteger 2, min 64 (2 + size / 2))\n            let lo' = match lo, hi with\n                      | Some l, _ -> l\n                      | None, Some h -> BigInteger.Min(BigInteger.Zero, h) - reach\n                      | None, None -> -reach\n            let hi' = match hi, lo with\n                      | Some h, _ -> h\n                      | None, Some l -> BigInteger.Max(BigInteger.Zero, l) + reach\n                      | None, None -> reach\n            if lo' > hi' then None\n            else\n                let n, _ = below (hi' - lo' + BigInteger.One) seed\n                let value = lo' + n\n                let origin = BigInteger.Min(BigInteger.Max(BigInteger.Zero, lo'), hi')\n                Some(Tree.unfold (towards origin) value))\n\n    let range (lo: int) (hi: int) = integer (Some(BigInteger lo)) (Some(BigInteger hi)) |> map int\n\n    /// One of several generators, shrinking towards the earlier ones.\n    let oneof (gens: Gen<'a> list) =\n        match gens with\n        | [] -> empty\n        | _ ->\n            let arr = Array.ofList gens\n            bind (range 0 (arr.Length - 1)) (fun i -> arr.[i])\n\n    /// A weighted choice, shrinking towards the earlier ones.\n    let frequency (choices: (int * Gen<'a>) list) =\n        let total = choices |> List.sumBy fst\n        if total <= 0 then empty\n        else\n            bind (range 0 (total - 1)) (fun n ->\n                let rec pick n choices =\n                    match choices with\n                    | [ (_, g) ] -> g\n                    | (w, g) :: rest -> if n < w then g else pick (n - w) rest\n                    | [] -> empty\n                pick n choices)\n\n    let rec private sequenceTrees (trees: Tree<'a> list) : Tree<'a list> =\n        let values = trees |> List.map (fun t -> t.Value)\n        let removals =\n            seq {\n                let n = List.length trees\n                if n > 0 then\n                    yield []\n                    if n > 1 then yield List.take (n / 2) trees\n                    for i in 0 .. n - 1 do\n                        yield List.removeAt i trees\n            }\n            |> Seq.map sequenceTrees\n        let replacements =\n            seq {\n                for i, t in List.indexed trees do\n                    for child in t.Children do\n                        yield sequenceTrees (List.updateAt i child trees)\n            }\n        { Value = values\n          Children = Seq.append removals replacements }\n\n    let rec private productTrees (trees: Tree<'a> list) : Tree<'a list> =\n        { Value = trees |> List.map (fun t -> t.Value)\n          Children =\n            seq {\n                for i, t in List.indexed trees do\n                    for child in t.Children do\n                        yield productTrees (List.updateAt i child trees)\n            } }\n\n    let private draws (gens: Gen<'a> list) seed size =\n        let rec go gens seed acc =\n            match gens with\n            | [] -> Some(List.rev acc)\n            | g :: rest ->\n                let s1, s2 = split seed\n                match run g s1 size with\n                | None -> None\n                | Some t -> go rest s2 (t :: acc)\n        go gens seed []\n\n    /// A fixed number of values, each shrinking in place.\n    let vector count (g: Gen<'a>) =\n        Gen(fun seed size -> draws (List.replicate count g) seed size |> Option.map productTrees)\n\n    /// Values of several generators, in order.\n    let tuple (gens: Gen<'a> list) = Gen(fun seed size -> draws gens seed size |> Option.map productTrees)\n\n    /// A list of a length the size limits, shrinking by removing items and by\n    /// shrinking them.\n    let list (g: Gen<'a>) =\n        Gen(fun seed size ->\n            let s1, s2 = split seed\n            let n, _ = below (BigInteger(size + 1)) s1\n            draws (List.replicate (int n) g) s2 size |> Option.map sequenceTrees)\n\n    /// Keep values a predicate accepts, redrawing up to a limit; candidates\n    /// are filtered too.\n    let constrain (limit: int) (predicate: 'a -> bool) (Gen g) =\n        Gen(fun seed size ->\n            let rec attempt seed n =\n                if n <= 0 then None\n                else\n                    let s1, s2 = split seed\n                    match g s1 size with\n                    | Some tree when predicate tree.Value -> Some(Tree.filter predicate tree)\n                    | _ -> attempt s2 (n - 1)\n            attempt seed limit)\n\n    /// A dependent input's domain: an impossible value discards the tuple, so\n    /// an earlier input is redrawn rather than retried in vain.\n    let refine (predicate: 'a -> bool) (g: Gen<'a>) =\n        bind g (fun value -> if predicate value then constant value else empty)\n\n    /// Draw until a predicate holds, failing the harness after a limit.\n    let suchThat (predicate: 'a -> bool) (limit: int) (onExhausted: unit -> unit) (Gen g) =\n        Gen(fun seed size ->\n            let rec attempt seed n =\n                if n <= 0 then\n                    onExhausted ()\n                    None\n                else\n                    let s1, s2 = split seed\n                    match g s1 size with\n                    | Some tree when predicate tree.Value -> Some(Tree.filter predicate tree)\n                    | _ -> attempt s2 (n - 1)\n            attempt seed (limit + 1))\n\n    /// A weighted mix of fixed values and a generator.\n    let withExamples (examples: 'a list) (g: Gen<'a>) =\n        match examples with\n        | [] -> g\n        | _ -> frequency [ 1, oneof (examples |> List.map constant); 9, g ]\n\n    let apply (f: Gen<'a -> 'b>) (x: Gen<'a>) = bind f (fun f -> map f x)\n"
dotnetSource "LawSpec.Testing/Generators.fs" = "/// Generation from a program's schema: scalars within their refinement\n/// bounds, lists within their lengths, and data within a structural budget\n/// that counts every node, so recursive types terminate without a hidden cap\n/// and deep singletons stay reachable. Indexed families are solved backwards\n/// from their target index. ref:DEC-structural-size-budget\n/// ref:DEC-shrink-within-domain ref:DEC-indexed-families-as-evidence\nmodule LawSpec.Testing.Generators\n\nopen System\nopen System.Collections.Generic\nopen System.Numerics\nopen System.Runtime.CompilerServices\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Schema\n\n/// A comparison bound on an input, or on its length.\ntype Bound =\n    | Compare of op: string * value: Value\n    | Length of op: string * value: Value\n\n/// A native generator for a data type, given generators for its arguments.\ntype Factory = Gen<Value> list -> Gen<Value>\n\n/// What generation reads beyond the schema: native generator factories by\n/// type name (from lawspec.json) and the attempts budget.\ntype Context =\n    { Schema: Schema\n      Symbols: Scalar.SymbolContext\n      Factories: Map<string, Factory>\n      Attempts: int }\n\nlet private minimums = ConditionalWeakTable<Schema, Dictionary<TypeRef * int, int option>>()\n\nlet private exactBound (value: Value) =\n    let n, d = Scalar.exact value\n    let floor = BigInteger.Divide(n, d) - (if n.Sign < 0 && not (BigInteger.Remainder(n, d)).IsZero then BigInteger.One else BigInteger.Zero)\n    let ceil = floor + (if (BigInteger.Remainder(n, d)).IsZero then BigInteger.Zero else BigInteger.One)\n    floor, ceil\n\nlet private lower (lo: BigInteger option) n = Some(match lo with None -> n | Some l -> BigInteger.Max(l, n))\nlet private upper (hi: BigInteger option) n = Some(match hi with None -> n | Some h -> BigInteger.Min(h, n))\n\nlet private limit (lo, hi) (op: string, value: Value) =\n    let floor, ceil = exactBound value\n    match op with\n    | \">\" -> lower lo (floor + BigInteger.One), hi\n    | \">=\" -> lower lo ceil, hi\n    | \"<\" -> lo, upper hi (ceil - BigInteger.One)\n    | \"<=\" -> lo, upper hi floor\n    | \"==\" -> lower lo ceil, upper hi floor\n    | _ -> lo, hi\n\nlet private lengths bounds = bounds |> List.choose (function Length(op, v) -> Some(op, v) | _ -> None)\nlet private comparisons bounds = bounds |> List.choose (function Compare(op, v) -> Some(op, v) | _ -> None)\n\nlet private lengthRange bounds = lengths bounds |> List.fold limit (Some BigInteger.Zero, None)\n\nlet private lengthAllowed n bounds =\n    let lo, hi = lengthRange bounds\n    let n = BigInteger(n: int)\n    (match lo with Some l -> n >= l | None -> true) && (match hi with Some h -> n <= h | None -> true)\n\nlet private lengthGenerator bounds (size: int) =\n    match lengthRange bounds with\n    | Some lo, Some hi when lo > hi -> Gen.empty\n    | lo, hi ->\n        let lo = defaultArg lo BigInteger.Zero\n        Gen.integer (Some lo) (upper hi (BigInteger.Max(lo, BigInteger size))) |> Gen.map int\n\nlet private sequenceOf (element: Gen<'a>) bounds =\n    match lengths bounds with\n    | [] -> Gen.list element\n    | _ -> Gen.sized (fun size -> Gen.bind (lengthGenerator bounds size) (fun count -> Gen.vector count element))\n\nlet private unicodeScalar =\n    Gen.oneof [ Gen.integer (Some BigInteger.Zero) (Some(BigInteger 0xD7FF))\n                Gen.integer (Some(BigInteger 0xE000)) (Some(BigInteger 0x10FFFF)) ]\n\nlet private ieee width =\n    Gen.integer (Some BigInteger.Zero) (Some((BigInteger.One <<< width) - BigInteger.One))\n    |> Gen.map (fun bits -> Float(width, uint64 bits))\n\nlet private scalar (context: Context) (t: TypeRef) (bounds: Bound list) : Gen<Value> =\n    match t with\n    | Named(\"Bool\", []) -> Gen.oneof [ Gen.constant (Bool false); Gen.constant (Bool true) ]\n    | Named(\"Unit\", []) -> Gen.constant Unit\n    | Named(\"Null\", []) -> Gen.constant Null\n    | Named(\"Undefined\", []) -> Gen.constant Undefined\n    | Named(\"Rational\", []) ->\n        Gen.bind (Gen.integer None None) (fun n -> Gen.integer (Some BigInteger.One) None |> Gen.map (fun d -> Scalar.ratio n d))\n    | Named(\"Decimal\", []) ->\n        Gen.bind (Gen.integer None None) (fun c ->\n            Gen.sized (fun size -> Gen.range -size size |> Gen.map (fun e -> Value.Decimal(c, e))))\n    | Named(\"Float32\", []) -> ieee 32\n    | Named(\"Float64\", []) -> ieee 64\n    | Named((\"Complex64\" | \"Complex128\") as name, []) ->\n        let w = if name = \"Complex64\" then 32 else 64\n        Gen.bind (ieee w) (fun r -> ieee w |> Gen.map (fun i -> Value.Complex(w, r, i)))\n    | Named(\"Char\", []) -> unicodeScalar |> Gen.map Int\n    | Named(\"CodePoint\", []) -> Gen.integer (Some BigInteger.Zero) (Some(BigInteger 0x10FFFF)) |> Gen.map Int\n    | Named(\"CodeUnit16\", []) -> Gen.integer (Some BigInteger.Zero) (Some(BigInteger 0xFFFF)) |> Gen.map Int\n    | Named(\"Text\", []) -> sequenceOf unicodeScalar bounds |> Gen.map (List.map int >> Scalar.textOfPoints >> Text)\n    | Named(\"Bytes\", []) ->\n        sequenceOf (Gen.integer (Some BigInteger.Zero) (Some(BigInteger 255))) bounds\n        |> Gen.map (fun units -> Bytes(units |> List.map byte |> Array.ofList))\n    | Named((\"CodePointText\" | \"Utf16Text\") as name, []) ->\n        let top = if name = \"CodePointText\" then 0x10FFFF else 0xFFFF\n        sequenceOf (Gen.integer (Some BigInteger.Zero) (Some(BigInteger top))) bounds\n        |> Gen.map (fun units -> Raw(name, units |> List.map int))\n    | Named(\"Symbol\", []) ->\n        Gen.integer (Some BigInteger.Zero) None\n        |> Gen.map (fun n ->\n            let key = n.ToString()\n            Value.Symbol(context.Symbols.Identity(\"generated:\" + key), key))\n    | Named(name, []) when Scalar.isIntegerType name ->\n        let lo, hi = comparisons bounds |> List.fold limit (Scalar.bounds name context.Schema.Bits)\n        match lo, hi with\n        | Some l, Some h when l > h -> Gen.empty\n        | _ -> Gen.integer lo hi |> Gen.map Int\n    | _ -> Fail.raiseWith \"NoGenerator\" (Scalar.typeKey t)\n\n/// Whether a value is a member of its type, contracts included.\nlet accepted (value: Value) (t: TypeRef) (schema: Schema) =\n    try\n        validate value t schema |> ignore\n        true\n    with :? LawSpecException as e when e.Code = \"RefinementViolation\" -> false\n\nlet rec private valueNodes (value: Value) =\n    match value with\n    | Data(_, fields) -> 1 + (fields |> List.sumBy valueNodes)\n    | Presence(_, Some v) -> 1 + valueNodes v\n    | List items -> 1 + (items |> List.sumBy (fun v -> 1 + valueNodes v))\n    | _ -> 1\n\n/// Sets and maps are canonical: sorted and without duplicate keys, also\n/// after every shrink.\nlet private canonical (t: TypeRef) (value: Value) =\n    let distinctSorted key items =\n        items\n        |> List.sortWith (fun a b -> Scalar.compareValues (key a) (key b))\n        |> List.fold (fun acc item ->\n            match acc with\n            | last :: _ when Scalar.compareValues (key last) (key item) = 0 -> acc\n            | _ -> item :: acc) []\n        |> List.rev\n    match t, value with\n    | Named(\"lawspec.collections::type::Set\", _), Data(tag, [ List items ]) -> Data(tag, [ List(distinctSorted id items) ])\n    | Named(\"lawspec.collections::type::KeyVal\", _), Data(tag, [ List entries ]) ->\n        Data(tag, [ List(distinctSorted (function Data(_, [ k; _ ]) -> k | v -> v) entries) ])\n    | _ -> value\n\nlet private factory (context: Context) (t: TypeRef) =\n    match t with\n    | Named(name, _) -> context.Factories.TryFind name\n    | _ -> None\n\nlet rec private inhabited (context: Context) (t: TypeRef) budget =\n    if budget < 1 then false\n    else\n        match t with\n        | Named((\"List\" | \"Optional\" | \"Nullable\"), _) -> true\n        | _ when (factory context t).IsSome -> true\n        | _ ->\n            match constructors t context.Schema with\n            | None -> true\n            | Some cs ->\n                cs |> List.collect witnessInstances\n                |> List.exists (fun (c: Constructor) -> Option.isSome (allocation context c.Fields (budget - 1 - List.length c.WitnessValues)))\n\n/// The least structural cost of a type, if it is at most the limit.\nand minimum (context: Context) (t: TypeRef) (limit: int) : int option =\n    if limit < 1 then None\n    else\n        let cache = minimums.GetValue(context.Schema, fun _ -> Dictionary())\n        let key = t, limit\n        match lock cache (fun () -> match cache.TryGetValue key with | true, v -> Some v | _ -> None) with\n        | Some cost -> cost\n        | None ->\n            let cost = seq { 1 .. limit } |> Seq.tryFind (fun c -> inhabited context t c)\n            lock cache (fun () -> cache.[key] <- cost)\n            cost\n\nand private costs (context: Context) (fields: (string * TypeRef) list) (budget: int) =\n    match fields with\n    | [] -> if budget >= 0 then Some [] else None\n    | _ when budget < 1 -> None\n    | (_, t) :: rest ->\n        minimum context t budget\n        |> Option.bind (fun cost -> costs context rest (budget - cost) |> Option.map (fun more -> cost :: more))\n\n/// Each field's budget: its minimum, plus an even share of what is left.\nand allocation (context: Context) (fields: (string * TypeRef) list) (budget: int) =\n    costs context fields budget\n    |> Option.map (fun minimums ->\n        match minimums with\n        | [] -> []\n        | _ ->\n            let extra = budget - List.sum minimums\n            let count = List.length minimums\n            minimums |> List.mapi (fun i cost -> cost + extra / count + (if i < extra % count then 1 else 0)))\n\nlet private withWitnesses (native: Gen<Value>) (witnesses: Value list) = Gen.withExamples witnesses native\n\nlet rec private build (context: Context) (t: TypeRef) (budget: int) (bounds: Bound list) : Gen<Value> =\n    match factory context t with\n    | Some f -> custom context t budget bounds f\n    | None -> buildNative context t budget bounds\n\nand private custom (context: Context) (t: TypeRef) (budget: int) (bounds: Bound list) (f: Factory) =\n    let args = match t with Named(_, a) -> a | _ -> []\n    let children =\n        args\n        |> List.map (fun child ->\n            let available = max 1 (budget - 1)\n            match minimum context child available with\n            | None -> Gen.empty\n            | Some _ -> build context child available [])\n    let checkedGen = f children |> Gen.map (fun v -> validate v t context.Schema)\n    match bounds with\n    | [] -> checkedGen\n    | _ ->\n        checkedGen\n        |> Gen.refine (fun v ->\n            bounds\n            |> List.forall (function\n                | Length(op, b) -> Scalar.binary op (Scalar.helper \"length\" [ v ] [ Scalar.typeKey t ] context.Schema.Bits) b \"Integer\" \"Integer\" = Bool true\n                | Compare(op, b) -> Scalar.binary op v b (Scalar.typeKey t) (Scalar.typeKey t) = Bool true))\n\nand private buildNative (context: Context) (t: TypeRef) (budget: int) (bounds: Bound list) =\n    match t with\n    | Named(\"List\", [ element ]) ->\n        let lengthBounds = lengths bounds\n        let limitCost = if List.isEmpty lengthBounds then budget - 1 else max 64 (budget - 1)\n        match minimum context element limitCost with\n        | None -> Gen.constant (List []) |> Gen.refine (fun _ -> lengthAllowed 0 bounds)\n        | Some cost ->\n            Gen.bind (lengthGenerator bounds ((budget - 1) / cost)) (fun count ->\n                if count = 0 then Gen.constant (List [])\n                else Gen.vector count (build context element (max cost ((budget - 1) / count)) []) |> Gen.map List)\n    | Named((\"Optional\" | \"Nullable\") as kind, [ inner ]) ->\n        let absent = Gen.constant (Presence(kind, None))\n        match minimum context inner (budget - 1) with\n        | None -> absent\n        | Some _ -> Gen.oneof [ absent; build context inner (budget - 1) [] |> Gen.map (fun v -> Presence(kind, Some v)) ]\n    | _ ->\n        match constructors t context.Schema with\n        | None -> scalar context t bounds\n        | Some raw ->\n            let choices =\n                [ for c0 in raw do\n                      for c in witnessInstances c0 do\n                          match allocation context c.Fields (budget - 1 - List.length c.WitnessValues) with\n                          | Some shares -> yield constructorGen context c shares\n                          | None -> () ]\n            Gen.oneof choices\n            |> Gen.map (canonical t)\n            |> Gen.constrain context.Attempts (fun v -> accepted v t context.Schema)\n\nand private constructorGen (context: Context) (c: Constructor) (shares: int list) =\n    let rec fields (remaining: ((string * TypeRef) * int) list) (values: Value list) =\n        match remaining with\n        | [] -> Gen.constant (Data(c.Tag, values @ c.WitnessValues))\n        | ((_, ft), share) :: rest ->\n            let position = List.length values + 1\n            let hints =\n                match c.Generators.TryFind position with\n                | Some constraints -> Some(constraints context.Schema c.Arguments values)\n                | None -> None\n            let bounds, witnesses =\n                match hints with\n                | Some h -> (h.Bounds |> List.map Compare) @ (h.Lengths |> List.map Length), h.Hints\n                | None -> [], []\n            let native = build context ft share bounds\n            let g = if (factory context ft).IsSome then native else withWitnesses native witnesses\n            Gen.bind g (fun v -> fields rest (values @ [ v ]))\n    fields (List.zip c.Fields shares) []\n\n// ---------------------------------------------------------------------------\n// Indexed families\n\ntype private Term =\n    | Constant of BigInteger\n    | Field of int\n    | Op of string * Term * Term\n\nlet private tokens (text: string) = text.Split(' ', StringSplitOptions.RemoveEmptyEntries) |> List.ofArray\n\nlet rec private parse tokens =\n    match tokens with\n    | (t: string) :: rest when t.StartsWith \"c\" -> Constant(BigInteger.Parse(t.Substring 1)), rest\n    | t :: rest when t.StartsWith \"f\" -> Field(int (t.Substring 1)), rest\n    | op :: rest ->\n        let a, next = parse rest\n        let b, after = parse next\n        Op(op, a, b), after\n    | [] -> Fail.raiseWith \"InvalidIndexTerm\" \"\"\n\nlet rec private termFields term =\n    match term with\n    | Constant _ -> []\n    | Field i -> [ i ]\n    | Op(_, a, b) -> termFields a @ termFields b\n\nlet rec private evaluate term (assigned: Map<int, BigInteger>) =\n    match term with\n    | Constant n -> Some n\n    | Field i -> assigned.TryFind i\n    | Op(op, a, b) ->\n        match evaluate a assigned, evaluate b assigned with\n        | Some x, Some y ->\n            match op with\n            | \"+\" -> Some(x + y)\n            | \"-\" when x >= y -> Some(x - y)\n            | \"*\" -> Some(x * y)\n            | \"div\" when y.Sign > 0 -> Some(BigInteger.Divide(x, y))\n            | \"mod\" when y.Sign > 0 -> Some(BigInteger.Remainder(x, y))\n            | \"^\" when y.Sign >= 0 && y <= BigInteger 64 -> Some(BigInteger.Pow(x, int y))\n            | _ -> None\n        | _ -> None\n\ntype private Equation =\n    { Term: Term\n      Guards: (string * Term * Term) list\n      Positions: int list }\n\nlet private equation (texts: string list) =\n    match texts with\n    | text :: guards ->\n        let term, _ = parse (tokens text)\n        let parsed =\n            guards\n            |> List.map (fun g ->\n                match tokens g with\n                | op :: rest ->\n                    let a, next = parse rest\n                    let b, _ = parse next\n                    op, a, b\n                | [] -> Fail.raiseWith \"InvalidIndexGuard\" g)\n        let positions =\n            (termFields term @ (parsed |> List.collect (fun (_, a, b) -> termFields a @ termFields b))) |> List.distinct |> List.sort\n        { Term = term; Guards = parsed; Positions = positions }\n    | [] -> Fail.raiseWith \"InvalidIndexTerm\" \"\"\n\nlet private holds (relation, a, b) assigned =\n    match evaluate a assigned, evaluate b assigned with\n    | Some x, Some y -> if relation = \"==\" then x = y else x >= y\n    | _ -> false\n\n/// An indexed family's value whose index is the target (or, for a negative\n/// target, any of its smallest reachable indices).\nlet indexed (context: Context) (t: TypeRef) (target: BigInteger) (equations: Map<string, string list>) (budget: int) : Gen<Value> =\n    let parsed = equations |> Map.map (fun _ texts -> equation texts)\n    let positions (c: Constructor) = parsed.[c.Tag].Positions\n    let rec families pending (found: Map<TypeRef, Constructor list>) =\n        match pending with\n        | [] -> found\n        | t :: rest when found.ContainsKey t -> families rest found\n        | t :: rest ->\n            let cs =\n                match constructors t context.Schema with\n                | Some cs -> cs |> List.collect witnessInstances\n                | None -> Fail.raiseWith \"IndexedTypeRequiresData\" (Scalar.typeKey t)\n            let children = [ for c in cs do for i in positions c -> snd (List.item i c.Fields) ]\n            families (children @ rest) (found.Add(t, cs))\n    let all = families [ t ] Map.empty\n    let plain =\n        [ for KeyValue(_, cs) in all do\n              for c in cs do\n                  for i, (_, ft) in List.indexed c.Fields do\n                      if not (List.contains i (positions c)) then yield ft, minimum context ft 64 ]\n        |> Map.ofList\n    let limitIndex = int (BigInteger.Max(BigInteger.Zero, target)) + 16\n    let assignments (c: Constructor) (costs: Map<TypeRef * int, int>) =\n        let eq = parsed.[c.Tag]\n        let fields = c.Fields\n        let ok = fields |> List.indexed |> List.forall (fun (i, (_, ft)) -> List.contains i eq.Positions || (plain.[ft]).IsSome)\n        if not ok then []\n        else\n            let choices =\n                [ for i in eq.Positions ->\n                      let _, ft = List.item i fields\n                      i, (costs |> Map.toList |> List.choose (fun ((t0, k), _) -> if t0 = ft then Some k else None) |> List.sort) ]\n            let rec assign choices (assigned: Map<int, BigInteger>) =\n                let ready =\n                    eq.Guards |> List.filter (fun (_, a, b) -> (termFields a @ termFields b) |> List.forall assigned.ContainsKey)\n                if not (ready |> List.forall (fun g -> holds g assigned)) then []\n                else\n                    match choices with\n                    | [] -> [ assigned ]\n                    | (i, values) :: rest -> values |> List.collect (fun v -> assign rest (assigned.Add(i, BigInteger(v: int))))\n            [ for assigned in assign choices Map.empty do\n                  match evaluate eq.Term assigned with\n                  | Some value when value.Sign >= 0 && value <= BigInteger limitIndex ->\n                      let required =\n                          fields\n                          |> List.mapi (fun i (_, ft) ->\n                              match assigned.TryFind i with\n                              | Some k -> costs.[(ft, int k)]\n                              | None -> (plain.[ft]).Value)\n                      yield int value, assigned, required\n                  | _ -> () ]\n    let rec reach (costs: Map<TypeRef * int, int>) =\n        let next =\n            all\n            |> Map.fold (fun acc ft cs ->\n                cs\n                |> List.fold (fun table c ->\n                    assignments c costs\n                    |> List.fold (fun table (k, _, fields) ->\n                        let cost = 1 + List.length c.WitnessValues + List.sum fields\n                        match Map.tryFind (ft, k) table with\n                        | Some existing when existing <= cost -> table\n                        | _ -> Map.add (ft, k) cost table) table) acc) costs\n        if next = costs then costs else reach next\n    let costs = reach Map.empty\n    let solutions =\n        all\n        |> Map.fold (fun table ft cs ->\n            cs\n            |> List.fold (fun acc c ->\n                assignments c costs\n                |> List.fold (fun acc (k, targets, fields) ->\n                    let existing = defaultArg (Map.tryFind (ft, k) acc) []\n                    Map.add (ft, k) (existing @ [ c, targets, fields ]) acc) acc) table) Map.empty\n    let levels =\n        if target.Sign < 0 then\n            costs |> Map.toList |> List.choose (fun ((t0, k), _) -> if t0 = t then Some k else None) |> List.sort |> List.truncate 6\n        else [ int target ] |> List.filter (fun k -> costs.ContainsKey(t, k))\n    let rec generate ft k share =\n        let choices =\n            defaultArg (solutions.TryFind(ft, k)) []\n            |> List.filter (fun (c, _, fieldCosts) -> 1 + List.length c.WitnessValues + List.sum fieldCosts <= share)\n        Gen.bind (Gen.oneof (choices |> List.map Gen.constant)) (fun (c: Constructor, targets: Map<int, BigInteger>, fieldCosts: int list) ->\n            let count = List.length fieldCosts\n            let extra = share - 1 - List.length c.WitnessValues - List.sum fieldCosts\n            let children =\n                List.zip c.Fields fieldCosts\n                |> List.mapi (fun i ((_, childType), cost) ->\n                    let childShare = cost + (if count > 0 then extra / count + (if i < extra % count then 1 else 0) else 0)\n                    match targets.TryFind i with\n                    | Some index -> generate childType (int index) childShare\n                    | None -> build context childType childShare [])\n            Gen.tuple children |> Gen.map (fun values -> Data(c.Tag, values @ c.WitnessValues)))\n        |> Gen.constrain context.Attempts (fun v -> accepted v ft context.Schema)\n    match levels with\n    | [] when target.Sign < 0 -> Fail.raiseWith \"NoIndexedGenerator\" (Scalar.typeKey t)\n    | [] -> Gen.empty\n    | _ -> Gen.bind (Gen.oneof (levels |> List.map Gen.constant)) (fun k -> generate t k (max budget costs.[(t, k)]))\n\n/// A bound on an input.\nlet compareBound (op: string) (value: Value) = Compare(op, value)\n\n/// A bound on an input's length.\nlet lengthBound (op: string) (value: Value) = Length(op, value)\n\n/// No index to aim at.\nlet noIndex () : (BigInteger * Map<string, string list>) option = None\n\n/// An indexed family's target index and each constructor's index terms.\nlet index (target: Value) (tags: string list) (terms: string list list) =\n    match target with\n    | Int n -> Some(n, Map.ofList (List.zip tags terms))\n    | _ -> Fail.raiseWith \"IntegerRequired\" \"index target\"\n\n/// The generator of an input of a type: native factories first, then the\n/// type's structure within a budget that grows with the size.\nlet generator (context: Context) (t: TypeRef) (bounds: Bound list) (witnesses: Value list) (index: (BigInteger * Map<string, string list>) option) =\n    Gen.sized (fun size ->\n        match factory context t with\n        | Some f -> custom context t (size + 1) bounds f\n        | None ->\n            let limit = List.max (64 :: (witnesses |> List.map valueNodes))\n            match minimum context t limit with\n            | None -> Fail.raiseWith \"NoStructuralGenerator\" (Scalar.typeKey t)\n            | Some least ->\n                let budget = max least (size + 1)\n                match index with\n                | Some(target, equations) -> indexed context t target equations budget\n                | None -> withWitnesses (build context t budget bounds) witnesses)\n"
dotnetSource "LawSpec.Testing/Harness.fs" = "/// The harness plane on .NET: how often a law runs, how long it may take,\n/// whether its cases were adequate (cover, classify, labels), targeted\n/// search scores, known failures, skips and benchmarks. Statistics go to\n/// LAWSPEC_STATS as the same JSON records every target writes.\n/// ref:REQ-harness-units ref:DEC-never-pass-vacuously\nmodule LawSpec.Testing.Harness\n\nopen System\nopen System.Collections.Generic\nopen System.Diagnostics\nopen System.IO\nopen System.Security.Cryptography\nopen System.Text\nopen System.Text.Json\nopen System.Text.Json.Nodes\nopen System.Threading\nopen System.Threading.Tasks\nopen LawSpec.Runtime\n\n/// What one generated case observed: cover predicates, classifications,\n/// labels and a target score.\ntype Observation =\n    { Covers: Value list\n      Classes: (string * Value) list\n      Labels: Value list\n      Score: Value option }\n\ntype private State =\n    { Law: string\n      Test: string\n      mutable Failed: bool\n      mutable Cases: int\n      mutable Cover: int[]\n      Classes: SortedDictionary<string, int>\n      Labels: SortedDictionary<string, int>\n      mutable Target: bool\n      mutable Best: Value option\n      mutable Aborted: exn option\n      Extra: Dictionary<string, JsonNode> }\n\nlet private current = AsyncLocal<State option>()\n\nlet private ordinal = StringComparer.Ordinal\n\n/// Fail the harness itself (not the law): a strategy outside its input's\n/// refinement, a discard budget spent, a broken cover clause.\nlet abort (code: string) (detail: string) : 'a =\n    let failure = LawSpecException(code, detail)\n    match current.Value with\n    | Some state when state.Aborted.IsNone -> state.Aborted <- Some(failure :> exn)\n    | _ -> ()\n    raise failure\n\n/// Mark a failure as the harness's, keeping the failure itself.\nlet markHarnessFailure (failure: exn) =\n    match current.Value with\n    | Some state when state.Aborted.IsNone -> state.Aborted <- Some failure\n    | _ -> ()\n\nlet private boolean (value: Value) =\n    match value with\n    | Bool b -> b\n    | _ -> abort \"InvalidHarnessPredicate\" (sprintf \"%A\" value)\n\n/// Whether a score beats the best so far; a NaN never does.\nlet higher (score: Value) (best: Value option) =\n    match score with\n    | Float _ when Scalar.floatClass score = \"nan\" -> false\n    | Float _ ->\n        match best with\n        | None -> true\n        | Some other -> Scalar.floatCompare score other = Some 1\n    | Int _ | Ratio _ | Value.Decimal _ ->\n        match best with\n        | None -> true\n        | Some other -> Scalar.compareValues score other = 1\n    | _ -> abort \"InvalidTargetScore\" (sprintf \"%A\" score)\n\n/// A score as the reports print it.\nlet scoreText (score: Value) =\n    match score with\n    | Int n -> n.ToString()\n    | Ratio(n, d) -> n.ToString() + \"/\" + d.ToString()\n    | Value.Decimal(c, e) -> c.ToString() + \"e\" + string e\n    | Float(w, b) ->\n        match Scalar.floatClass score with\n        | \"nan\" -> \"NaN\"\n        | \"infinity\" -> if (b >>> (w - 1)) = 0UL then \"Infinity\" else \"-Infinity\"\n        | _ -> (Scalar.toDouble score).ToString(\"R\", Globalization.CultureInfo.InvariantCulture)\n    | _ -> sprintf \"%A\" score\n\nlet private observe (state: State) (o: Observation) =\n    if List.length o.Covers <> state.Cover.Length then abort \"InvalidHarnessCoverObservation\" \"\"\n    o.Covers |> List.iteri (fun i holds -> if boolean holds then state.Cover.[i] <- state.Cover.[i] + 1)\n    for label, _ in o.Classes do\n        if not (state.Classes.ContainsKey label) then state.Classes.[label] <- 0\n    for label in o.Classes |> List.filter (snd >> boolean) |> List.map fst |> List.distinct do\n        state.Classes.[label] <- state.Classes.[label] + 1\n    let labels =\n        o.Labels |> List.map (function Text s -> s | v -> abort \"InvalidHarnessLabel\" (sprintf \"%A\" v)) |> List.distinct\n    for label in labels do\n        state.Labels.[label] <- (match state.Labels.TryGetValue label with | true, n -> n | _ -> 0) + 1\n    match o.Score with\n    | None -> ()\n    | Some score ->\n        state.Target <- true\n        if higher score state.Best then state.Best <- Some score\n\n/// What a case observed.\nlet observation covers classes labels score = { Covers = covers; Classes = classes; Labels = labels; Score = score }\n\n/// One generated case: count it, record what it observed, then run it. After\n/// the first failure only the law runs (shrinking does not count cases).\nlet sample (observation: unit -> Observation) (test: unit -> Value) : Value =\n    match current.Value with\n    | None -> Fail.raiseWith \"HarnessObservationOutsideRun\" \"\"\n    | Some state when state.Failed ->\n        observation () |> ignore\n        test ()\n    | Some state ->\n        state.Cases <- state.Cases + 1\n        try\n            observe state (observation ())\n            test ()\n        with _ ->\n            state.Failed <- true\n            reraise ()\n\nlet private percentage n cases = if cases = 0 then 0.0 else Math.Round(10000.0 * float n / float cases) / 100.0\n\nlet private statsDirectory () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_STATS\" with\n    | null | \"\" -> None\n    | directory -> Some directory\n\nlet private writeRecord (identity: string) (record: JsonObject) =\n    match statsDirectory () with\n    | None -> ()\n    | Some directory ->\n        Directory.CreateDirectory directory |> ignore\n        let hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes identity))\n        let path = Path.Combine(directory, hash + \".json\")\n        let temporary = path + \".\" + string Environment.ProcessId + \".\" + Guid.NewGuid().ToString(\"N\") + \".tmp\"\n        try\n            File.WriteAllText(temporary, record.ToJsonString())\n            File.Move(temporary, path, true)\n        finally\n            if File.Exists temporary then File.Delete temporary\n\n/// The expected-failure context of a `known failing` law.\ntype private Expected =\n    { ExpectedLaw: string\n      Checks: ResizeArray<JsonObject>\n      mutable ExpectedAborted: exn option }\n\nlet private expected = AsyncLocal<Expected option>()\n\nlet private commit (record: JsonObject) =\n    let law = record.[\"law\"].GetValue<string>()\n    match expected.Value with\n    | Some e when e.ExpectedLaw = law ->\n        e.Checks.Add record\n        if record.ContainsKey \"failureKind\" && record.[\"failureKind\"].GetValue<string>() = \"harness\" && e.ExpectedAborted.IsNone then\n            e.ExpectedAborted <- Some(LawSpecException(\"HarnessFailed\", law) :> exn)\n    | _ -> writeRecord (law + \"\\u0000\" + record.[\"test\"].GetValue<string>()) record\n\nlet private node (value: obj) : JsonNode =\n    match value with\n    | :? JsonNode as n -> n\n    | :? string as s -> JsonValue.Create(s)\n    | :? int as i -> JsonValue.Create(i)\n    | :? int64 as i -> JsonValue.Create(i)\n    | :? float as f -> JsonValue.Create(f)\n    | :? bool as b -> JsonValue.Create(b)\n    | null -> null\n    | other -> JsonValue.Create(string other)\n\nlet private objectOf (fields: (string * obj) list) =\n    let o = JsonObject()\n    for k, v in fields do\n        o.[k] <- node v\n    o\n\ntype private CoverRow =\n    { Label: string\n      Required: int\n      Observed: float\n      Hits: int\n      Cases: int\n      Met: bool }\n\nlet private coverRows (covers: (int * string) list) (state: State) =\n    List.zip covers (List.ofArray state.Cover)\n    |> List.map (fun ((percent, label), n) ->\n        { Label = label\n          Required = percent\n          Observed = percentage n state.Cases\n          Hits = n\n          Cases = state.Cases\n          Met = state.Cases > 0 && 100 * n >= percent * state.Cases })\n\nlet private reportText (state: State) (rows: CoverRow list) =\n    let text = StringBuilder()\n    let line (s: string) = text.Append(s).Append('\\n') |> ignore\n    line (sprintf \"%s: %d generated case(s)\" state.Law state.Cases)\n    for row in rows do\n        let shortfall = if row.Met then \"\" else sprintf \" (not met; %d/%d cases)\" row.Hits row.Cases\n        line (sprintf \"  cover %d%% \\\"%s\\\": %.2f%%%s\" row.Required row.Label row.Observed shortfall)\n    for KeyValue(label, n) in state.Classes do\n        line (sprintf \"  %s: %.2f%%\" label (percentage n state.Cases))\n    for KeyValue(label, n) in state.Labels do\n        line (sprintf \"  label %s: %.2f%%\" label (percentage n state.Cases))\n    match state.Target, state.Best with\n    | true, Some best -> line (\"  best target score: \" + scoreText best)\n    | _ -> ()\n    text.ToString()\n\nlet private report (state: State) (rows: CoverRow list) =\n    let cover = JsonArray()\n    for row in rows do\n        cover.Add(objectOf [ \"label\", box row.Label; \"required\", box row.Required; \"observed\", box row.Observed\n                             \"hits\", box row.Hits; \"cases\", box row.Cases; \"met\", box row.Met ])\n    let classes = JsonObject()\n    for KeyValue(k, v) in state.Classes do classes.[k] <- JsonValue.Create(v)\n    let labels = JsonObject()\n    for KeyValue(k, v) in state.Labels do labels.[k] <- JsonValue.Create(v)\n    let o =\n        objectOf [ \"law\", box state.Law; \"test\", box state.Test; \"attempts\", box 1; \"cases\", box state.Cases\n                   \"cover\", box cover; \"classes\", box classes; \"labels\", box labels ]\n    if state.Target then\n        o.[\"target\"] <- objectOf [ \"best\", (match state.Best with Some b -> box (scoreText b) | None -> null) ]\n    for KeyValue(k, v) in state.Extra do\n        o.[k] <- v.DeepClone()\n    o\n\n/// Options of a controlled run.\ntype Options =\n    { Repeat: int\n      Retries: int\n      Timeout: int option\n      Resources: bool\n      Observed: bool }\n\nlet defaults = { Repeat = 1; Retries = 0; Timeout = None; Resources = false; Observed = true }\n\n/// A controlled run's options.\nlet options (repeat: int) (retries: int) (timeout: int option) (resources: bool) (observed: bool) =\n    { Repeat = repeat; Retries = retries; Timeout = timeout; Resources = resources; Observed = observed }\n\nlet private execute (law: string) (options: Options) (test: unit -> unit) : exn option =\n    match options.Timeout with\n    | None ->\n        try\n            test ()\n            None\n        with e -> Some e\n    | Some ms ->\n        let state = current.Value\n        let work = Task.Run(fun () ->\n            current.Value <- state\n            test ())\n        let finished = try work.Wait(ms) with _ -> true\n        if not finished then\n            let failure = LawSpecException(\"TestTimeout\", sprintf \"%s did not finish within %d ms\" law ms)\n            markHarnessFailure failure\n            Some(failure :> exn)\n        elif work.IsFaulted then\n            Some(match work.Exception.InnerExceptions.Count with\n                 | 1 -> work.Exception.InnerExceptions.[0]\n                 | _ -> work.Exception :> exn)\n        else None\n\n/// Run a test under the harness: each repeat is a complete check with its\n/// own counters, and a retry starts the repeats again. Coverage is never\n/// pooled across runs.\nlet run (law: string) (name: string) (covers: (int * string) list) (options: Options) (test: unit -> unit) =\n    let previous = current.Value\n    try\n        let rec attempts (attempt: int) (history: JsonObject list) =\n            let rec repeats (repetition: int) (runs: JsonObject list) =\n                let state =\n                    { Law = law; Test = name; Failed = false; Cases = 0; Cover = Array.zeroCreate covers.Length\n                      Classes = SortedDictionary(ordinal); Labels = SortedDictionary(ordinal); Target = false\n                      Best = None; Aborted = None; Extra = Dictionary() }\n                current.Value <- Some state\n                let failure = execute law options test\n                let rows = coverRows covers state\n                let unmet = rows |> List.filter (fun r -> not r.Met)\n                let reportObject = if options.Observed then report state rows else objectOf [ \"law\", box law; \"test\", box name ]\n                let text = if options.Observed then reportText state rows else \"\"\n                if options.Observed then Console.Out.Write text\n                let outcome, retryable =\n                    match failure, state.Aborted, unmet with\n                    | None, Some cause, _ -> Some cause, false\n                    | None, None, _ :: _ ->\n                        Some(LawSpecException(\"HarnessFailed\", law + \": UnmetCover\\n\" + text) :> exn), false\n                    | Some e, Some _, _ -> Some e, false\n                    | Some e, None, _ ->\n                        (if options.Observed && not (List.isEmpty covers) then\n                             Some(LawSpecException(\"PropertyFailed\", e.Message + \"\\n\" + text, [], e) :> exn)\n                         else Some e), true\n                    | None, None, [] -> None, true\n                let run = reportObject.DeepClone().AsObject()\n                run.Remove \"law\" |> ignore\n                run.Remove \"test\" |> ignore\n                run.Remove \"attempts\" |> ignore\n                run.[\"attempt\"] <- JsonValue.Create(attempt)\n                run.[\"repetition\"] <- JsonValue.Create(repetition)\n                run.[\"outcome\"] <- JsonValue.Create(if outcome.IsNone then \"passed\" else \"failed\")\n                let runs = run :: runs\n                match outcome with\n                | None when repetition < options.Repeat -> repeats (repetition + 1) runs\n                | _ -> outcome, retryable, reportObject, runs\n            let outcome, retryable, reportObject, runs = repeats 1 history\n            match outcome with\n            | Some _ when retryable && attempt <= options.Retries -> attempts (attempt + 1) runs\n            | _ ->\n                let status =\n                    match outcome with\n                    | None when attempt > 1 -> \"flaky\"\n                    | None -> \"passed\"\n                    | Some _ -> \"failed\"\n                reportObject.[\"outcome\"] <- JsonValue.Create(status)\n                reportObject.[\"attempts\"] <- JsonValue.Create(attempt)\n                if not retryable then reportObject.[\"failureKind\"] <- JsonValue.Create(\"harness\")\n                if options.Repeat <> 1 || options.Retries <> 0 then\n                    reportObject.[\"repeat\"] <- JsonValue.Create(options.Repeat)\n                    let array = JsonArray()\n                    for r in List.rev runs do array.Add(r)\n                    reportObject.[\"runs\"] <- array\n                match outcome with\n                | None ->\n                    commit reportObject\n                    if status = \"flaky\" then printfn \"%s is flaky: it failed, then passed on attempt %d\" law attempt\n                | Some e ->\n                    (try commit reportObject with r -> eprintfn \"LawSpec statistics failed for %s: %s\" law r.Message)\n                    raise e\n        attempts 1 []\n    finally\n        current.Value <- previous\n\n/// Record extra fields (a search's report) in the running test's record.\nlet record (fields: (string * JsonNode) list) =\n    match current.Value with\n    | Some state -> for k, v in fields do state.Extra.[k] <- v\n    | None -> ()\n\n/// A skipped law, recorded and reported.\nlet skip (law: string) (reason: string) =\n    eprintfn \"SKIPPED %s: %s\" law reason\n    commit (objectOf [ \"law\", box law; \"test\", box (law + \" skipped\"); \"outcome\", box \"skipped\"; \"reason\", box reason ])\n\n/// A law known to fail: its checks must fail, and a law that passes fails\n/// the run so the mark is removed.\nlet knownFailing (law: string) (name: string) (reason: string) (checks: (unit -> unit) list) =\n    let previous = expected.Value\n    let context = { ExpectedLaw = law; Checks = ResizeArray(); ExpectedAborted = None }\n    expected.Value <- Some context\n    let failure =\n        try\n            try\n                for check in checks do check ()\n                None\n            with e -> Some e\n        finally\n            expected.Value <- previous\n    let reports = JsonArray()\n    for c in context.Checks do reports.Add(c)\n    let record outcome extra =\n        let o = objectOf ([ \"law\", box law; \"test\", box name; \"reason\", box reason; \"outcome\", box outcome ] @ extra)\n        o.[\"checks\"] <- reports\n        commit o\n    match failure, context.ExpectedAborted with\n    | None, None ->\n        record \"known-failing-passed\" []\n        eprintfn \"%s is marked known failing (%s), but it passes; remove `known failing` from its harness\" law reason\n        Fail.raiseWith \"KnownFailingPassed\" (law + \" is marked known failing (\" + reason + \"), but it passes; remove `known failing` from its harness\")\n    | Some e, None ->\n        record \"known-failing\" [ \"failure\", box e.Message ]\n        printfn \"%s is known to fail (%s): %s\" law reason e.Message\n    | Some e, Some _ ->\n        record \"failed\" [ \"failureKind\", box \"harness\"; \"failure\", box e.Message ]\n        raise e\n    | None, Some cause ->\n        record \"failed\" [ \"failureKind\", box \"harness\" ]\n        raise cause\n\n/// Measure a body: at least three iterations, about 200 ms, at most 100,000.\nlet benchmark (unitName: string) (name: string) (body: unit -> unit) =\n    let started = Stopwatch.GetTimestamp()\n    let ticks = Stopwatch.Frequency\n    let toNs (t: int64) = t * 1_000_000_000L / ticks\n    let mutable count = 0L\n    let mutable total = 0L\n    let mutable fastest = Int64.MaxValue\n    let mutable go = true\n    while go && count < 100000L do\n        let before = Stopwatch.GetTimestamp()\n        if count >= 3L && toNs (before - started) >= 200_000_000L then go <- false\n        else\n            body ()\n            let elapsed = toNs (Stopwatch.GetTimestamp() - before)\n            fastest <- min fastest elapsed\n            total <- total + elapsed\n            count <- count + 1L\n    let mean = total / count\n    writeRecord (\"benchmark\\u0000\" + unitName + \"\\u0000\" + name)\n        (objectOf [ \"benchmark\", box name; \"unit\", box unitName; \"iterations\", box count; \"mean_ns\", box mean; \"min_ns\", box fastest ])\n    printfn \"benchmark %s: %d iteration(s), mean %.2f us, fastest %.2f us\" name count (float mean / 1000.0) (float fastest / 1000.0)\n\n/// Record that a parallel unit ran.\nlet recordParallel (unitName: string) (fields: (string * obj) list) =\n    writeRecord (\"parallel\\u0000\" + unitName) (objectOf ((\"parallel\", box unitName) :: fields))\n"
dotnetSource "LawSpec.Testing/History.fs" = "/// Scenario histories carry vector clocks through sends, receives and\n/// fork/join. Consistency depends on these message edges as well as each\n/// caller's own order; real time is required only for linearizability.\n/// ref:DEC-sessions-by-construction ref:DEC-stateful-models-linearizability\n/// ref:wing-gong-linearizability\nmodule LawSpec.Testing.History\n\nopen System.Numerics\nopen LawSpec.Runtime\n\n/// A completed call: the model command it ran, its arguments and result, its\n/// interval on the shared clock, its process and its vector clocks.\ntype Event =\n    { Command: int\n      Arguments: Value list\n      Result: Value\n      Called: int64\n      Returned: int64\n      Process: string\n      CallClock: Map<string, int64>\n      ReturnClock: Map<string, int64> }\n\n/// Whether a's return happened before b's call, by their vector clocks.\n[<CompiledName(\"HappenedBefore\")>]\nlet happenedBefore (a: Event) (b: Event) =\n    a.ReturnClock |> Map.forall (fun proc count -> defaultArg (b.CallClock.TryFind proc) 0L >= count)\n\nlet private before mode (a: Event) (b: Event) =\n    if mode = \"linearizable\" then a.Returned < b.Called else happenedBefore a b\n\nlet private mask (indices: int seq) = indices |> Seq.fold (fun bits i -> bits ||| (BigInteger.One <<< i)) BigInteger.Zero\n\nlet private bit i = BigInteger.One <<< i\n\nlet private search\n    (model: Model.Model)\n    (context: Model.Context)\n    (history: Event[])\n    (preds: BigInteger[])\n    (members: int list)\n    (checkedBits: BigInteger)\n    (expected: Value)\n    (judge: Value -> bool)\n    =\n    let full = mask members\n    let seen = System.Collections.Generic.HashSet<BigInteger * Value>(HashIdentity.Structural)\n    let rec visit (dbits: BigInteger) (state: Value) =\n        if dbits = full then judge state\n        elif not (seen.Add((dbits, state))) then false\n        else\n            members\n            |> List.exists (fun i ->\n                let b = bit i\n                let dependencies = preds.[i] &&& full\n                let available = (dbits &&& b).IsZero && (dependencies &&& dbits) = dependencies\n                if not available then false\n                else\n                    let e = history.[i]\n                    let c = Model.command model e.Command\n                    match Model.step c context e.Arguments state with\n                    | None -> false\n                    | Some(next, wanted) ->\n                        let ignore = (checkedBits &&& b).IsZero || c.ReturnsUnit\n                        if ignore || Scalar.equal e.Result wanted then visit (dbits ||| b) next else false)\n    visit BigInteger.Zero expected\n\n/// Whether a history has an order consistent with the model: real time for\n/// linearizability, message order otherwise; causal histories are checked\n/// in each process's view. Final is the system's abstract final state, if any.\n[<CompiledName(\"Consistent\")>]\nlet consistent (model: Model.Model) (context: Model.Context) (events: Event list) (expected: Value) (final: Value option) (system: obj) =\n    let history = Array.ofList events\n    let indices = [ 0 .. history.Length - 1 ]\n    let mode = model.Consistency\n    let preds =\n        [| for i in indices -> mask [ for j in indices do if j <> i && before mode history.[j] history.[i] then yield j ] |]\n    let judge compareFinal (state: Value) =\n        try\n            let equal =\n                match compareFinal, final with\n                | true, Some actual -> Scalar.equal actual state\n                | _ -> true\n            equal\n            && (Model.checkState (Model.withoutAbstraction model) context system state\n                true)\n        with _ -> false\n    if mode = \"causal\" then\n        let processes = events |> List.map (fun e -> e.Process) |> List.distinct |> List.sort\n        match processes with\n        | [] -> judge false expected\n        | _ ->\n            processes\n            |> List.forall (fun proc ->\n                let own = indices |> List.filter (fun i -> history.[i].Process = proc)\n                let visible =\n                    own @ [ for j in indices do\n                                for i in own do\n                                    if j <> i && happenedBefore history.[j] history.[i] then yield j ]\n                    |> List.distinct |> List.sort\n                search model context history preds visible (mask own) expected (judge false))\n    else\n        let checkedBits = if mode = \"eventual\" then BigInteger.Zero else mask indices\n        search model context history preds indices checkedBits expected (judge true)\n"
dotnetSource "LawSpec.Testing/LawSpec.Testing.fsproj" = "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <!-- Generated by LawSpec. Do not edit. LawSpec's property engine and harness. -->\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n    <TreatWarningsAsErrors>true</TreatWarningsAsErrors>\n    <IsPackable>false</IsPackable>\n  </PropertyGroup>\n  <ItemGroup>\n    <Compile Include=\"Gen.fs\" />\n    <Compile Include=\"Generators.fs\" />\n    <Compile Include=\"Harness.fs\" />\n    <Compile Include=\"Property.fs\" />\n    <Compile Include=\"CryptoVectors.fs\" />\n    <Compile Include=\"Model.fs\" />\n    <Compile Include=\"History.fs\" />\n    <Compile Include=\"ModelParallel.fs\" />\n    <Compile Include=\"Search.fs\" />\n    <Compile Include=\"Schedule.fs\" />\n    <Compile Include=\"Supervision.fs\" />\n    <Compile Include=\"Resources.fs\" />\n  </ItemGroup>\n  <ItemGroup>\n    <ProjectReference Include=\"../LawSpec.Runtime/LawSpec.Runtime.fsproj\" />\n    <PackageReference Include=\"xunit.v3.extensibility.core\" Version=\"4.0.2\" />\n  </ItemGroup>\n</Project>\n"
dotnetSource "LawSpec.Testing/Model.fs" = "/// Portable stateful model runs over checked logical callbacks. A fresh\n/// context owns each generation, replay and shrink attempt, so no handler\n/// state or workflow state is shared between attempts. The draws, the\n/// rejected reference steps, the crash injection of actor models and the\n/// shrink order are those of every other runtime, so one seed replays one\n/// run on every target. ref:DEC-stateful-models-linearizability\n/// ref:DEC-portable-seeded-generation ref:DEC-shrink-within-domain\nmodule LawSpec.Testing.Model\n\nopen System\nopen System.Numerics\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Descriptors\n\n/// What a callback runs with: the schema, with the model's production\n/// handlers in scope, and the case's symbols.\ntype CallbackContext = Schema.Schema * Scalar.SymbolContext\n\n/// A checked entry of the program: the case's context and its arguments.\ntype Callback = CallbackContext -> Value list -> Value\n\n/// Runs a body in a fresh case context: generated code makes a symbol\n/// context, takes the program's schema and installs production handlers\n/// (Effects.withScope) around the body.\ntype ContextFactory = (CallbackContext -> obj) -> obj\n\n/// What an actor model needs from the actor runtime (LawSpec.Runtime.Actors):\n/// a supervised actor holding the system's state, restarted after a crash.\ntype IActorHost =\n    /// Start one permanent child under a one-for-one supervisor that allows\n    /// the given number of restarts, run the body with the child, then stop.\n    /// start makes the first state; restart makes a state from the state at\n    /// the crash.\n    abstract WithActor: restarts: int * start: (unit -> Value) * restart: (Value -> Value) * body: (obj -> 'r) -> 'r\n    /// Run an update on the actor's state in the actor: its reply and next state.\n    abstract Call: actor: obj * update: (Value -> Value * Value) -> Value\n    /// Crash the actor, waiting until its supervisor has restarted it.\n    abstract Crash: actor: obj -> unit\n    /// The actor's current state.\n    abstract State: actor: obj -> Value\n\ntype StepKind =\n    | Command\n    | Crash\n\n/// A command of the model (or the injected crash of an actor model).\ntype Step =\n    { Name: string\n      Arguments: Descriptor list\n      StatePosition: int\n      ReturnsUnit: bool\n      Needs: (string * BigInteger) list\n      Shifts: (string * BigInteger) list\n      Key: int option\n      Restart: bool\n      Kind: StepKind\n      Run: Callback\n      Reference: Callback\n      When: Callback option }\n\ntype Model =\n    { Name: string\n      Shared: bool\n      Actor: bool\n      Table: Map<string, Descriptor>\n      StartArguments: Descriptor list\n      StartIndices: BigInteger list\n      StartRun: Callback\n      StartModel: Callback\n      Commands: Step[]\n      Steps: Step[]\n      RestartStep: Step option\n      Abstract: Callback option\n      Invariants: (string * Callback) list\n      PerKey: bool\n      Consistency: string\n      Context: ContextFactory\n      Actors: IActorHost option }\n\n/// A case of the run: the model's context, its start arguments and the model.\ntype Context =\n    { Value: CallbackContext\n      Start: Value list\n      Model: Model }\n\n/// A run: start arguments, and each step's index and arguments.\ntype Run = Value list * (int * Value list) list\n\n/// Why a run failed, and at which step (0 before the first).\ntype Failure = { Step: int; Reason: string }\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\nlet private require condition code = if not condition then fail code \"\"\n\nlet private noCallback: Callback = fun _ _ -> fail \"ModelMissingCallback\" \"\"\n\nlet private atom d =\n    match d with\n    | Atom a -> a\n    | Quoted q -> q\n    | Number n -> n.ToString()\n    | _ -> fail \"InvalidModelSpec\" (sprintf \"%A\" d)\n\nlet private fields (forms: Descriptor list) =\n    forms\n    |> List.choose (function\n        | Forms(Atom k :: vs) -> Some(k, vs)\n        | _ -> None)\n    |> Map.ofList\n\nlet private one key (f: Map<string, Descriptor list>) =\n    match f.TryFind key with\n    | Some [ v ] -> v\n    | _ -> fail \"InvalidModelSpec\" key\n\nlet private flag key (forms: Descriptor list) = forms |> List.contains (Forms [ Atom key; Atom \"true\" ])\n\nlet private form key (forms: Descriptor list) =\n    forms\n    |> List.pick (function\n        | Forms(Atom k :: rest) when k = key -> Some rest\n        | _ -> None)\n\nlet private pairs (ds: Descriptor list) =\n    ds\n    |> List.map (function\n        | Forms [ Atom k; Number n ] -> k, n\n        | d -> fail \"InvalidModelSpec\" (sprintf \"%A\" d))\n\nlet private readCommand (forms: Descriptor list) (run: Callback, reference: Callback, ``when``: Callback option) =\n    match forms with\n    | Atom \"command\" :: name :: rest ->\n        let f = fields rest\n        { Name = atom name\n          Arguments = defaultArg (f.TryFind \"arguments\") []\n          StatePosition =\n            (match one \"state\" f with\n             | Number n -> int n\n             | d -> fail \"InvalidModelSpec\" (sprintf \"%A\" d))\n          ReturnsUnit = atom (one \"unit\" f) = \"true\"\n          Needs = pairs (defaultArg (f.TryFind \"needs\") [])\n          Shifts = pairs (defaultArg (f.TryFind \"shifts\") [])\n          Key =\n            (match one \"key\" f with\n             | Number n -> Some(int n)\n             | _ -> None)\n          Restart = atom (one \"restart\" f) = \"true\"\n          Kind = Command\n          Run = run\n          Reference = reference\n          When = ``when`` }\n    | _ -> fail \"InvalidModelSpec\" \"command\"\n\nlet private defaultContext: ContextFactory =\n    fun body -> body (Schema.create [] [] 64, Scalar.SymbolContext())\n\n/// A model from its spec text (LawSpec.MachineSpec), its start entries (the\n/// system's and the reference's), each command's run, reference and optional\n/// precondition, its optional abstraction and its invariants.\n[<CompiledName(\"Create\")>]\nlet create\n    (spec: string)\n    (startRun: Callback, startModel: Callback)\n    (callbacks: (Callback * Callback * Callback option) list)\n    (abstractRun: Callback option)\n    (invariants: Callback list)\n    : Model =\n    let forms = read spec\n    let name, sharing =\n        match List.head forms with\n        | Forms [ Atom \"machine\"; name; sharing ] -> atom name, atom sharing\n        | _ -> fail \"InvalidModelSpec\" \"machine\"\n    let start = fields (form \"start\" forms)\n    let commandForms = forms |> List.choose (function Forms(Atom \"command\" :: _ as f) -> Some f | _ -> None)\n    let kinds = form \"invariants\" forms |> List.map atom\n    require (List.length commandForms = List.length callbacks) \"ModelCommandCallbacks\"\n    require (List.length kinds = List.length invariants) \"ModelInvariantCallbacks\"\n    let all = List.map2 readCommand commandForms callbacks\n    let restarts = all |> List.filter (fun c -> c.Restart)\n    require (List.length restarts <= 1) \"ModelRestartCallbacks\"\n    let commands = all |> List.filter (fun c -> not c.Restart) |> Array.ofList\n    let actor = flag \"actor\" forms\n    let consistency = atom (List.head (form \"consistency\" forms))\n    require (sharing = \"linear\" || sharing = \"shared\") \"ModelInvalidSharing\"\n    require (List.contains consistency [ \"linearizable\"; \"sequential\"; \"causal\"; \"eventual\" ]) \"ModelInvalidConsistency\"\n    require (consistency <> \"eventual\" || abstractRun.IsSome) \"ModelEventualRequiresAbstraction\"\n    require (not actor || sharing = \"shared\") \"ModelActorMustBeShared\"\n    require (actor || List.isEmpty restarts) \"ModelRestartRequiresActor\"\n    let crash =\n        { Name = \"crash\"; Arguments = []; StatePosition = 0; ReturnsUnit = true; Needs = []; Shifts = []; Key = None\n          Restart = false; Kind = Crash; Run = noCallback; Reference = noCallback; When = None }\n    { Name = name\n      Shared = (sharing = \"shared\")\n      Actor = actor\n      Table =\n        forms\n        |> List.choose (function\n            | Forms(Atom \"data\" :: n :: _) as d -> Some(atom n, d)\n            | _ -> None)\n        |> Map.ofList\n      StartArguments = defaultArg (start.TryFind \"arguments\") []\n      StartIndices = defaultArg (start.TryFind \"indices\") [] |> List.map (function Number n -> n | d -> fail \"InvalidModelSpec\" (sprintf \"%A\" d))\n      StartRun = startRun\n      StartModel = startModel\n      Commands = commands\n      Steps = Array.append commands (if actor then [| crash |] else [||])\n      RestartStep = List.tryHead restarts\n      Abstract = abstractRun\n      Invariants = List.zip kinds invariants\n      PerKey = flag \"perkey\" forms\n      Consistency = consistency\n      Context = defaultContext\n      Actors = None }\n\n/// The model with the context factory generated code supplies.\n[<CompiledName(\"WithContext\")>]\nlet withContextFactory (factory: ContextFactory) (model: Model) = { model with Context = factory }\n\n/// The model with the actor runtime an actor model runs its system on.\n[<CompiledName(\"WithActors\")>]\nlet withActors (host: IActorHost) (model: Model) = { model with Actors = Some host }\n\n/// A context factory: fresh symbols, the program's schema, and the given\n/// handler factories installed in a scope of their own around each body.\n[<CompiledName(\"Context\")>]\nlet context (schema: Schema.Schema) (factories: (string * (Schema.Schema -> Effects.Handler)) list) : ContextFactory =\n    fun body ->\n        let symbols = Scalar.SymbolContext()\n        if List.isEmpty factories then body (schema, symbols)\n        else Effects.withScope schema factories (fun scoped -> body (scoped, symbols))\n\n/// The step at an index (commands, then the injected crash).\n[<CompiledName(\"Command\")>]\nlet command (model: Model) (index: int) =\n    if index < 0 || index >= model.Steps.Length then fail \"ModelInvalidStep\" (string index)\n    model.Steps.[index]\n\nlet private zipShort a b = Seq.zip a b |> List.ofSeq\n\n/// Whether a command's index preconditions admit the current indices.\n[<CompiledName(\"Admits\")>]\nlet admits (step: Step) (indices: BigInteger list) =\n    zipShort step.Needs indices\n    |> List.forall (fun ((kind, n), i) -> if kind = \"atleast\" then i >= n else i = n)\n\n/// The indices after a command.\n[<CompiledName(\"Shifted\")>]\nlet shifted (step: Step) (indices: BigInteger list) =\n    if List.isEmpty step.Shifts then indices\n    else zipShort step.Shifts indices |> List.map (fun ((kind, n), i) -> if kind = \"by\" then i + n else n)\n\n/// Run a body in a fresh case context.\n[<CompiledName(\"WithCaseContext\")>]\nlet withCase (model: Model) (startArgs: Value list) (body: Context -> 'a) : 'a =\n    model.Context(fun value -> box (body { Value = value; Start = startArgs; Model = model })) |> unbox<'a>\n\nlet callback (f: Callback) (context: Context) (arguments: Value list) = f context.Value arguments\n\nlet initial (model: Model) (context: Context) = callback model.StartModel context context.Start\n\n/// The reference's step: the next model state and the reply, or None when\n/// the reference rejects it. An invalid reference removes a candidate; it\n/// never turns the implementation's exception into a pass.\n[<CompiledName(\"Step\")>]\nlet step (s: Step) (context: Context) (args: Value list) (state: Value) : (Value * Value) option =\n    try\n        match s.Kind with\n        | Crash ->\n            let next =\n                match context.Model.RestartStep with\n                | None -> initial context.Model context\n                | Some r -> callback r.Reference context [ state ]\n            Some(next, Unit)\n        | Command ->\n            let allowed =\n                match s.When with\n                | None -> true\n                | Some w -> callback w context [ state ] = Bool true\n            if not allowed then None\n            else\n                let out = callback s.Reference context (args @ [ state ])\n                if s.ReturnsUnit then Some(out, Unit)\n                else\n                    match out with\n                    | Data(_, [ reply; next ]) -> Some(next, reply)\n                    | _ -> None\n    with _ -> None\n\n/// The model states a run passes through, or None when the reference\n/// rejects it.\n[<CompiledName(\"Simulate\")>]\nlet simulate (model: Model) ((startArgs, steps): Run) : Value list option =\n    withCase model startArgs (fun context ->\n        try\n            let rec go steps indices state states =\n                match steps with\n                | [] -> Some(List.rev (state :: states))\n                | (i, args) :: rest ->\n                    let c = command model i\n                    if not (admits c indices) then None\n                    else\n                        match step c context args state with\n                        | None -> None\n                        | Some(next, _) -> go rest (shifted c indices) next (state :: states)\n            go steps model.StartIndices (initial model context) []\n        with _ -> None)\n\nlet private arguments (model: Model) (ds: Descriptor list) (random: Random.Seed) (size: int) =\n    let mutable r = random\n    let values =\n        ds\n        |> List.map (fun d ->\n            let v, next = generate d model.Table r size\n            r <- next\n            v)\n    values, r\n\n/// A run drawn from a random state, of at most a length, at a size; crashes\n/// are injected (one step in eight) only when asked, and only for actors.\n[<CompiledName(\"Generate\")>]\nlet generateRun (model: Model) (random: Random.Seed) (length: int) (size: int) (crashes: bool) : Run * Random.Seed =\n    let startArgs, r1 = arguments model model.StartArguments random size\n    withCase model startArgs (fun context ->\n        let started = try Some(initial model context) with _ -> None\n        match started with\n        | None -> (startArgs, []), r1\n        | Some state ->\n            let rec go random remaining indices state steps =\n                if remaining = 0 then List.rev steps, random\n                else\n                    let allowed =\n                        model.Commands |> Array.indexed |> Array.filter (fun (_, c) -> admits c indices) |> Array.map fst\n                    if allowed.Length = 0 then List.rev steps, random\n                    else\n                        let choice, r1 = Random.below (BigInteger allowed.Length) random\n                        let index, r2 =\n                            if crashes && model.Actor then\n                                let crash, r = Random.below (BigInteger 8) r1\n                                (if crash.IsZero then model.Commands.Length else allowed.[int choice]), r\n                            else allowed.[int choice], r1\n                        let c = command model index\n                        let args, r3 = arguments model c.Arguments r2 size\n                        match step c context args state with\n                        | None -> go r3 (remaining - 1) indices state steps\n                        | Some(next, _) -> go r3 (remaining - 1) (shifted c indices) next ((index, args) :: steps)\n            let steps, last = go r1 length model.StartIndices state []\n            (startArgs, steps), last)\n\nlet private hostOf (model: Model) =\n    match model.Actors with\n    | Some host -> host\n    | None -> fail \"ModelActorRuntimeMissing\" model.Name\n\n/// Run a body with the system started (an actor model's under a\n/// supervisor), its context and the reference's initial state.\n[<CompiledName(\"WithSystem\")>]\nlet withSystem (model: Model) (startArgs: Value list) (restarts: int) (body: Context -> obj -> Value -> 'a) : 'a =\n    withCase model startArgs (fun context ->\n        let start () = callback model.StartRun context startArgs\n        if not model.Actor then body context (box (start ())) (initial model context)\n        else\n            let restart state =\n                match model.RestartStep with\n                | None -> start ()\n                | Some r -> callback r.Run context [ state ]\n            (hostOf model).WithActor(restarts, start, restart, fun actor -> body context actor (initial model context)))\n\nlet private insertState (s: Step) (args: Value list) (state: Value) =\n    let before, after = List.splitAt s.StatePosition args\n    before @ [ state ] @ after\n\nlet private pair (out: Value) =\n    match out with\n    | Data(_, [ reply; next ]) -> reply, next\n    | _ -> fail \"ModelInvalidReply\" (sprintf \"%A\" out)\n\n/// Run a step on the system: its reply and the system after it.\n[<CompiledName(\"Invoke\")>]\nlet invoke (model: Model) (context: Context) (s: Step) (args: Value list) (system: obj) : Value * obj =\n    match s.Kind with\n    | Crash ->\n        (hostOf model).Crash system\n        Unit, system\n    | Command when model.Actor ->\n        let reply =\n            (hostOf model).Call(system, fun state ->\n                let out = callback s.Run context (insertState s args state)\n                if s.ReturnsUnit then Unit, out else pair out)\n        reply, system\n    | Command ->\n        let state = unbox<Value> system\n        let out = callback s.Run context (insertState s args state)\n        match model.Shared, s.ReturnsUnit with\n        | true, _ -> out, system\n        | false, true ->\n            match out with\n            | Data(_, [ next ]) -> Unit, box next\n            | _ -> fail \"ModelInvalidReply\" (sprintf \"%A\" out)\n        | false, false ->\n            let reply, next = pair out\n            reply, box next\n\nexception private ModelFailure of string\n\n/// The system's state, as its abstraction and state invariants see it.\n[<CompiledName(\"SystemState\")>]\nlet systemState (model: Model) (system: obj) =\n    if model.Actor then (hostOf model).State system else unbox<Value> system\n\n/// Check the system against the reference state: its abstraction, then the\n/// invariants on the model state and on the system state.\n[<CompiledName(\"CheckState\")>]\nlet checkState (model: Model) (context: Context) (system: obj) (expected: Value) =\n    let state = systemState model system\n    match model.Abstract with\n    | None -> ()\n    | Some a ->\n        let actual = callback a context [ state ]\n        if not (Scalar.equal actual expected) then\n            raise (ModelFailure(sprintf \"state %s, expected %s\" (render actual) (render expected)))\n    for kind, invariant in model.Invariants do\n        let value = if kind = \"model\" then expected else state\n        match callback invariant context [ value ] with\n        | Bool true -> ()\n        | Bool false -> raise (ModelFailure(\"invariant on the \" + kind + \" failed\"))\n        | other -> raise (ModelFailure(sprintf \"invariant on the %s gave %s\" kind (render other)))\n\n/// A model without its abstraction (for the checks of each order).\nlet withoutAbstraction (model: Model) = { model with Abstract = None }\n\nlet private raised (e: exn) =\n    match e with\n    | ModelFailure reason -> reason\n    | _ -> \"raised \" + e.GetType().Name + \": \" + e.Message\n\n/// Run a run on the system, checking each reply and state.\n[<CompiledName(\"Execute\")>]\nlet execute (model: Model) ((startArgs, steps): Run) : Result<unit, Failure> =\n    try\n        withSystem model startArgs (List.length steps) (fun context system expected ->\n            let rec go steps indices system expected n =\n                try\n                    checkState model context system expected\n                    match steps with\n                    | [] -> Ok()\n                    | (i, args) :: rest ->\n                        let c = command model i\n                        if not (admits c indices) then Error { Step = n + 1; Reason = \"invalid step\" }\n                        else\n                            match step c context args expected with\n                            | None -> Error { Step = n + 1; Reason = \"invalid step\" }\n                            | Some(next, wanted) ->\n                                let outcome = try Ok(invoke model context c args system) with e -> Error e\n                                match outcome with\n                                | Error e -> Error { Step = n + 1; Reason = raised e }\n                                | Ok(result, after) ->\n                                    if c.ReturnsUnit || Scalar.equal result wanted then\n                                        go rest (shifted c indices) after next (n + 1)\n                                    else\n                                        Error { Step = n + 1; Reason = sprintf \"returned %s, expected %s\" (render result) (render wanted) }\n                with e -> Error { Step = n; Reason = raised e }\n            go steps model.StartIndices system expected 0)\n    with e -> Error { Step = 0; Reason = raised e }\n\nlet rec private halves n = if n = 0 then [] else n :: halves (n / 2)\n\nlet private removeRange (values: 'a list) start size =\n    let before, rest = List.splitAt start values\n    before @ List.skip (min size (List.length rest)) rest\n\nlet private smallerArgs (model: Model) (ds: Descriptor list) (args: Value list) =\n    [ for i, (d, arg) in List.indexed (List.zip ds args) do\n          for v in shrink d arg model.Table -> List.updateAt i v args ]\n\n/// Shrink candidates in the portable order: remove chunks of steps, then\n/// shrink each step's arguments, then the start arguments.\n[<CompiledName(\"Candidates\")>]\nlet candidates (model: Model) ((startArgs, steps): Run) : Run list =\n    let n = List.length steps\n    let drops =\n        [ for size in halves (n / 2) do\n              for start in 0 .. size .. n - 1 -> startArgs, removeRange steps start size ]\n    let args =\n        [ for k, (i, values) in List.indexed steps do\n              for smaller in smallerArgs model (command model i).Arguments values -> startArgs, List.updateAt k (i, smaller) steps ]\n    let starts = [ for smaller in smallerArgs model model.StartArguments startArgs -> smaller, steps ]\n    drops @ args @ starts\n\n/// The smallest failing run within a budget of attempts.\n[<CompiledName(\"Shrink\")>]\nlet rec shrinkRun (model: Model) (run: Run) (failure: Failure) (budget: int) : Run * Failure =\n    let rec next candidates budget =\n        match candidates with\n        | _ when budget = 0 -> run, failure\n        | [] -> run, failure\n        | candidate :: rest ->\n            let result =\n                match simulate model candidate with\n                | None -> Ok()\n                | Some _ -> execute model candidate\n            match result with\n            | Ok() -> next rest (budget - 1)\n            | Error found -> shrinkRun model candidate found (budget - 1)\n    next (candidates model run) budget\n\nlet private describeStep (name: string) (args: Value list) =\n    name + \"(\" + String.Join(\", \", args |> List.map render) + \")\"\n\n/// A run as text: start(...); command(...); ...\n[<CompiledName(\"Describe\")>]\nlet describe (model: Model) ((startArgs, steps): Run) =\n    String.Join(\"; \", describeStep \"start\" startArgs :: [ for i, args in steps -> describeStep (command model i).Name args ])\n\n/// The run's seed: given, LAWSPEC_SEED, or 0.\n[<CompiledName(\"Seed\")>]\nlet seed (given: BigInteger option) =\n    match given with\n    | Some n -> Random.seed n\n    | None ->\n        match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n        | null | \"\" -> Random.seed BigInteger.Zero\n        | text -> Random.seed (BigInteger.Parse text)\n\n/// How many cases, how long a run may be, how many shrink attempts, and\n/// the seed (otherwise LAWSPEC_SEED, or 0).\ntype Options =\n    { Cases: int\n      MaxLength: int\n      MaxShrinks: int\n      Seed: BigInteger option }\n\nlet defaults = { Cases = 100; MaxLength = 20; MaxShrinks = 2000; Seed = None }\n\nlet private seedValue (Random.Seed s) = s\n\n/// Check a model's sequential runs, with options.\n[<CompiledName(\"CheckWith\")>]\nlet checkWith (options: Options) (model: Model) =\n    require (options.Cases > 0) \"ModelRequiresCases\"\n    require (options.MaxLength >= 0) \"ModelInvalidLength\"\n    require (options.MaxShrinks >= 0) \"ModelInvalidShrinks\"\n    let start = seed options.Seed\n    let rec go n random =\n        if n < options.Cases then\n            let length, r1 = Random.below (BigInteger(options.MaxLength + 1)) random\n            let run, r2 = generateRun model r1 (int length) (1 + n % 8) true\n            match execute model run with\n            | Ok() -> go (n + 1) r2\n            | Error failure ->\n                let smaller, found = shrinkRun model run failure options.MaxShrinks\n                Fail.raiseWith \"ModelFailed\"\n                    (sprintf \"model %s: seed %d (LAWSPEC_SEED=%d replays it), case %d: %s; at step %d: %s\"\n                        model.Name (seedValue start) (seedValue start) n (describe model smaller) found.Step found.Reason)\n    go 0 start\n\n/// Check a model's sequential runs.\n[<CompiledName(\"Check\")>]\nlet check (model: Model) = checkWith defaults model\n"
dotnetSource "LawSpec.Testing/ModelParallel.fs" = "/// Concurrent model histories, generated from a valid sequential prefix.\n/// Every interleaving of the branches must be allowed by the reference.\n/// The calls run on the thread pool at once; a shared counter records each\n/// call's interval, and an order consistent with the model (and, for\n/// linearizability, with real time) must explain the results.\n/// ref:DEC-stateful-models-linearizability ref:herlihy-wing-linearizability\n/// ref:wing-gong-linearizability ref:DEC-portable-seeded-generation\nmodule LawSpec.Testing.ModelParallel\n\nopen System\nopen System.Numerics\nopen System.Threading\nopen System.Threading.Tasks\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Descriptors\nopen LawSpec.Testing.Model\n\n/// A case: a sequential prefix, then a branch of steps for each thread.\ntype Case = Run * (int * Value list) list list\n\n/// A call's interval on the shared clock and its outcome.\ntype Event = int64 * int64 * Result<Value, string>\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\nlet private states (model: Model.Model) (prefix: Run) = simulate model prefix\n\nlet private pending (branches: (int * Value list)[][]) (positions: int[]) =\n    [ for i in 0 .. branches.Length - 1 do\n          let k = positions.[i]\n          if k < branches.[i].Length then yield i, branches.[i].[k] ]\n\nlet private advance (positions: int[]) i =\n    let next = Array.copy positions\n    next.[i] <- next.[i] + 1\n    next\n\n/// Whether every interleaving of the branches is allowed by the reference.\n[<CompiledName(\"Allowed\")>]\nlet allowed (model: Model.Model) (((startArgs, _) as prefix, branches): Case) =\n    match states model prefix with\n    | None -> false\n    | Some ss ->\n        withCase model startArgs (fun context ->\n            let bs = branches |> List.map Array.ofList |> Array.ofList\n            let seen = System.Collections.Generic.HashSet<int list * Value>(HashIdentity.Structural)\n            let rec allOrders (positions: int[]) (state: Value) =\n                if not (seen.Add((List.ofArray positions, state))) then true\n                else\n                    pending bs positions\n                    |> List.forall (fun (i, (index, args)) ->\n                        match step (command model index) context args state with\n                        | None -> false\n                        | Some(next, _) -> allOrders (advance positions i) next)\n            allOrders (Array.zeroCreate bs.Length) (List.last ss))\n\nlet private generateBranch (model: Model.Model) (context: Context) random size count state =\n    let rec go random remaining state steps =\n        if remaining = 0 || model.Commands.Length = 0 then List.rev steps, random\n        else\n            let index, r1 = Random.below (BigInteger model.Commands.Length) random\n            let c = command model (int index)\n            let mutable r = r1\n            let args =\n                c.Arguments\n                |> List.map (fun d ->\n                    let v, next = generate d model.Table r size\n                    r <- next\n                    v)\n            match step c context args state with\n            | None -> go r (remaining - 1) state steps\n            | Some(next, _) -> go r (remaining - 1) next ((int index, args) :: steps)\n    go random count state []\n\nlet rec private trim (model: Model.Model) ((prefix, branches): Case) : Case =\n    if allowed model (prefix, branches) then prefix, branches\n    else\n        let length = branches |> List.map List.length |> List.max\n        let i = branches |> List.findIndex (fun b -> List.length b = length)\n        trim model (prefix, List.updateAt i (List.take (length - 1) branches.[i]) branches)\n\n/// A case drawn from a random state: a prefix of up to three steps, then a\n/// branch for each thread of one to the branch length steps.\n[<CompiledName(\"Generate\")>]\nlet generateCase (model: Model.Model) (random: Random.Seed) (size: int) (threads: int) (branchLength: int) : Case * Random.Seed =\n    let length, r1 = Random.below (BigInteger 4) random\n    let ((startArgs, _) as prefix), r2 = generateRun model r1 (int length) size false\n    match states model prefix with\n    | None -> (prefix, List.replicate threads []), r2\n    | Some ss ->\n        let branches, r3 =\n            withCase model startArgs (fun context ->\n                let mutable r = r2\n                let branches =\n                    [ for _ in 1 .. threads ->\n                          let n, next = Random.below (BigInteger branchLength) r\n                          let branch, after = generateBranch model context next size (int n + 1) (List.last ss)\n                          r <- after\n                          branch ]\n                branches, r)\n        trim model (prefix, branches), r3\n\nlet private perturb (random: Random.Seed) =\n    let choice, next = Random.below (BigInteger 4) random\n    if choice.IsZero then ()\n    elif choice.IsOne then Thread.Yield() |> ignore\n    else Thread.Sleep 1\n    next\n\nlet private raisedText (e: exn) = \"raised \" + e.GetType().Name + \": \" + e.Message\n\nlet private prefixRun (model: Model.Model) (context: Context) (steps: (int * Value list) list) (system: obj) (expected: Value) =\n    let rec go steps expected =\n        checkState model context system expected\n        match steps with\n        | [] -> expected\n        | (i, args) :: rest ->\n            let c = command model i\n            match step c context args expected with\n            | None -> fail \"ModelPrefixInvalid\" c.Name\n            | Some(next, wanted) ->\n                let result, _ = invoke model context c args system\n                if c.ReturnsUnit || Scalar.equal result wanted then go rest next\n                else fail \"ModelPrefixReturned\" (sprintf \"%s returned %s, expected %s\" c.Name (render result) (render wanted))\n    go steps expected\n\n/// Search the orders consistent with each branch's order (and, for\n/// linearizability, real time) for one the reference explains.\nlet rec private findOrder (model: Model.Model) (context: Context) (branches: (int * Value list) list list) (history: Event list list) (expected: Value) (finish: Value -> bool) =\n    let bs = branches |> List.map Array.ofList |> Array.ofList\n    let hs = history |> List.map Array.ofList |> Array.ofList\n    let linear = model.Consistency = \"linearizable\"\n    let seen = System.Collections.Generic.HashSet<int list * Value>(HashIdentity.Structural)\n    let rec visit (positions: int[]) (state: Value) =\n        if not (seen.Add((List.ofArray positions, state))) then false\n        else\n            match pending bs positions with\n            | [] -> finish state\n            | next ->\n                next\n                |> List.exists (fun (i, (index, args)) ->\n                    let called, _, result = hs.[i].[positions.[i]]\n                    let blocked =\n                        linear && (next |> List.exists (fun (j, _) ->\n                            let _, returned, _ = hs.[j].[positions.[j]]\n                            j <> i && returned < called))\n                    if blocked then false\n                    else\n                        let c = command model index\n                        match step c context args state with\n                        | None -> false\n                        | Some(next, wanted) ->\n                            let ignore = model.Consistency = \"eventual\" || c.ReturnsUnit\n                            let value = match result with Ok v -> v | Error _ -> Unit\n                            if ignore || Scalar.equal value wanted then visit (advance positions i) next else false)\n    visit (Array.zeroCreate bs.Length) expected\n\nlet private causal (model: Model.Model) (context: Context) branches (history: Event list list) expected system =\n    List.zip branches history\n    |> List.forall (fun (branch, events) ->\n        try\n            let last =\n                List.zip branch events\n                |> List.fold (fun state ((i, args), (_, _, result)) ->\n                    let c = command model i\n                    match step c context args state with\n                    | Some(next, wanted) ->\n                        let value = match result with Ok v -> v | Error _ -> Unit\n                        if c.ReturnsUnit || Scalar.equal value wanted then next else failwith \"inconsistent\"\n                    | None -> failwith \"inconsistent\") expected\n            checkState (withoutAbstraction model) context system last\n            true\n        with _ -> false)\n\nlet rec private foldKeys (model: Model.Model) context (groups: ((int * Value list) * Event) list list list) state (finish: Value -> bool) =\n    match groups with\n    | [] -> finish state\n    | parts :: rest ->\n        let branches = parts |> List.map (List.map fst)\n        let history = parts |> List.map (List.map snd)\n        findOrder model context branches history state (fun next -> foldKeys model context rest next finish)\n\nlet private byKey (model: Model.Model) context (branches: (int * Value list) list list) (history: Event list list) expected finish =\n    let n = List.length branches\n    let groups =\n        List.zip branches history\n        |> List.indexed\n        |> List.fold (fun (acc: Map<string, ((int * Value list) * Event) list list>) (i, (branch, events)) ->\n            List.zip branch events\n            |> List.fold (fun (groups: Map<string, ((int * Value list) * Event) list list>) (((index, args) as s), e) ->\n                let keyIndex = (command model index).Key.Value\n                let key = render (List.item keyIndex args)\n                let parts = defaultArg (groups.TryFind key) (List.replicate n [])\n                groups.Add(key, List.updateAt i (parts.[i] @ [ s, e ]) parts)) acc) Map.empty\n    let ordered =\n        groups |> Map.toList |> List.sortWith (fun (a, _) (b, _) -> Scalar.compareText a b) |> List.map snd\n    foldKeys model context ordered expected finish\n\n/// Whether a parallel history has an order consistent with the model.\n[<CompiledName(\"Consistent\")>]\nlet consistent (model: Model.Model) (context: Context) (branches: (int * Value list) list list) (history: Event list list) (expected: Value) (final: Value option) (system: obj) =\n    let finish (state: Value) =\n        try\n            let equal = match final with None -> true | Some actual -> Scalar.equal actual state\n            equal && (checkState (withoutAbstraction model) context system state; true)\n        with _ -> false\n    match model.Consistency with\n    | \"causal\" -> causal model context branches history expected system\n    | consistency ->\n        let canPartition =\n            consistency = \"linearizable\" && model.PerKey\n            && (branches |> List.concat |> List.forall (fun (i, _) -> (command model i).Key.IsSome))\n        if canPartition then byKey model context branches history expected finish\n        else findOrder model context branches history expected finish\n\n/// Run a case once, its branches at the same time, with scheduling\n/// perturbed from a shake value; Ok when an order explains the results.\n[<CompiledName(\"Execute\")>]\nlet execute (model: Model.Model) (((startArgs, steps), branches): Case) (shake: uint64) : Result<unit, string> =\n    try\n        withSystem model startArgs (List.length steps) (fun context system expected ->\n            let finalPrefix = prefixRun model context steps system expected\n            let clock = ref 0L\n            let gate = obj ()\n            let tick () = lock gate (fun () -> clock.Value <- clock.Value + 1L; clock.Value)\n            let runBranch (i: int) (branch: (int * Value list) list) =\n                let mutable random =\n                    Random.seed (BigInteger shake ^^^ (BigInteger(i + 1) * BigInteger 0x9e3779b97f4a7c15UL))\n                [ for index, args in branch ->\n                      let c = command model index\n                      random <- perturb random\n                      let called = tick ()\n                      let result =\n                          try\n                              let value, _ = invoke model context c args system\n                              Ok value\n                          with e -> Error(c.Name + \": \" + raisedText e)\n                      let returned = tick ()\n                      random <- perturb random\n                      (called, returned, result) ]\n            let tasks = branches |> List.mapi (fun i b -> Task.Run(fun () -> runBranch i b)) |> Array.ofList\n            (try Task.WaitAll(tasks |> Array.map (fun t -> t :> Task)) with _ -> ())\n            let history =\n                tasks\n                |> Array.map (fun t ->\n                    if t.IsFaulted then [ 0L, 0L, Error(raisedText t.Exception.InnerException) ] else t.Result)\n                |> List.ofArray\n            let errors = [ for events in history do for (_, _, r) in events do match r with Error e -> yield e | Ok _ -> () ]\n            match errors with\n            | e :: _ -> Error e\n            | [] ->\n                let final = model.Abstract |> Option.map (fun a -> callback a context [ systemState model system ])\n                if consistent model context branches history finalPrefix final system then Ok()\n                else\n                    let shown =\n                        history\n                        |> List.mapi (fun i events ->\n                            string (char (int 'A' + i)) + \": \"\n                            + String.Join(\", \", [ for (a, b, r) in events -> sprintf \"[%d,%d] %s\" a b (match r with Ok v -> render v | Error e -> e) ]))\n                    Error(\"no consistent order: \" + String.Join(\"; \", shown)))\n    with e -> Error(raisedText e)\n\n/// Shrink candidates: remove a prefix step, remove a branch step, then\n/// shrink a branch step's arguments.\n[<CompiledName(\"Candidates\")>]\nlet candidates (model: Model.Model) ((((startArgs, steps) as prefix), branches): Case) : Case list =\n    let prefixes = [ for i in 0 .. List.length steps - 1 -> (startArgs, List.removeAt i steps), branches ]\n    let drops =\n        [ for i, branch in List.indexed branches do\n              for k in 0 .. List.length branch - 1 -> prefix, List.updateAt i (List.removeAt k branch) branches ]\n    let smaller =\n        [ for i, branch in List.indexed branches do\n              for k, (index, values) in List.indexed branch do\n                  for a, (d, v) in List.indexed (List.zip (command model index).Arguments values) do\n                      for value in shrink d v model.Table ->\n                          prefix, List.updateAt i (List.updateAt k (index, List.updateAt a value values) branch) branches ]\n    prefixes @ drops @ smaller\n\nlet rec private repeats model case count (shake: uint64) =\n    if count = 0 then Ok()\n    else\n        match execute model case shake with\n        | Ok() -> repeats model case (count - 1) (shake + 1UL)\n        | error -> error\n\n/// The smallest case still failing within a budget of attempts.\n[<CompiledName(\"Shrink\")>]\nlet rec shrinkCase (model: Model.Model) (case: Case) (failure: string) (count: int) (budget: int) (shake: uint64) : Case * string =\n    let rec next candidates budget =\n        match candidates with\n        | _ when budget = 0 -> case, failure\n        | [] -> case, failure\n        | candidate :: rest ->\n            let found = if not (allowed model candidate) then Ok() else repeats model candidate count shake\n            match found with\n            | Ok() -> next rest (budget - 1)\n            | Error reason -> shrinkCase model candidate reason count (budget - 1) shake\n    next (candidates model case) budget\n\n/// A case as text: its prefix, then each branch, at the same time.\n[<CompiledName(\"Describe\")>]\nlet describeCase (model: Model.Model) ((prefix, branches): Case) =\n    let parts =\n        branches\n        |> List.mapi (fun i b ->\n            let shown =\n                match b with\n                | [] -> \"nothing\"\n                | _ -> (describe model ([], b)).Substring(\"start(); \".Length)\n            string (char (int 'A' + i)) + \": \" + shown)\n    let joined =\n        match parts with\n        | [] -> \"nothing\"\n        | [ only ] -> only\n        | _ -> String.Join(\", \", List.take (parts.Length - 1) parts) + \" and \" + List.last parts\n    describe model prefix + \", then \" + joined + \" at the same time\"\n\n/// How many cases, how many runs of each, the shrink budget, the threads\n/// and the longest branch.\ntype Options =\n    { Cases: int\n      Repeats: int\n      MaxShrinks: int\n      Threads: int\n      BranchLength: int\n      Seed: BigInteger option }\n\nlet defaults = { Cases = 50; Repeats = 10; MaxShrinks = 300; Threads = 3; BranchLength = 5; Seed = None }\n\nlet private seedValue (Random.Seed s) = s\n\n/// Check a shared model's concurrent histories, with options.\n[<CompiledName(\"CheckWith\")>]\nlet checkWith (options: Options) (model: Model.Model) =\n    if not model.Shared then fail \"ModelNotShared\" model.Name\n    if options.Cases <= 0 || options.Repeats <= 0 || options.Threads <= 0 || options.BranchLength <= 0 || options.MaxShrinks < 0 then\n        fail \"ModelInvalidOptions\" model.Name\n    let start = Model.seed options.Seed\n    let rec go n random =\n        if n < options.Cases then\n            let case, r1 = generateCase model random (1 + n % 8) options.Threads options.BranchLength\n            let shake, r2 = Random.next r1\n            match repeats model case options.Repeats shake with\n            | Ok() -> go (n + 1) r2\n            | Error failure ->\n                let smaller, found = shrinkCase model case failure (max 2 (options.Repeats / 2)) options.MaxShrinks shake\n                Fail.raiseWith \"ModelInconsistent\"\n                    (sprintf \"model %s is not %s: seed %d (LAWSPEC_SEED=%d replays it), case %d, shake %d: %s; %s\"\n                        model.Name model.Consistency (seedValue start) (seedValue start) n shake (describeCase model smaller) found)\n    go 0 (Random.Seed(seedValue start ^^^ 0x5bd1e995UL))\n\n/// Check a shared model's concurrent histories.\n[<CompiledName(\"Check\")>]\nlet check (model: Model.Model) = checkWith defaults model\n"
dotnetSource "LawSpec.Testing/Property.fs" = "/// Running a law's property: draw cases from a seed, run each, and shrink the\n/// first failure to a small counterexample. One seed per run is printed with\n/// any failure, and LAWSPEC_SEED replays it. ref:DEC-portable-seeded-generation\n/// ref:DEC-never-pass-vacuously\nmodule LawSpec.Testing.Property\n\nopen System\nopen System.Numerics\nopen LawSpec.Runtime\n\n/// How many cases to run, how many discards a case may take, and how many\n/// shrink steps a failure may take.\ntype Settings =\n    { Cases: int\n      MaxAttempts: int\n      MaxShrinks: int }\n\nlet private random = System.Random.Shared\n\n/// The run's seed: LAWSPEC_SEED, or a fresh one.\nlet runSeed () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n    | null | \"\" -> BigInteger(random.NextInt64())\n    | text -> BigInteger.Parse text\n\nlet private render (values: Value list) =\n    \"(\" + String.Join(\", \", values |> List.map Recorded.renderPlain) + \")\"\n\nlet private failureOf (property: Value list -> Value) (values: Value list) : exn option =\n    try\n        match property values with\n        | Bool true -> None\n        | Bool false -> Some(LawSpecException(\"PropertyFalse\", \"\") :> exn)\n        | other -> Some(LawSpecException(\"NonBooleanProperty\", sprintf \"%A\" other) :> exn)\n    with\n    | :? LawSpecException as e when e.Code = \"StrategyOutsideRefinement\" || e.Code = \"StrategyDiscards\" -> raise e\n    | e -> Some e\n\n/// Check a property over a generator of its inputs.\nlet check (label: string) (settings: Settings) (gen: Gen<Value list>) (property: Value list -> Value) =\n    let seed = runSeed ()\n    let mutable state = Random.seed seed\n    let mutable passed = 0\n    let mutable failure = None\n    while failure.IsNone && passed < settings.Cases do\n        let size = min 99 passed\n        let mutable drawn = None\n        let mutable discards = 0\n        while drawn.IsNone do\n            let s1, s2 = Random.split state\n            state <- s2\n            match Gen.run gen s1 size with\n            | Some tree -> drawn <- Some tree\n            | None ->\n                discards <- discards + 1\n                if discards > settings.MaxAttempts then\n                    Harness.abort \"CannotSatisfy\"\n                        (sprintf \"%s: no input satisfied the law's domain after %d attempts (seed %O)\" label settings.MaxAttempts seed)\n        let tree = drawn.Value\n        match failureOf property tree.Value with\n        | None -> passed <- passed + 1\n        | Some error -> failure <- Some(tree, error)\n    match failure with\n    | None -> ()\n    | Some(tree, error) ->\n        let mutable best = tree\n        let mutable bestError = error\n        let mutable steps = 0\n        let mutable searching = true\n        while searching && steps < settings.MaxShrinks do\n            let next =\n                best.Children\n                |> Seq.truncate (settings.MaxShrinks * 4)\n                |> Seq.tryPick (fun child -> failureOf property child.Value |> Option.map (fun e -> child, e))\n            match next with\n            | Some(child, e) ->\n                best <- child\n                bestError <- e\n                steps <- steps + 1\n            | None -> searching <- false\n        let message =\n            sprintf \"%s failed after %d passing case(s) and %d shrink(s): counterexample %s; seed %O (LAWSPEC_SEED=%O replays it)\\n%s\"\n                label passed steps (render best.Value) seed seed bestError.Message\n        raise (LawSpecException(\"PropertyFailed\", message, [], bestError))\n\n/// A law's generation settings.\nlet settings (cases: int) (attempts: int) (shrinks: int) = { Cases = cases; MaxAttempts = attempts; MaxShrinks = shrinks }\n\n/// What generation reads: the schema, the case's symbols and the discard budget.\nlet generation (schema: Schema.Schema) (symbols: Scalar.SymbolContext) (attempts: int) : Generators.Context =\n    { Schema = schema; Symbols = symbols; Factories = Map.empty; Attempts = attempts }\n\n/// Each boundary case, in order; the first that fails names its position.\nlet boundaries (label: string) (cases: Value list list) (law: Value list -> Value) =\n    cases\n    |> List.iteri (fun i values ->\n        try\n            match law values with\n            | Bool true -> ()\n            | other -> Fail.raiseWith \"ContractFailed\" (sprintf \"%s boundary %d returned %A\" label i other)\n        with\n        | :? LawSpecException as e ->\n            raise (LawSpecException(\"BoundaryFailed\", sprintf \"%s boundary %d %s: %s\" label i (render values) e.Message, [], e)))\n\n/// A strategy's value must lie inside the input's refinement.\nlet checkDrawn (strategy: string) (input: string) (value: Value) (holds: bool) =\n    if holds then value\n    else Harness.abort \"StrategyOutsideRefinement\" (sprintf \"strategy %s produced %s for %s, outside the input's refinement\" strategy (Recorded.renderPlain value) input)\n\n/// A strategy's draw that keeps only values a predicate accepts.\nlet suchThat (strategy: string) (predicate: Value -> bool) (limit: int) (gen: Gen<Value>) =\n    Gen.suchThat predicate limit (fun () -> Harness.abort \"StrategyDiscards\" (sprintf \"strategy %s discarded %d values\" strategy limit)) gen\n"
dotnetSource "LawSpec.Testing/Resources.fs" = "/// Resources a law's cases use: acquired before a case and released after\n/// it, even when it fails, or shared across a unit's cases (`share R per\n/// unit`): acquired once, reset before each use, and released when the run\n/// ends. A resource that is not concurrent is used by one case at a time.\n/// ref:REQ-law-primitives ref:REQ-harness-units\nmodule LawSpec.Testing.Resources\n\nopen System\nopen System.Collections.Concurrent\nopen System.Threading\nopen LawSpec.Runtime\n\nlet private cleanupFailure (detail: string) (inner: exn) =\n    let failure = LawSpecException(\"TestCleanupFailed\", detail + \": \" + inner.Message, [], inner)\n    Harness.markHarnessFailure failure\n    failure\n\n/// A resource for one case: the body's outcome stands unless releasing the\n/// resource fails, which fails the case.\n[<CompiledName(\"WithResource\")>]\nlet withResource (acquire: unit -> Value) (release: Value -> Value) (body: Value -> Value) : Value =\n    let value = acquire ()\n    let outcome = try Choice1Of2(body value) with e -> Choice2Of2 e\n    let cleanup = try release value |> ignore; None with e -> Some e\n    match outcome, cleanup with\n    | Choice1Of2 result, None -> result\n    | Choice2Of2 e, None -> raise e\n    | Choice1Of2 _, Some c -> raise (cleanupFailure \"a resource's release failed\" c)\n    | Choice2Of2 e, Some c -> raise (cleanupFailure (\"a resource's release failed after the case failed (\" + e.Message + \")\") c)\n\ntype private Shared(acquire: unit -> Value, reset: Value -> Value, release: Value -> Value, concurrent: bool) =\n    let gate = new SemaphoreSlim(1, 1)\n    let users = new SemaphoreSlim((if concurrent then Int32.MaxValue else 1), (if concurrent then Int32.MaxValue else 1))\n    let mutable value: Value option = None\n    let mutable leases = 0\n    member _.Checkout() =\n        users.Wait()\n        gate.Wait()\n        try\n            try\n                match value with\n                | None -> value <- Some(acquire ())\n                | Some v when leases = 0 -> reset v |> ignore\n                | Some _ -> ()\n                leases <- leases + 1\n                value.Value\n            with _ ->\n                users.Release() |> ignore\n                reraise ()\n        finally\n            gate.Release() |> ignore\n    member _.Checkin() =\n        gate.Wait()\n        leases <- leases - 1\n        gate.Release() |> ignore\n        users.Release() |> ignore\n    member _.Release() =\n        match value with\n        | Some v ->\n            value <- None\n            release v |> ignore\n        | None -> ()\n\nlet private shared = ConcurrentDictionary<string, Shared>()\n\nlet private released =\n    lazy\n        AppDomain.CurrentDomain.ProcessExit.Add(fun _ ->\n            for KeyValue(key, entry) in shared do\n                try entry.Release()\n                with e -> eprintfn \"LawSpec: releasing the shared resource %s failed: %s\" key e.Message)\n\n/// A resource shared by a unit's cases.\n[<CompiledName(\"WithShared\")>]\nlet withShared (key: string) (acquire: unit -> Value) (reset: Value -> Value) (release: Value -> Value) (concurrent: bool) (body: Value -> Value) : Value =\n    released.Force()\n    let entry = shared.GetOrAdd(key, fun _ -> Shared(acquire, reset, release, concurrent))\n    let value = entry.Checkout()\n    try body value finally entry.Checkin()\n"
dotnetSource "LawSpec.Testing/Schedule.fs" = "/// How a harness runs a unit's laws on xUnit: `order random` puts a unit's\n/// tests in an order the run's seed chooses (the same seed, the same order),\n/// and `parallel` lets them run at once, while other units' tests run one at\n/// a time. ref:REQ-harness-units ref:DEC-portable-seeded-generation\nnamespace LawSpec.Testing\n\nopen System\nopen System.Numerics\nopen System.Security.Cryptography\nopen System.Text\nopen Xunit.v3\n\nmodule Schedule =\n    let private chosen = lazy (BigInteger(RandomNumberGenerator.GetBytes 8 |> Array.append [| 0uy |] |> Array.rev))\n\n    /// The run's seed for ordering: LAWSPEC_SEED, or one chosen once per run.\n    let seed () =\n        match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n        | null | \"\" -> chosen.Value\n        | text -> BigInteger.Parse text\n\n    /// Items in the order a seed chooses for a unit: by the hash of the seed,\n    /// the unit and each item's position.\n    let order (unitName: string) (items: 'a list) =\n        let s = seed ()\n        eprintfn \"order random seed %O (%s): LAWSPEC_SEED=%O replays this order\" s unitName s\n        items\n        |> List.mapi (fun i item ->\n            let key = SHA256.HashData(Encoding.UTF8.GetBytes(s.ToString() + \"\\u0000\" + unitName + \"\\u0000\" + string (i + 1)))\n            key, i, item)\n        |> List.sortWith (fun (a: byte[], i, _) (b, j, _) ->\n            match ReadOnlySpan<byte>(a).SequenceCompareTo(ReadOnlySpan<byte>(b)) with\n            | 0 -> compare i j\n            | c -> c)\n        |> List.map (fun (_, _, item) -> item)\n\n/// xUnit's order for a unit with `order random`: its tests in declaration\n/// order, then shuffled by the run's seed.\ntype SeededOrder() =\n    interface ITestCaseOrderer with\n        member _.OrderTestCases<'T when 'T :> Xunit.Sdk.ITestCase>(testCases: Collections.Generic.IReadOnlyCollection<'T>) =\n            let cases = List.ofSeq testCases\n            let unitName =\n                match cases with\n                | c :: _ -> c.TestClassName\n                | [] -> \"\"\n            let declared =\n                cases |> List.sortBy (fun c -> (if c.TestMethodMetadataToken.HasValue then c.TestMethodMetadataToken.Value else 0), c.TestCaseDisplayName)\n            ResizeArray(Schedule.order unitName declared) :> Collections.Generic.IReadOnlyCollection<'T>\n"
dotnetSource "LawSpec.Testing/Search.fs" = "/// LawSpec's descriptor search, apart from generation and shrinking: the\n/// portable seeded climb of a `target` (ten starting points, sixty rounds, at\n/// most twenty-four moves a round and four hundred checks), and the failure\n/// database that keeps a failing law's inputs (LAWSPEC_FAILURES) and replays\n/// them first on the next run. ref:REQ-harness-units\n/// ref:DEC-portable-seeded-generation ref:DEC-shrink-within-domain\nmodule LawSpec.Testing.Search\n\nopen System\nopen System.IO\nopen System.Numerics\nopen System.Security.Cryptography\nopen System.Text\nopen System.Text.Json\nopen System.Text.Json.Nodes\nopen LawSpec.Runtime\n\nlet private inputFile (law: string) =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_FAILURES\" with\n    | null | \"\" -> None\n    | directory ->\n        let name = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes law)).ToLowerInvariant()\n        Some(Path.Combine(directory, \"inputs\", name + \".json\"))\n\n/// Keep a failing case's inputs, encoded on the canonical wire.\n[<CompiledName(\"Remember\")>]\nlet remember (law: string) (descriptors: string list) (values: Value list) =\n    match inputFile law with\n    | None -> ()\n    | Some file ->\n        let inputs = JsonArray()\n        for descriptor, value in List.zip descriptors values do\n            let table, d = Descriptors.fromText descriptor\n            inputs.Add(JsonValue.Create(Convert.ToHexString(Descriptors.encode d value table).ToLowerInvariant()))\n        let record = JsonObject()\n        record.[\"law\"] <- JsonValue.Create(law)\n        record.[\"inputs\"] <- inputs\n        Directory.CreateDirectory(Path.GetDirectoryName file) |> ignore\n        let temporary = file + \".\" + string Environment.ProcessId + \".\" + Guid.NewGuid().ToString(\"N\") + \".tmp\"\n        try\n            File.WriteAllText(temporary, record.ToJsonString())\n            File.Move(temporary, file, true)\n        finally\n            if File.Exists temporary then File.Delete temporary\n\nlet private keep law descriptors values =\n    try remember law descriptors values\n    with e -> eprintfn \"LawSpec could not save inputs for %s: %s\" law e.Message\n\n/// Run a case, keeping its inputs when it fails.\n[<CompiledName(\"Guard\")>]\nlet guard (law: string) (descriptors: string list) (values: Value list) (check: unit -> Value) : Value =\n    try\n        match check () with\n        | Bool false ->\n            keep law descriptors values\n            Bool false\n        | result -> result\n    with _ ->\n        keep law descriptors values\n        reraise ()\n\n/// Replay the kept failing inputs of a law, if any, before its generated\n/// cases; a repaired or obsolete one is removed.\n[<CompiledName(\"Replay\")>]\nlet replay (law: string) (descriptors: string list) (check: Value list -> Value option) =\n    match inputFile law with\n    | None -> ()\n    | Some file when not (File.Exists file) -> ()\n    | Some file ->\n        let values =\n            try\n                let record = JsonNode.Parse(File.ReadAllText file)\n                if record.[\"law\"].GetValue<string>() <> law then None\n                else\n                    let inputs = record.[\"inputs\"].AsArray() |> Seq.map (fun n -> n.GetValue<string>()) |> List.ofSeq\n                    Some(List.map2 (fun descriptor (hex: string) ->\n                        let table, d = Descriptors.fromText descriptor\n                        Descriptors.decode d (Convert.FromHexString hex) table) descriptors inputs)\n            with _ -> None\n        match values with\n        | None -> eprintfn \"%s: discarding incompatible saved inputs\" law\n        | Some values ->\n            eprintfn \"%s: replaying the failing inputs kept in .lawspec/failures\" law\n            match check values with\n            | Some(Bool false) -> Fail.raiseWith \"ReplayFailed\" law\n            | _ -> ()\n        File.Delete file\n\nlet private bounds (d: Descriptors.Descriptor) =\n    let number = function\n        | Descriptors.Number n -> Some n\n        | _ -> None\n    match d with\n    | Descriptors.Forms [ _; _; lo; hi ] ->\n        match number lo, number hi with\n        | None, None -> BigInteger(-1000000), BigInteger 1000000\n        | None, Some h -> BigInteger.Min(BigInteger(-1000000), h - BigInteger 2000000), h\n        | Some l, None -> l, BigInteger.Max(BigInteger 1000000, l + BigInteger 2000000)\n        | Some l, Some h -> l, h\n    | _ -> BigInteger.Zero, BigInteger.Zero\n\nlet private distinct (values: 'a list) =\n    values |> List.fold (fun acc v -> if List.contains v acc then acc else acc @ [ v ]) []\n\n/// Each move changes one integer leaf, within its wire bounds.\nlet rec private moves (d: Descriptors.Descriptor) (value: Value) table : Value list =\n    match Descriptors.resolve d table, value with\n    | (Descriptors.Forms [ Descriptors.Atom \"int\"; _; _; _ ] as resolved), Int n ->\n        let lo, hi = bounds resolved\n        let two = BigInteger 2\n        [ n + BigInteger.One; n - BigInteger.One; n * two; BigInteger.Divide(n, two)\n          n + BigInteger.Divide(hi - n, two); n - BigInteger.Divide(n - lo, two) ]\n        |> List.filter (fun x -> x <> n && x >= lo && x <= hi)\n        |> distinct\n        |> List.map Int\n    | Descriptors.Forms [ Descriptors.Atom \"list\"; item ], List items ->\n        fieldMoves (items |> List.map (fun _ -> item)) items table |> List.map List\n    | Descriptors.Forms [ Descriptors.Atom \"maybe\"; item ], Data(\"Maybe::Just\" as tag, [ v ]) ->\n        moves item v table |> List.map (fun c -> Data(tag, [ c ]))\n    | Descriptors.Forms [ Descriptors.Atom \"either\"; left; right ], Data(tag, [ v ]) ->\n        moves (if tag = \"Either::Left\" then left else right) v table |> List.map (fun c -> Data(tag, [ c ]))\n    | Descriptors.Forms(Descriptors.Atom \"data\" :: _ :: constructors), Data(tag, values) ->\n        let types =\n            constructors\n            |> List.pick (function\n                | Descriptors.Forms(Descriptors.Atom \"ctor\" :: name :: ds) when\n                    (match name with Descriptors.Quoted s | Descriptors.Atom s -> s = tag | _ -> false) -> Some ds\n                | _ -> None)\n        fieldMoves types values table |> List.map (fun cs -> Data(tag, cs))\n    | _ -> []\n\nand private fieldMoves ds values table =\n    match ds, values with\n    | d :: ds, v :: vs ->\n        (moves d v table |> List.map (fun c -> c :: vs)) @ (fieldMoves ds vs table |> List.map (fun cs -> v :: cs))\n    | _ -> []\n\nlet rec private inputMoves (tables: (Map<string, Descriptors.Descriptor> * Descriptors.Descriptor) list) (values: Value list) =\n    match tables, values with\n    | (table, d) :: tables, v :: vs ->\n        (moves d v table |> List.map (fun c -> c :: vs)) @ (inputMoves tables vs |> List.map (fun tail -> v :: tail))\n    | _ -> []\n\ntype internal Climb =\n    { Tried: int\n      Accepted: int\n      Best: Value option\n      Values: Value list option }\n\nexception internal SearchFailed of exn * Climb * Value list\n\n/// Climb towards the highest score of a law's `target`, from the run's seed.\n/// The check gives None for inputs outside the law's domain, or the score.\n[<CompiledName(\"Climb\")>]\nlet climb (law: string) (descriptors: string list) (check: Value list -> Value option) =\n    let seed =\n        match Environment.GetEnvironmentVariable \"LAWSPEC_SEED\" with\n        | null | \"\" -> BigInteger.Zero\n        | text -> BigInteger.Parse text\n    let tables = descriptors |> List.map Descriptors.fromText\n    let generate (s: BigInteger) =\n        let mutable state = Random.seed s\n        [ for table, d in tables ->\n              let v, next = Descriptors.generate d table state 8\n              state <- next\n              v ]\n    let attempt (values: Value list) (state: Climb) =\n        if state.Tried >= 400 then false, state\n        else\n            let next = { state with Tried = state.Tried + 1 }\n            let outcome = try Choice1Of2(check values) with e -> Choice2Of2 e\n            match outcome with\n            | Choice2Of2 e -> raise (SearchFailed(e, next, values))\n            | Choice1Of2 None -> false, next\n            | Choice1Of2(Some score) ->\n                if Harness.higher score state.Best then\n                    true, { next with Accepted = next.Accepted + 1; Best = Some score; Values = Some values }\n                else false, { next with Accepted = next.Accepted + 1 }\n    let publish outcome (state: Climb) =\n        let best = state.Best |> Option.map Harness.scoreText\n        printfn \"%s: targeted search tried %d case(s)%s\" law state.Tried (match best with Some b -> \"; best score \" + b | None -> \"\")\n        let search = JsonObject()\n        search.[\"seed\"] <- JsonValue.Create(seed.ToString())\n        search.[\"tried\"] <- JsonValue.Create(state.Tried)\n        search.[\"accepted\"] <- JsonValue.Create(state.Accepted)\n        search.[\"best\"] <- (match best with Some b -> JsonValue.Create(b) :> JsonNode | None -> null)\n        Harness.record [ \"search\", (search :> JsonNode); \"outcome\", (JsonValue.Create(outcome: string) :> JsonNode) ]\n    try\n        let mutable state = { Tried = 0; Accepted = 0; Best = None; Values = None }\n        for k in 0 .. 9 do\n            state <- snd (attempt (generate (seed + BigInteger k)) state)\n        let mutable step = 0\n        while step < 60 && state.Tried < 400 do\n            let candidates =\n                match state.Values with\n                | None -> []\n                | Some values -> inputMoves tables values |> List.truncate 24\n            let mutable rose = false\n            for candidate in candidates do\n                let rising, next = attempt candidate state\n                rose <- rose || rising\n                state <- next\n            if not rose then state <- snd (attempt (generate (seed + BigInteger 1000 + BigInteger step)) state)\n            step <- step + 1\n        publish \"passed\" state\n    with SearchFailed(e, state, values) ->\n        keep law descriptors values\n        (try publish \"failed\" state with r -> eprintfn \"LawSpec search statistics failed for %s: %s\" law r.Message)\n        let inputs =\n            List.map2 (fun (table, d) v -> Convert.ToHexString(Descriptors.encode d v table)) tables values\n        raise (LawSpecException(\"TargetFailed\", sprintf \"%s (seed %O, inputs %s): %s\" law seed (String.Join(\", \", inputs)) e.Message, [], e))\n"
dotnetSource "LawSpec.Testing/Supervision.fs" = "/// Supervision evidence: the generated check of a program with supervisors\n/// exercises real trees of the runtime's actors, every restart strategy and\n/// lifetime, restart budgets and escalation, links, committed checkpoints\n/// and stable mailboxes. ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\nmodule LawSpec.Testing.Supervision\n\nopen System\nopen System.Threading\nopen LawSpec.Runtime\nopen LawSpec.Runtime.Actors\n\nlet private failure (label: string) (expected: obj) (actual: obj) : 'a =\n    Fail.raiseWith \"SupervisionFailed\" (sprintf \"%s: expected %A, actual %A\" label expected actual)\n\nlet private expect (label: string) (expected: 'a) (actual: 'a) =\n    if expected <> actual then failure label (box expected) (box actual)\n\nlet private counter () = actor (fun () -> box 0) (fun _ -> box 0)\nlet private counters names = names |> List.map (fun n -> n, Permanent, counter ())\nlet private tree strategy limit children body = withSpec (supervisor strategy limit 10_000_000L children) body\nlet private childrenOf sup names = names |> List.map (child sup)\nlet private value (h: Handle) = unbox<int> (state h)\nlet private states handles = handles |> List.map value\nlet private bump (h: Handle) = unbox<int> (call h (fun s -> let n = unbox<int> s + 1 in box n, box n))\n\nlet private failCall (h: Handle) =\n    match (try Choice1Of2(call h (fun _ -> raise (InvalidOperationException \"supervision probe\"))) with e -> Choice2Of2 e) with\n    | Choice2Of2(:? LawSpecException as e) when e.Code = \"ActorCrashed\" && (e.InnerException :? InvalidOperationException) -> ()\n    | other -> failure \"failing handler\" (box \"ActorCrashed\") (box other)\n\nlet private stopped (h: Handle) =\n    match (try Choice1Of2(state h) with e -> Choice2Of2 e) with\n    | Choice2Of2(:? LawSpecException as e) when e.Code = \"ActorStopped\" -> ()\n    | other -> failure \"stopped actor\" (box \"ActorStopped\") (box other)\n\nlet private crashed (inbox: Inbox) (h: Handle) =\n    match receiveEvent inbox h 2000 with\n    | Some(Crashed _) -> ()\n    | other -> failure \"crash monitor\" (box \"Crashed\") (box other)\n\nlet private waitFor (label: string) (signal: ManualResetEventSlim) =\n    if not (signal.Wait 2000) then failure label (box \"signal\") (box \"timeout\")\n\nlet private strategies () =\n    for strategy, expected in [ OneForOne, [ 1; 0; 1 ]; OneForAll, [ 0; 0; 0 ]; RestForOne, [ 1; 0; 0 ] ] do\n        tree strategy 5 (counters [ \"a\"; \"b\"; \"c\" ]) (fun sup ->\n            let actors = childrenOf sup [ \"a\"; \"b\"; \"c\" ]\n            let before = actors |> List.map worker\n            for a in actors do bump a |> ignore\n            expect \"three children\" 3 (List.length (children sup))\n            failCall actors.[1]\n            expect (sprintf \"%A\" strategy) expected (states actors)\n            let after = actors |> List.map worker\n            expect (sprintf \"%A replaced workers\" strategy) (expected |> List.map (fun v -> v = 0)) (List.map2 (<>) before after))\n\nlet private lifetimes () =\n    tree OneForOne 5 [ \"p\", Permanent, counter (); \"t\", Transient, counter (); \"x\", Temporary, counter () ] (fun sup ->\n        let p, t, x = child sup \"p\", child sup \"t\", child sup \"x\"\n        bump p |> ignore\n        stop p\n        expect \"permanent normal stop\" 0 (value p)\n        bump t |> ignore\n        failCall t\n        expect \"transient crash\" 0 (value t)\n        stop t\n        stopped t\n        failCall x\n        stopped x\n        expect \"remaining children\" [ \"p\" ] (children sup |> List.map fst))\n\nlet private limits () =\n    tree OneForOne 2 (counters [ \"a\"; \"b\" ]) (fun sup ->\n        let a, b = child sup \"a\", child sup \"b\"\n        let inbox = Inbox()\n        monitor sup inbox\n        for _ in 1..3 do failCall a\n        stopped b\n        crashed inbox sup\n        expect \"one limit notification\" true (receiveEvent inbox sup 0 |> Option.isNone))\n\nlet private escalation () =\n    let inner = supervisor OneForOne 1 10_000_000L (counters [ \"a\"; \"b\" ])\n    tree OneForOne 5 [ \"inner\", Permanent, inner; \"c\", Permanent, counter () ] (fun sup ->\n        let innerHandle, c = child sup \"inner\", child sup \"c\"\n        let a, b = child innerHandle \"a\", child innerHandle \"b\"\n        let old = worker innerHandle\n        bump b |> ignore\n        bump c |> ignore\n        failCall a\n        failCall a\n        expect \"escalated children\" [ 0; 0; 1 ] (states [ a; b; c ])\n        expect \"replaced inner supervisor\" true (old <> worker innerHandle)\n        expect \"outer restart count\" 1 (restartCount sup)\n        expect \"fresh inner budget\" 0 (restartCount innerHandle))\n\nlet private links () =\n    withSpec (counter ()) (fun a ->\n        withSpec (counter ()) (fun b ->\n            link a b\n            let inbox = Inbox()\n            monitor b inbox\n            failCall a\n            crashed inbox b\n            stopped b))\n    tree OneForOne 10 (counters [ \"a\"; \"b\"; \"c\" ]) (fun sup ->\n        let actors = childrenOf sup [ \"a\"; \"b\"; \"c\" ]\n        let a, b, c = actors.[0], actors.[1], actors.[2]\n        link a b\n        link b c\n        link c a\n        let inbox = Inbox()\n        for x in actors do\n            bump x |> ignore\n            monitor x inbox\n        failCall a\n        for x in actors do crashed inbox x\n        let deadline = DateTime.UtcNow.AddSeconds 2.0\n        while restartCount sup < 3 && DateTime.UtcNow < deadline do Thread.Sleep 1\n        expect \"link cycle\" [ 0; 0; 0 ] (states actors)\n        expect \"one restart per linked actor\" 3 (restartCount sup))\n\nlet private checkpointAndMailbox () =\n    let spec = actor (fun () -> box 0) id\n    tree OneForOne 5 [ \"a\", Permanent, spec ] (fun sup ->\n        let a = child sup \"a\"\n        bump a |> ignore\n        failCall a\n        expect \"committed checkpoint\" 1 (value a)\n        let entered = new ManualResetEventSlim()\n        let finish = new ManualResetEventSlim()\n        let inbox = Inbox()\n        monitor a inbox\n        let w = worker a\n        try\n            tell a (fun s ->\n                entered.Set()\n                finish.Wait()\n                box (), box (unbox<int> s + 10))\n            waitFor \"mailbox handler started\" entered\n            tell a (fun s -> box (), box (unbox<int> s + 2))\n            kill a\n            crashed inbox a\n            expect \"queued tell after an external kill\" 3 (value a)\n            expect \"stable mailbox handle\" a (child sup \"a\")\n            expect \"replaced killed worker\" true (w <> worker a)\n        finally finish.Set())\n\nlet private queuedSiblingRestart strategy =\n    let restored = ref None\n    let sibling = actor (fun () -> box 0) (fun s -> restored.Value <- Some(unbox<int> s); box 0)\n    tree strategy 5 [ \"a\", Permanent, counter (); \"b\", Permanent, sibling ] (fun sup ->\n        let a, b = child sup \"a\", child sup \"b\"\n        let entered = new ManualResetEventSlim()\n        let finish = new ManualResetEventSlim()\n        let queued = ref None\n        try\n            tell b (fun s ->\n                entered.Set()\n                finish.Wait()\n                box (), box (unbox<int> s + 1))\n            waitFor \"sibling started\" entered\n            tell b (fun s -> queued.Value <- Some(unbox<int> s); box (), box (unbox<int> s + 3))\n            tell a (fun _ -> raise (InvalidOperationException \"supervision probe\"))\n            let deadline = DateTime.UtcNow.AddSeconds 2.0\n            while restartCount sup = 0 do\n                if DateTime.UtcNow > deadline then failure \"restart admitted\" (box true) (box false)\n                Thread.Sleep 1\n            // This tell follows the restart; the two accepted earlier belong\n            // to the old checkpoint, and their order survives the restart.\n            tell b (fun s -> box (), box (unbox<int> s + 10))\n            finish.Set()\n            expect (sprintf \"%A post-restart tell\" strategy) 10 (value b)\n            expect (sprintf \"%A queued checkpoint\" strategy) (Some 1) queued.Value\n            expect (sprintf \"%A restart checkpoint\" strategy) (Some 4) restored.Value\n        finally finish.Set())\n\n/// The supervision check: fails with SupervisionFailed naming what broke.\n[<CompiledName(\"Check\")>]\nlet check () =\n    withSpec (counter ()) (fun a ->\n        expect \"initial increment\" 1 (bump a)\n        failCall a\n        stopped a)\n    strategies ()\n    lifetimes ()\n    limits ()\n    escalation ()\n    links ()\n    checkpointAndMailbox ()\n    for strategy in [ OneForAll; RestForOne ] do queuedSiblingRestart strategy\n"
